import React, { useState } from 'react';
import { useAppState } from '../../app/providers';
import { ChevronLeft, ChevronRight, Plus, BoxSelect, CalendarDays, LayoutList, Calendar as CalendarIcon } from 'lucide-react';
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";
import { ConfirmationModal } from '../../common/components';
import toast from 'react-hot-toast';

const CalendarGrid = React.lazy(() => import('./v2/CalendarGrid'));
const CalendarMonthView = React.lazy(() => import('./v2/CalendarMonthView'));
const CalendarListView = React.lazy(() => import('./v2/CalendarListView'));
const BookingManagerModal = React.lazy(() => import('./v2/BookingManagerModal'));


const cn = (...inputs) => twMerge(clsx(inputs));

export default function CalendarV2Page() {
    const {
        bookingsV2,
        slotsV2,
        allSlotsV2,
        calendarCourts,
        addBookingV2,
        addSlotToBookingV2,
        removeSlotV2,
        updateBookingPaymentV2,
        updateBookingRenterV2,
        updateBookingV2,
        toggleSlotPaymentV2,
        markAllSlotsPaidV2,
        markBookingFreeV2,
        deleteBookingV2,
        bulkUpdateSlotsV2, // Added import
        fetchBookingsForRange, // New action
        settings
    } = useAppState(s => s);

    const [currentDate, setCurrentDate] = useState(new Date());
    const [viewMode, setViewMode] = useState("list"); // 'day', 'month', 'list'

    // --- DATA SYNCING ---
    const fetchMonthData = React.useCallback(() => {
        const y = currentDate.getFullYear();
        const m = currentDate.getMonth();
        const start = new Date(y, m, 1);
        const end = new Date(y, m + 1, 0); // Last day of month

        // Format YYYY-MM-DD
        const sStr = start.toLocaleDateString('en-CA');
        const eStr = end.toLocaleDateString('en-CA');

        fetchBookingsForRange(sStr, eStr);
    }, [currentDate, fetchBookingsForRange]);

    React.useEffect(() => {
        fetchMonthData();
        const interval = setInterval(fetchMonthData, 60000);
        return () => clearInterval(interval);
    }, [fetchMonthData]);

    // UI State
    const [selectedBookingId, setSelectedBookingId] = useState(null);
    const [draftBooking, setDraftBooking] = useState(null); // { booking, slots }
    const [isCreating, setIsCreating] = useState(false);

    const [createMode, setCreateMode] = useState("RENTAL");

    // --- EDIT MODE STATE ---
    const [isEditMode, setIsEditMode] = useState(false);
    const [modifiedSlots, setModifiedSlots] = useState({}); // { slotId: { ...slotNode } }

    const [isSaving, setIsSaving] = useState(false);
    const [infoModal, setInfoModal] = useState({ isOpen: false, title: "", message: "" });
    const closeInfoModal = () => setInfoModal(prev => ({ ...prev, isOpen: false }));

    // Toggle Edit Mode
    const handleToggleEditMode = () => {
        if (isEditMode) {
            // Cancel logic if toggled off via button (though we have explicit Cancel)
            handleCancelEdits();
        } else {
            setIsEditMode(true);
            setModifiedSlots({});
            setIsCreating(false); // Ensure create mode is off
            setDraftBooking(null);
        }
    };

    // Handle Slot Move (from Grid)
    const handleSlotMove = (slotId, newStartTime, newCourtId) => {
        setModifiedSlots(prev => {
            const originalSlot = allSlotsV2.find(s => s.slotId === slotId);
            if (!originalSlot) return prev;

            const duration = originalSlot.endTime - originalSlot.startTime;
            const newEndTime = newStartTime + duration;

            return {
                ...prev,
                [slotId]: {
                    ...originalSlot,
                    courtId: newCourtId || originalSlot.courtId,
                    startTime: newStartTime,
                    endTime: newEndTime,
                    isModified: true // Flag for UI
                }
            };
        });
    };

    // Save Edits
    const handleSaveEdits = async () => {
        setIsSaving(true);
        try {
            // Collect all updates into a flat array
            const allUpdates = Object.values(modifiedSlots).map(s => ({
                slotId: s.slotId,
                courtId: s.courtId,
                startTime: s.startTime,
                endTime: s.endTime,
                date: s.date
            }));

            // Use Batch API
            await bulkUpdateSlotsV2(allUpdates);

            // Collect Renter Names for Feedback
            const updatedRenters = Object.values(modifiedSlots).map(s => {
                const b = bookingsV2[s.bookingId];
                return b?.renter?.name || (b?.type === 'OPEN_PLAY_BLOCK' ? 'Open Play' : "Unknown");
            }).filter((name, index, self) => self.indexOf(name) === index); // Unique

            console.log("Promises resolved");
            console.log("Updated Renters:", updatedRenters);

            const namesList = updatedRenters.slice(0, 3).join(", ");
            const moreCount = updatedRenters.length > 3 ? ` +${updatedRenters.length - 3} more` : "";

            const toastMsg = `Schedule updated for: ${namesList}${moreCount}`;
            console.log("Firing toast:", toastMsg);
            toast.success(toastMsg);
            fetchMonthData(); // Refresh
            setIsEditMode(false);
            setModifiedSlots({});

        } catch (e) {
            toast.error("Failed to save changes: " + e.message);
        } finally {
            setIsSaving(false);
        }
    };

    const handleCancelEdits = () => {
        setIsEditMode(false);
        setModifiedSlots({});
    };



    const handleConfirmCreation = async (payload) => {
        if (!draftBooking) return;
        setIsSaving(true);

        const finalBooking = {
            ...draftBooking.booking,
            ...payload,
            renter: payload?.renter || draftBooking.booking.renter,
            // Merge payment details: prefer payload values (which include discounted totalAmount)
            // over the draft's raw totals which are computed from slot count × rate only.
            paymentSummary: {
                ...draftBooking.booking.paymentSummary,
                ...(payload?.payment || {}),
                // Ensure totalAmount from payload (discounted) takes precedence
                totalAmount: payload?.payment?.totalAmount ?? draftBooking.booking.paymentSummary?.totalAmount ?? 0,
                amountPaid: payload?.payment?.amountPaid ?? 0,
                paymentStatus: payload?.payment?.paymentStatus ?? draftBooking.booking.paymentSummary?.paymentStatus ?? 'UNPAID',
                paymentMethod: payload?.payment?.paymentMethod ?? null,
            }
        };
        const finalSlots = payload?.slots || draftBooking.slots;

        try {
            await toast.promise(
                (async () => {
                    const newBookingId = await addBookingV2(finalBooking, finalSlots);

                    // Refresh Data to ensure UI matches Server
                    fetchMonthData();

                    // Success State Updates
                    setIsCreating(false);
                    setDraftBooking(null);
                    setSelectedBookingId(newBookingId);
                    return newBookingId;
                })(),
                {
                    loading: 'Creating booking...',
                    success: 'Booking created successfully!',
                    error: (err) => `Creation failed: ${err.message}`
                }
            );
        } catch (e) {
            // Toast handles error
        } finally {
            setIsSaving(false);
        }
    };

    const handleUpdateBookingWrapper = async (bookingId, updates) => {
        setIsSaving(true);
        try {
            await toast.promise(
                (async () => {
                    await updateBookingV2(bookingId, updates);
                    fetchMonthData(); // Refresh
                })(),
                {
                    loading: 'Updating booking...',
                    success: 'Booking saved successfully!',
                    error: (err) => `Update failed: ${err.message}`
                }
            );
        } catch (e) {
        } finally {
            setIsSaving(false);
        }
    };

    const handleDeleteBookingWrapper = async (bookingId) => {
        setIsSaving(true);
        try {
            await toast.promise(
                (async () => {
                    await deleteBookingV2(bookingId);
                    fetchMonthData(); // Refresh
                })(),
                {
                    loading: 'Deleting booking...',
                    success: 'Booking deleted.',
                    error: (err) => `Delete failed: ${err.message}`
                }
            );
            setSelectedBookingId(null);
        } catch (e) {
        } finally {
            setIsSaving(false);
        }
    };

    const handleAddSlot = (bookingId, slotData) => {
        try {
            // If drafting, add to local draft state? 
            // V1 Modal expects real addSlot action.
            // For simplicitly, Draft Mode = initial slots only. 
            // If user wants to add more slots, they do it AFTER creating. 
            // OR we support draft slot addition (complex).
            // Let's assume V1 flow: Create with Initial -> Then Edit.
            if (isCreating) {
                // Draft mode doesn't support adding extra slots dynamically yet
                setInfoModal({ isOpen: true, title: "Action Not Allowed", message: "Please save the booking first before adding more slots." });
                return;
            }
            addSlotToBookingV2(bookingId, slotData);
        } catch (e) {
            setInfoModal({ isOpen: true, title: "Cannot Add Slot", message: e.message });
        }
    };

    // Handler: Drag on Grid -> Create Draft
    const handleTimeSelect = ({ startMinutes, endMinutes, courtIds }) => {
        // Create Temp ID
        const bookingId = `draft-${Date.now()}`;
        const isBlock = createMode === "OPEN_PLAY_BLOCK";

        // Align to hours
        const startHour = Math.floor(startMinutes / 60);
        let endHour = Math.floor(endMinutes / 60);
        if (endMinutes % 60 !== 0) endHour += 1;

        // Generate slots
        const initialSlots = [];
        let slotCounter = 0;

        // Defensive validation: Filter out invalid court IDs
        const existingCourtIds = new Set(calendarCourts.map(c => String(c.id)));
        const validCourtIds = courtIds.filter(id => existingCourtIds.has(String(id)));

        if (validCourtIds.length === 0) {
            toast.error("There was a problem with the slot selection. Please try again or add a slot manually.");
            return;
        }

        validCourtIds.forEach(cId => {
            for (let h = startHour; h < endHour; h++) {
                const sTime = new Date(currentDate);
                sTime.setHours(h, 0, 0, 0);
                const dateStr = sTime.toLocaleDateString('en-CA');

                initialSlots.push({
                    slotId: `draft-slot-${Date.now()}-${slotCounter++}`,
                    bookingId: bookingId,
                    courtId: cId,
                    date: dateStr,
                    startTime: h * 60,
                    endTime: (h + 1) * 60,
                    price: settings?.defaultRentalRate || 500 // Use Settings Default or 500
                });
            }
        });

        const newBooking = {
            id: bookingId,
            type: createMode,
            renter: isBlock ? null : { name: "", contact: "", email: "" },
            paymentSummary: { totalAmount: 0, amountPaid: 0, paymentStatus: 'UNPAID' }
        };

        // Set Draft
        setDraftBooking({ booking: newBooking, slots: initialSlots });
        setIsCreating(true);
    };

    // Handler: Manual "Create" Button Click -> Redirect to Day View
    const handleManualCreate = () => {
        // Just switch to Day View on Today (or current selected date?)
        // User request: "redirect to Day View to current day"
        // Usually "current day" implies Today.
        const today = new Date();
        setCurrentDate(today);
        setViewMode('day');

        // Don't open modal (isCreating = false)
        setIsCreating(false);
        setDraftBooking(null);

        // Optional: Maybe show a toast/hint? "Select a time slot on the grid."
        toast("Tap a time slot on the grid to create a booking.", { icon: '👆' });
    }

    const handleBookingClick = (bookingId) => {
        setSelectedBookingId(bookingId);
        setIsCreating(false);
        setDraftBooking(null);
    };

    const handleCloseModal = () => {
        setSelectedBookingId(null);
        setDraftBooking(null);
        setIsCreating(false);
    };

    // Derived: Active Data (Draft OR Real)
    const activeBooking = isCreating ? draftBooking?.booking : (selectedBookingId ? bookingsV2[selectedBookingId] : null);

    // For slots: 
    // If Draft: use draftBooking.slots
    // If Real: map IDs to slotsV2
    let activeBookingSlots = [];
    if (isCreating && draftBooking) {
        activeBookingSlots = draftBooking.slots;
    } else if (activeBooking) {
        activeBookingSlots = activeBooking.slotIds.map(id => slotsV2[id]).filter(Boolean);
    }

    // Date Navigation
    const nextDay = () => {
        const d = new Date(currentDate);
        d.setDate(d.getDate() + 1);
        setCurrentDate(d);
    };
    const prevDay = () => {
        const d = new Date(currentDate);
        d.setDate(d.getDate() - 1);
        setCurrentDate(d);
    };

    // Month Nav
    const nextMonth = () => {
        const d = new Date(currentDate);
        d.setMonth(d.getMonth() + 1);
        setCurrentDate(d);
    }
    const prevMonth = () => {
        const d = new Date(currentDate);
        d.setMonth(d.getMonth() - 1);
        setCurrentDate(d);
    }

    const handleNavNext = viewMode === 'month' ? nextMonth : nextDay;
    const handleNavPrev = viewMode === 'month' ? prevMonth : prevDay;

    // Header Label logic
    let headerLabel = currentDate.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
    if (viewMode === 'month') {
        headerLabel = currentDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    } else if (viewMode === 'list') {
        // Show range? "Jan 1 - Jan 7"
        const endRange = new Date(currentDate);
        endRange.setDate(endRange.getDate() + 6);
        headerLabel = `${currentDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} - ${endRange.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`;
    }

    // --- Draft Modifiers ---
    const updateDraftRenter = (bookingId, data) => {
        setDraftBooking(prev => ({
            ...prev,
            booking: { ...prev.booking, renter: { ...prev.booking.renter, ...data } }
        }));
    };

    const updateDraftPayment = (bookingId, amount, method, status) => {
        // status is usually just a log message in the real hook, but maybe we need to track local amount?
        // In draft, we just update summary.
        setDraftBooking(prev => ({
            ...prev,
            booking: {
                ...prev.booking,
                paymentSummary: {
                    ...prev.booking.paymentSummary,
                    totalAmount: amount, // Logic in modal might pass total? No, modal passes `amount` paid usually?
                    // Wait, `updateBookingPaymentV2` signature: (bookingId, amountPaid, method, note)
                    amountPaid: amount,
                    paymentMethod: method,
                    // Auto-calculate status derived?
                    paymentStatus: amount >= (prev.booking.paymentSummary.totalAmount || 0) ? "PAID" : (amount > 0 ? "PARTIAL" : "UNPAID")
                }
            }
        }));
    };

    const removeDraftSlot = (slotId) => {
        setDraftBooking(prev => {
            const newSlots = prev.slots.filter(s => s.slotId !== slotId);
            if (newSlots.length === 0) {
                // All slots gone? Cancel draft?
                handleCloseModal();
                return null;
            }
            return { ...prev, slots: newSlots };
        });
    };

    // Calculate Total Price for Draft (using settings rate)
    React.useEffect(() => {
        if (draftBooking && draftBooking.slots) {
            const ratePerSlot = settings?.defaultRentalRate || 500;
            const total = draftBooking.slots.length * ratePerSlot;
            setDraftBooking(prev => {
                if (!prev || prev.booking.paymentSummary.totalAmount === total) return prev;
                return {
                    ...prev,
                    booking: {
                        ...prev.booking,
                        paymentSummary: { ...prev.booking.paymentSummary, totalAmount: total }
                    }
                };
            });
        }
    }, [draftBooking?.slots?.length, settings?.defaultRentalRate]);


    return (
        <div className="flex h-full flex-col bg-white">
            {/* Header */}
            <header className="flex flex-col gap-4 border-b border-slate-200 px-4 py-4 md:px-6">
                {/* ... Header Content ... */}
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div className="flex items-center justify-between md:justify-start gap-4 w-full md:w-auto">
                        <h1 className="text-lg md:text-xl font-semibold text-slate-900 tracking-tight flex items-center gap-2 shrink-0">
                            <CalendarIcon className="h-5 w-5 text-slate-500" />
                            <span className="hidden xs:inline">Court Calendar</span>
                        </h1>

                        {/* Date Nav - Mobile: Auto width, Desktop: Fixed */}
                        <div className="flex items-center rounded-md border border-slate-200 bg-slate-50 p-1 ml-auto md:ml-0">
                            <button onClick={handleNavPrev} className="rounded-sm p-1 hover:bg-white hover:shadow-sm">
                                <ChevronLeft className="h-4 w-4 text-slate-500" />
                            </button>
                            <span className="min-w-[120px] md:min-w-[140px] text-center text-sm font-medium text-slate-700 select-none truncate px-2">
                                {headerLabel}
                            </span>
                            <button onClick={handleNavNext} className="rounded-sm p-1 hover:bg-white hover:shadow-sm">
                                <ChevronRight className="h-4 w-4 text-slate-500" />
                            </button>
                        </div>
                    </div>

                    <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
                        {/* View Toggle */}
                        <div className="flex items-center bg-slate-100 rounded-lg p-1 border border-slate-200 flex-1 md:flex-none justify-center">
                            {[
                                { id: 'day', label: 'Day', icon: CalendarDays },
                                { id: 'month', label: 'Month', icon: CalendarIcon },
                                { id: 'list', label: 'List', icon: LayoutList },
                            ].map(view => (
                                <button
                                    key={view.id}
                                    onClick={() => setViewMode(view.id)}
                                    className={cn(
                                        "flex items-center justify-center gap-2 px-3 py-1.5 text-xs font-medium rounded-md transition-all flex-1 md:flex-none",
                                        viewMode === view.id ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"
                                    )}
                                >
                                    <view.icon className="h-3.5 w-3.5" />
                                    <span className="hidden sm:inline">{view.label}</span>
                                </button>
                            ))}
                        </div>

                        <div className="h-6 w-px bg-slate-200 mx-1 hidden md:block" />

                        {/* Create Mode Toggle - Hide labels on mobile if needed */}
                        <div className="flex items-center bg-slate-100 rounded-lg p-1 border border-slate-200">
                            <button
                                onClick={() => setCreateMode("RENTAL")}
                                className={cn(
                                    "flex items-center gap-2 px-3 py-1.5 text-xs font-medium rounded-md transition-all",
                                    createMode === "RENTAL" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"
                                )}
                                title="Rental Mode"
                            >
                                <span className={cn("h-2 w-2 rounded-full", createMode === "RENTAL" ? "bg-emerald-500" : "bg-slate-300")} />
                                <span className="hidden sm:inline">Rental</span>
                            </button>
                            <button
                                onClick={() => setCreateMode("OPEN_PLAY_BLOCK")}
                                className={cn(
                                    "flex items-center gap-2 px-3 py-1.5 text-xs font-medium rounded-md transition-all",
                                    createMode === "OPEN_PLAY_BLOCK" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"
                                )}
                                title="Blocker Mode"
                            >
                                <BoxSelect className="h-3.5 w-3.5" />
                                <span className="hidden sm:inline">Blocker</span>
                            </button>
                        </div>
                    </div>

                    {/* Actions Group - Full width on mobile for ease of tapping */}
                    <div className="flex items-center gap-2 w-full md:w-auto justify-end border-t border-slate-100 pt-3 md:border-0 md:pt-0">
                        {isEditMode ? (
                            <>
                                <button
                                    onClick={handleCancelEdits}
                                    className="flex-1 md:flex-none px-3 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg transition-colors border border-slate-200"
                                    disabled={isSaving}
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={handleSaveEdits}
                                    disabled={isSaving}
                                    className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white px-4 py-2 rounded-lg text-sm font-semibold shadow-sm transition-colors"
                                >
                                    {isSaving ? "Saving..." : "Save Changes"}
                                </button>
                            </>
                        ) : (
                            <>
                                {/* Edit Mode Toggle - Only in Day View */}
                                {viewMode === 'day' && (
                                    <button
                                        onClick={handleToggleEditMode}
                                        className="flex-1 md:flex-none px-3 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg transition-colors border border-slate-200"
                                    >
                                        Edit Schedule
                                    </button>
                                )}

                                {/* Manual Create Button */}
                                <button
                                    onClick={handleManualCreate}
                                    className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg text-sm font-semibold shadow-sm transition-colors"
                                >
                                    <Plus className="h-4 w-4" />
                                    <span>Create</span>
                                </button>
                            </>
                        )}
                    </div>
                </div>

                {viewMode === 'day' && (
                    <div className="text-xs text-slate-400 font-medium flex justify-center md:justify-end">
                        {isEditMode
                            ? "Drag slots to move them. Click Save to apply."
                            : `Drag on grid to create ${createMode === "RENTAL" ? "Bookings" : "Blocks"}`
                        }
                    </div>
                )}
            </header>

            {/* View Container */}
            <div className="flex-1 overflow-hidden relative flex flex-col">
                <div className="flex-1 overflow-auto">
                    <React.Suspense fallback={<div className="p-10 text-center text-sm text-slate-400">Loading View...</div>}>
                        {viewMode === 'day' && (
                            <CalendarGrid
                                courts={calendarCourts}
                                bookings={bookingsV2}
                                slots={allSlotsV2}
                                currentDate={currentDate}
                                onTimeSelect={handleTimeSelect}
                                onBookingClick={handleBookingClick}

                                // Drag & Drop Props
                                isEditMode={isEditMode}
                                modifiedSlots={modifiedSlots}
                                onSlotMove={handleSlotMove}
                            />
                        )}
                        {viewMode === 'month' && (
                            <CalendarMonthView

                                currentDate={currentDate}
                                slots={allSlotsV2}
                                bookings={bookingsV2}
                                onDateClick={(date) => {
                                    setCurrentDate(date);
                                    setViewMode('day');
                                }}
                            />
                        )}
                        {viewMode === 'list' && (
                            <CalendarListView
                                currentDate={currentDate}
                                bookings={bookingsV2}
                                slots={allSlotsV2}
                                onBookingClick={handleBookingClick}
                            />
                        )}
                    </React.Suspense>
                </div>
            </div>

            {/* Modal */}
            <React.Suspense fallback={null}>
                <BookingManagerModal
                    isOpen={!!activeBooking}
                    onClose={handleCloseModal}
                    booking={activeBooking}
                    slots={activeBookingSlots}
                    allSlots={allSlotsV2}
                    // Pass actions conditional on Draft vs Real
                    // Wiring Up Actions
                    onUpdateRenter={isCreating ? updateDraftRenter : updateBookingRenterV2}
                    onUpdatePayment={isCreating ? updateDraftPayment : updateBookingPaymentV2}
                    onUpdateBooking={handleUpdateBookingWrapper} // Wrapped
                    onRemoveSlot={isCreating ? removeDraftSlot : removeSlotV2}
                    onAddSlot={handleAddSlot}
                    onToggleSlotPayment={toggleSlotPaymentV2}
                    onMarkAllPaid={markAllSlotsPaidV2}
                    onMarkFree={markBookingFreeV2}
                    onDeleteBooking={handleDeleteBookingWrapper}
                    courts={calendarCourts} // Pass dynamic courts

                    // Wiring Up Creation
                    isCreating={isCreating}
                    onConfirmCreation={handleConfirmCreation}
                    isSaving={isSaving}
                    defaultRentalRate={settings?.defaultRentalRate}
                />
            </React.Suspense>
            <ConfirmationModal
                isOpen={infoModal.isOpen}
                title={infoModal.title}
                message={infoModal.message}
                confirmLabel="OK"
                cancelLabel={null}
                onConfirm={closeInfoModal}
                onCancel={closeInfoModal}
            />
        </div>
    );
}
