import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import {
  Monitor,
  Tv,
  Play,
  BarChart2,
  Trophy,
  Clock,
  CheckCircle,
  Image,
  Star,
  Plus,
  Trash2,
  ToggleLeft,
  ToggleRight,
  ChevronUp,
  ChevronDown,
  ExternalLink,
  Wifi,
  WifiOff,
  Settings,
  RefreshCw,
} from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import { saveLogo, deleteLogo } from "../utils/imageStorage";
import toast from "react-hot-toast";

const VIEWS = [
  { key: "tournament_info", label: "Info", icon: Monitor, desc: "Welcome screen" },
  { key: "current_match", label: "Now Playing", icon: Play, desc: "In-progress matches" },
  { key: "live_courts", label: "Live Courts", icon: Tv, desc: "All courts grid" },
  { key: "standings", label: "Standings", icon: BarChart2, desc: "Group standings" },
  { key: "bracket", label: "Bracket", icon: Trophy, desc: "Playoff bracket" },
  { key: "upcoming", label: "Upcoming", icon: Clock, desc: "Next matches" },
  { key: "results", label: "Results", icon: CheckCircle, desc: "Recent results" },
  { key: "slideshow", label: "Slideshow", icon: RefreshCw, desc: "Auto-cycle views" },
  { key: "sponsor_slideshow", label: "Sponsor Show", icon: Star, desc: "Sponsor cycle" },
];

const VIEW_LABELS = {
  tournament_info: "Tournament Info",
  current_match: "Now Playing",
  live_courts: "Live Courts",
  standings: "Standings",
  bracket: "Bracket",
  upcoming: "Upcoming",
  results: "Results",
  sponsor_highlight: "Sponsor",
  sponsor_slideshow: "Sponsors",
  slideshow: "Live Updates",
};

// ── Mini Display Preview ──────────────────────────────────────────────────────
function fmt12Mini(time24) {
  if (!time24) return "—";
  const [h, m] = time24.split(":").map(Number);
  const ampm = h >= 12 ? "PM" : "AM";
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${ampm}`;
}

function MiniDisplayPreview({ tournament, activeView, divisions, partners, matches, featuredMatchId }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  const timeStr = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  const dateStr = now.toLocaleDateString([], { weekday: "short", month: "short", day: "numeric" });

  const partnerMap = useMemo(
    () => Object.fromEntries(partners.map((p) => [p.id, p])),
    [partners]
  );
  const divMap = useMemo(
    () => Object.fromEntries(divisions.map((d) => [d.id, d])),
    [divisions]
  );
  const shownDivisions = useMemo(
    () => divisions.filter((d) => d.tournament_id === tournament.id),
    [divisions, tournament.id]
  );
  const liveMatches = useMemo(
    () => matches.filter((m) => m.tournament_id === tournament.id && m.status === "in_progress"),
    [matches, tournament.id]
  );

  function renderMiniContent() {
    switch (activeView) {
      // ── Tournament Info ─────────────────────────────────────────────────
      case "tournament_info":
        return (
          <div className="flex-1 flex flex-col items-center justify-center text-center px-4 gap-3">
            <div className="font-display text-3xl text-pickle-cream leading-tight">{tournament.name}</div>
            {(tournament.start_date) && (
              <div className="text-pickle-cream/60 text-xs font-body">{tournament.start_date}</div>
            )}
            {shownDivisions.length > 0 && (
              <div className="w-full max-w-[280px] grid grid-cols-2 gap-1.5">
                {shownDivisions.map((d) => {
                  const divPartners = partners.filter((p) => p.division_id === d.id && !p.withdrawn);
                  return (
                    <div key={d.id} className="bg-white/10 rounded-xl px-2.5 py-1.5 text-left">
                      <div className="font-oswald font-bold text-white text-sm">{d.name}</div>
                      <div className="text-pickle-cream/50 text-[10px] font-body">{divPartners.length} teams</div>
                    </div>
                  );
                })}
              </div>
            )}
            {tournament.courts?.length > 0 && (
              <div className="text-pickle-cream/40 text-[10px] font-body">{tournament.courts.join(" · ")}</div>
            )}
          </div>
        );

      // ── Current Match (Now Playing) — VS layout ─────────────────────────
      case "current_match": {
        const featuredMatch = featuredMatchId
          ? matches.find((m) => m.id === featuredMatchId) || liveMatches[0]
          : liveMatches.length === 1 ? liveMatches[0] : null;

        // VS full layout for featured or single match
        if (featuredMatch || liveMatches.length <= 1) {
          const m = featuredMatch || liveMatches[0];
          if (!m) {
            return (
              <div className="flex-1 flex items-center justify-center">
                <div className="flex flex-col items-center gap-2">
                  <div className="w-12 h-12 rounded-full border-2 border-dashed border-white/20 flex items-center justify-center">
                    <span className="font-oswald font-bold text-white/30 text-xs">VS</span>
                  </div>
                  <div className="text-white/20 font-oswald font-bold text-xs uppercase tracking-widest">No Matches Live</div>
                </div>
              </div>
            );
          }
          const teamA = partnerMap[m.partner_a_id];
          const teamB = partnerMap[m.partner_b_id];
          const liveScore = m.live_score;
          const scoreA = liveScore?.partner_a ?? null;
          const scoreB = liveScore?.partner_b ?? null;
          return (
            <div className="flex-1 flex flex-col items-center justify-between py-3 px-2">
              {/* Court label */}
              {m.court && (
                <div className="font-oswald font-bold text-pickle-cream/60 text-[10px] uppercase tracking-widest">{m.court}</div>
              )}
              {/* Main VS row */}
              <div className="flex-1 flex items-center justify-center w-full gap-1">
                {/* Team A */}
                <div className="flex-1 flex flex-col items-center gap-1 text-center">
                  {scoreA !== null && (
                    <div className={`font-oswald font-bold leading-none tabular-nums text-3xl ${scoreA > (scoreB ?? -1) ? "text-pickle-gold" : "text-white/60"}`}>
                      {scoreA}
                    </div>
                  )}
                  <div className="font-oswald font-bold text-white text-[11px] leading-tight text-center px-1" style={{ wordBreak: "break-word" }}>
                    {teamA?.team_name || "TBD"}
                  </div>
                  {(teamA?.player_1_name || teamA?.player_2_name) && (
                    <div className="text-pickle-cream/40 text-[8px] leading-tight text-center px-1">
                      {[teamA.player_1_name, teamA.player_2_name].filter(Boolean).join(" · ")}
                    </div>
                  )}
                </div>
                {/* VS badge */}
                <div className="shrink-0 w-8 h-8 rounded-full border border-dashed border-white/25 flex items-center justify-center mx-1">
                  <span className="font-oswald font-bold text-white/40 text-[9px]">VS</span>
                </div>
                {/* Team B */}
                <div className="flex-1 flex flex-col items-center gap-1 text-center">
                  {scoreB !== null && (
                    <div className={`font-oswald font-bold leading-none tabular-nums text-3xl ${scoreB > (scoreA ?? -1) ? "text-pickle-gold" : "text-white/60"}`}>
                      {scoreB}
                    </div>
                  )}
                  <div className="font-oswald font-bold text-white text-[11px] leading-tight text-center px-1" style={{ wordBreak: "break-word" }}>
                    {teamB?.team_name || "TBD"}
                  </div>
                  {(teamB?.player_1_name || teamB?.player_2_name) && (
                    <div className="text-pickle-cream/40 text-[8px] leading-tight text-center px-1">
                      {[teamB.player_1_name, teamB.player_2_name].filter(Boolean).join(" · ")}
                    </div>
                  )}
                </div>
              </div>
              {/* Bottom: completed scores + live badge */}
              <div className="flex items-center gap-2">
                {m.scores?.length > 0 && (
                  <div className="text-pickle-gold font-oswald font-bold text-[9px]">
                    {m.scores.map((g, i) => <span key={i}>{i > 0 ? " · " : ""}{g.partner_a}–{g.partner_b}</span>)}
                  </div>
                )}
                {m.status === "in_progress" && (
                  <span className="flex items-center gap-1 text-green-300 font-oswald font-bold text-[9px] uppercase">
                    <span className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse" /> Live
                  </span>
                )}
              </div>
            </div>
          );
        }

        // Multiple live, no featured — compact grid
        return (
          <div className={`flex-1 p-3 grid gap-2 content-center ${liveMatches.length <= 4 ? "grid-cols-2" : "grid-cols-3"}`}>
            {liveMatches.slice(0, 6).map((m) => (
              <div key={m.id} className="bg-white/10 border border-white/20 rounded-xl p-2 flex flex-col gap-1">
                {m.court && <div className="text-pickle-cream/50 font-oswald text-[9px] uppercase">{m.court}</div>}
                <div className="flex items-center justify-between gap-1">
                  <span className="font-oswald font-bold text-white text-[11px] truncate flex-1">{partnerMap[m.partner_a_id]?.team_name || "TBD"}</span>
                  {m.live_score != null && <span className="font-oswald font-bold text-pickle-gold text-sm tabular-nums">{m.live_score.partner_a ?? 0}</span>}
                </div>
                <div className="text-white/25 text-[8px] text-center">vs</div>
                <div className="flex items-center justify-between gap-1">
                  <span className="font-oswald font-bold text-white text-[11px] truncate flex-1">{partnerMap[m.partner_b_id]?.team_name || "TBD"}</span>
                  {m.live_score != null && <span className="font-oswald font-bold text-pickle-gold text-sm tabular-nums">{m.live_score.partner_b ?? 0}</span>}
                </div>
              </div>
            ))}
          </div>
        );
      }

      // ── Live Courts ──────────────────────────────────────────────────────
      case "live_courts": {
        const courts = tournament.courts || [];
        const colCount = courts.length <= 2 ? courts.length : courts.length <= 4 ? 2 : 3;
        const gridCols = colCount === 1 ? "grid-cols-1" : colCount === 2 ? "grid-cols-2" : "grid-cols-3";
        return (
          <div className={`flex-1 p-3 grid ${gridCols} gap-2 content-center`}>
            {courts.slice(0, 9).map((courtName) => {
              const live = matches.find((m) => m.tournament_id === tournament.id && m.court === courtName && m.status === "in_progress");
              const upcoming = !live && matches.find((m) => m.tournament_id === tournament.id && m.court === courtName && m.status === "scheduled" && m.partner_a_id && m.partner_b_id);
              const active = live || upcoming;
              const liveScore = live?.live_score;
              return (
                <div key={courtName} className={`rounded-xl p-2.5 flex flex-col gap-1 border-2 ${live ? "border-green-500/60 bg-green-500/10" : upcoming ? "border-amber-400/40 bg-white/5" : "border-white/10 bg-white/5"}`}>
                  <div className="flex items-center justify-between">
                    <span className="font-oswald font-bold text-xs text-white uppercase tracking-wide truncate">{courtName}</span>
                    {live && <span className="text-[8px] font-bold text-green-300 bg-green-500/25 px-1.5 py-0.5 rounded-full">LIVE</span>}
                    {upcoming && !live && <span className="text-[8px] text-amber-300 bg-amber-400/20 px-1.5 py-0.5 rounded-full">NEXT</span>}
                  </div>
                  {active ? (
                    <>
                      <div className="flex items-center justify-between gap-1">
                        <span className="font-oswald font-bold text-white text-[11px] leading-tight truncate flex-1">{partnerMap[active.partner_a_id]?.team_name || "TBD"}</span>
                        {liveScore != null && <span className="font-oswald font-bold text-pickle-gold text-sm tabular-nums">{liveScore.partner_a ?? 0}</span>}
                      </div>
                      <div className="text-white/25 text-[8px] text-center">vs</div>
                      <div className="flex items-center justify-between gap-1">
                        <span className="font-oswald font-bold text-white text-[11px] leading-tight truncate flex-1">{partnerMap[active.partner_b_id]?.team_name || "TBD"}</span>
                        {liveScore != null && <span className="font-oswald font-bold text-pickle-gold text-sm tabular-nums">{liveScore.partner_b ?? 0}</span>}
                      </div>
                    </>
                  ) : (
                    <div className="text-white/20 font-oswald text-[10px]">Available</div>
                  )}
                </div>
              );
            })}
          </div>
        );
      }

      // ── Standings ────────────────────────────────────────────────────────
      case "standings":
        return (
          <div className="flex-1 flex flex-col items-center justify-center p-3 gap-2 overflow-hidden">
            {shownDivisions.length === 0 && (
              <div className="text-white/30 font-oswald font-bold text-base">No Divisions</div>
            )}
            {shownDivisions.slice(0, 2).map((div) => {
              const divPartners = partners.filter((p) => p.division_id === div.id && !p.withdrawn).slice(0, 6);
              const divMatches = matches.filter((m) => m.division_id === div.id && m.status === "completed" && m.winner_id);
              const winsMap = {};
              const lossMap = {};
              divPartners.forEach((p) => { winsMap[p.id] = 0; lossMap[p.id] = 0; });
              divMatches.forEach((m) => {
                if (winsMap[m.winner_id] !== undefined) winsMap[m.winner_id]++;
                const loserId = m.winner_id === m.partner_a_id ? m.partner_b_id : m.partner_a_id;
                if (lossMap[loserId] !== undefined) lossMap[loserId]++;
              });
              const sorted = [...divPartners].sort((a, b) => (winsMap[b.id] || 0) - (winsMap[a.id] || 0));
              return (
                <div key={div.id} className="bg-white/10 rounded-xl overflow-hidden w-full">
                  <div className="bg-white/10 px-3 py-1.5">
                    <span className="font-oswald font-bold text-pickle-cream text-sm uppercase tracking-wide">{div.name}</span>
                  </div>
                  <table className="w-full">
                    <thead>
                      <tr className="text-pickle-cream/40 text-[9px] font-oswald uppercase">
                        <th className="px-2 py-1 text-left">#</th>
                        <th className="px-2 py-1 text-left">Team</th>
                        <th className="px-2 py-1 text-center">W</th>
                        <th className="px-2 py-1 text-center">L</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sorted.map((p, i) => (
                        <tr key={p.id} className="border-t border-white/10">
                          <td className="px-2 py-1 text-white/40 font-oswald text-[10px]">{i + 1}</td>
                          <td className="px-2 py-1 font-oswald font-bold text-white text-[11px] truncate max-w-[90px]">{p.team_name}</td>
                          <td className="px-2 py-1 text-center text-pickle-gold font-oswald font-bold text-[11px]">{winsMap[p.id] || 0}</td>
                          <td className="px-2 py-1 text-center text-white/50 font-oswald text-[11px]">{lossMap[p.id] || 0}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              );
            })}
          </div>
        );

      // ── Upcoming ─────────────────────────────────────────────────────────
      case "upcoming": {
        const upcoming = matches
          .filter((m) => m.tournament_id === tournament.id && m.status === "scheduled" && m.partner_a_id && m.partner_b_id)
          .sort((a, b) => ((a.scheduled_date || "") + (a.scheduled_time || "")).localeCompare((b.scheduled_date || "") + (b.scheduled_time || "")))
          .slice(0, 8);
        return (
          <div className="flex-1 flex flex-col justify-center p-3 gap-1">
            {upcoming.length === 0 && (
              <div className="flex items-center justify-center h-full text-white/30 font-oswald font-bold text-base uppercase tracking-widest">No Upcoming</div>
            )}
            {upcoming.map((m, idx) => (
              <div key={m.id} className={`flex items-center gap-2 rounded-lg px-2.5 py-1.5 ${idx % 2 === 0 ? "bg-white/10" : "bg-white/5"}`}>
                <span className="text-pickle-cream font-oswald font-bold w-14 shrink-0 text-[11px]">{fmt12Mini(m.scheduled_time)}</span>
                <span className="font-oswald font-bold text-white text-xs truncate flex-1">
                  {partnerMap[m.partner_a_id]?.team_name || "TBD"} <span className="text-white/30 font-normal">vs</span> {partnerMap[m.partner_b_id]?.team_name || "TBD"}
                </span>
                {m.court && <span className="text-pickle-cream/30 text-[9px] shrink-0">{m.court}</span>}
              </div>
            ))}
          </div>
        );
      }

      // ── Results ──────────────────────────────────────────────────────────
      case "results": {
        const recent = matches
          .filter((m) => m.tournament_id === tournament.id && m.status === "completed" && m.winner_id)
          .sort((a, b) => (b.completed_at || "").localeCompare(a.completed_at || ""))
          .slice(0, 10);
        return (
          <div className="flex-1 flex flex-col justify-center p-3 gap-1">
            {recent.length === 0 && (
              <div className="flex items-center justify-center h-full text-white/30 font-oswald font-bold text-base uppercase tracking-widest">No Results Yet</div>
            )}
            {recent.map((m, idx) => {
              const winner = partnerMap[m.winner_id];
              const loserId = m.winner_id === m.partner_a_id ? m.partner_b_id : m.partner_a_id;
              const loser = partnerMap[loserId];
              const div = divMap[m.division_id];
              const scoreStr = m.scores?.map((g) => `${g.partner_a}–${g.partner_b}`).join(", ") || "";
              return (
                <div key={m.id} className={`flex items-center gap-2 rounded-lg px-2.5 py-1.5 ${idx % 2 === 0 ? "bg-white/10" : "bg-white/5"}`}>
                  <div className="flex-1 min-w-0">
                    <div className="font-oswald font-bold text-pickle-gold text-xs truncate">{winner?.team_name || "TBD"}</div>
                    <div className="font-oswald text-white/50 text-[10px] truncate">{loser?.team_name || "TBD"}</div>
                  </div>
                  {scoreStr && <span className="text-pickle-gold font-oswald font-bold text-[10px] shrink-0">{scoreStr}</span>}
                  {div && <span className="text-white/30 text-[9px] shrink-0">{div.name}</span>}
                </div>
              );
            })}
          </div>
        );
      }

      default:
        return (
          <div className="flex-1 flex items-center justify-center">
            <span className="text-white/40 font-oswald font-bold text-base uppercase tracking-widest">{VIEW_LABELS[activeView] || activeView}</span>
          </div>
        );
    }
  }

  // Inner renders at 2× the container size, scale(0.5) brings it to 1×.
  // Container uses aspectRatio 16/9 and overflow: hidden to clip perfectly.
  return (
    // Outer: full width, 16:9 aspect ratio, clips inner
    <div className="relative w-full overflow-hidden rounded-xl" style={{ aspectRatio: "16/9" }}>
      {/* Inner: 2× size, scaled down 50% from top-left */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "200%",
          height: "200%",
          transform: "scale(0.5)",
          transformOrigin: "top left",
        }}
      >
        <div className="w-full h-full bg-[#3E430F] flex flex-col">
          {/* Mini header */}
          <div className="shrink-0 flex items-center justify-between px-5 py-3 bg-black/30 border-b border-white/10">
            <div>
              <div className="font-display text-2xl text-white leading-tight truncate max-w-xs">{tournament.name}</div>
              <div className="text-pickle-cream/50 text-sm font-body mt-0.5">{VIEW_LABELS[activeView] || activeView}</div>
            </div>
            <div className="flex flex-col items-end">
              <span className="text-pickle-cream font-oswald text-3xl">{timeStr}</span>
              <span className="text-pickle-cream/50 font-body text-base">{dateStr}</span>
            </div>
          </div>
          {/* Mini content */}
          <div className="flex-1 overflow-hidden flex flex-col">
            {renderMiniContent()}
          </div>
        </div>
      </div>
    </div>
  );
}

// ── RemoteTab ──────────────────────────────────────────────────────────────
export default function RemoteTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getMatchesForTournament,
    getPartnersForTournament,
    addSponsor,
    removeSponsor,
    updateSponsor,
    reorderSponsors,
    updateDisplaySettings,
  } = useTournamentState();

  const divisions = getDivisionsForTournament(tournament.id);
  const allMatches = useMemo(() => getMatchesForTournament(tournament.id), [getMatchesForTournament, tournament.id]);
  const allPartners = useMemo(() => getPartnersForTournament(tournament.id), [getPartnersForTournament, tournament.id]);
  const sponsors = tournament.sponsors || [];
  const displaySettings = tournament.display_settings || {};

  const [activeView, setActiveView] = useState(displaySettings.current_view || "tournament_info");
  const [filterDivisionId, setFilterDivisionId] = useState(null);
  const [featuredMatchId, setFeaturedMatchId] = useState(null);
  const [connected, setConnected] = useState(false);
  const [slideshowInterval, setSlideshowInterval] = useState(displaySettings.slideshow_interval || 15);
  const [sponsorInterval, setSponsorInterval] = useState(displaySettings.sponsor_slideshow_interval || 8);

  // Sponsor add form
  const [sponsorName, setSponsorName] = useState("");
  const [sponsorPreview, setSponsorPreview] = useState(null);
  const [sponsorFile, setSponsorFile] = useState(null);
  const fileInputRef = useRef(null);

  const bcRef = useRef(null);
  const disconnectTimerRef = useRef(null);

  // BroadcastChannel
  useEffect(() => {
    const channelName = `tournament_display_${tournament.id}`;
    let bc = null;
    try {
      bc = new BroadcastChannel(channelName);
      bc.onmessage = (e) => {
        const { type } = e.data || {};
        if (type === "DISPLAY_STATUS") {
          setConnected(true);
          if (disconnectTimerRef.current) clearTimeout(disconnectTimerRef.current);
          disconnectTimerRef.current = setTimeout(() => setConnected(false), 15000);
        }
      };
      bcRef.current = bc;
    } catch {}

    return () => {
      if (disconnectTimerRef.current) clearTimeout(disconnectTimerRef.current);
      bc?.close();
      bcRef.current = null;
    };
  }, [tournament.id]);

  const send = useCallback((msg) => {
    try { bcRef.current?.postMessage(msg); } catch {}
  }, []);

  const switchView = (view) => {
    setActiveView(view);
    send({ type: "CHANGE_VIEW", view, matchId: view === "current_match" ? featuredMatchId : undefined });
    updateDisplaySettings(tournament.id, { current_view: view });
  };

  const handleFeaturedMatch = (matchId) => {
    const next = featuredMatchId === matchId ? null : matchId;
    setFeaturedMatchId(next);
    // Always switch to current_match AND carry the featured match ID in one broadcast
    setActiveView("current_match");
    send({ type: "CHANGE_VIEW", view: "current_match", matchId: next });
    updateDisplaySettings(tournament.id, { current_view: "current_match" });
  };

  const handleDivisionFilter = (divId) => {
    const next = filterDivisionId === divId ? null : divId;
    setFilterDivisionId(next);
    send({ type: "SET_DIVISION", divisionId: next });
  };

  const handleFileSelect = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { toast.error("Image must be under 5 MB"); return; }
    setSponsorFile(file);
    const url = URL.createObjectURL(file);
    setSponsorPreview(url);
  };

  const handleAddSponsor = async () => {
    if (!sponsorName.trim()) { toast.error("Enter a sponsor name"); return; }
    const id = addSponsor(tournament.id, { name: sponsorName.trim() });
    if (sponsorFile && id) {
      await saveLogo(id, sponsorFile);
    }
    setSponsorName("");
    setSponsorFile(null);
    if (sponsorPreview) { URL.revokeObjectURL(sponsorPreview); setSponsorPreview(null); }
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleRemoveSponsor = async (sponsorId) => {
    removeSponsor(tournament.id, sponsorId);
    await deleteLogo(sponsorId);
  };

  const handleHighlight = (sponsorId) => {
    send({ type: "SET_SPONSOR", sponsorId });
    send({ type: "CHANGE_VIEW", view: "sponsor_highlight" });
    setActiveView("sponsor_highlight");
  };

  const moveSponsor = (idx, dir) => {
    const sorted = [...sponsors].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
    const ids = sorted.map((s) => s.id);
    const newIdx = idx + dir;
    if (newIdx < 0 || newIdx >= ids.length) return;
    [ids[idx], ids[newIdx]] = [ids[newIdx], ids[idx]];
    reorderSponsors(tournament.id, ids);
  };

  const saveIntervalSettings = () => {
    updateDisplaySettings(tournament.id, {
      slideshow_interval: Number(slideshowInterval) || 15,
      sponsor_slideshow_interval: Number(sponsorInterval) || 8,
    });
    send({
      type: "UPDATE_SETTINGS",
      settings: {
        slideshow_interval: Number(slideshowInterval) || 15,
        sponsor_slideshow_interval: Number(sponsorInterval) || 8,
      },
    });
    toast.success("Settings saved.");
  };

  const openDisplay = () => {
    window.open(`#/tournament/${tournament.id}/display`, "_blank", "noopener");
  };

  const sortedSponsors = [...sponsors].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

  return (
    <div className="p-4 md:p-6 max-w-4xl mx-auto space-y-6">
      {/* ── Header row ── */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-lg font-semibold text-slate-800">Display Remote</h2>
          <p className="text-sm text-slate-500">Control what's shown on your venue display.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className={`flex items-center gap-1.5 text-sm font-medium ${connected ? "text-green-600" : "text-slate-400"}`}>
            {connected ? <Wifi size={14} /> : <WifiOff size={14} />}
            {connected ? "Display Connected" : "Display Offline"}
          </div>
          <button
            onClick={openDisplay}
            className="flex items-center gap-2 px-4 py-2 rounded-lg bg-pickle-green text-white text-sm font-semibold hover:bg-pickle-green/90 transition-colors"
          >
            <ExternalLink size={14} />
            Open Display
          </button>
        </div>
      </div>

      {/* ── Mini Display Preview ── */}
      <div className="bg-slate-900 rounded-2xl border border-slate-700 shadow-lg overflow-hidden">
        <div className="flex items-center justify-between px-4 py-2.5 border-b border-slate-700/60">
          <span className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
            <Monitor size={12} />
            Live Preview
          </span>
          <div className="flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full ${connected ? "bg-green-500 animate-pulse" : "bg-slate-600"}`} />
            <span className="text-[11px] text-slate-500 font-body">{VIEW_LABELS[activeView] || activeView}</span>
          </div>
        </div>
        <div className="p-3">
          <MiniDisplayPreview
            tournament={tournament}
            activeView={activeView}
            divisions={divisions}
            partners={allPartners}
            matches={allMatches}
            featuredMatchId={featuredMatchId}
          />
        </div>
      </div>

      {/* ── View selector ── */}
      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-5">
        <h3 className="text-sm font-bold text-slate-700 mb-3">Display View</h3>
        <div className="grid grid-cols-3 gap-2">
          {VIEWS.map(({ key, label, icon: Icon, desc }) => (
            <button
              key={key}
              onClick={() => switchView(key)}
              className={`flex flex-col items-center gap-1.5 p-3 rounded-xl border-2 text-center transition-all text-sm font-medium ${
                activeView === key
                  ? "border-pickle-green bg-pickle-green/5 text-pickle-green"
                  : "border-slate-100 text-slate-600 hover:border-pickle-green/30 hover:text-pickle-green"
              }`}
            >
              <Icon size={20} />
              <span className="font-semibold">{label}</span>
              <span className="text-xs font-normal text-slate-400">{desc}</span>
            </button>
          ))}
        </div>

        {/* Featured match picker — shown when Now Playing is active */}
        {activeView === "current_match" && (() => {
          const partnerMap = Object.fromEntries(allPartners.map((p) => [p.id, p]));
          const liveMatches = allMatches.filter((m) => m.tournament_id === tournament.id && m.status === "in_progress");
          const upcomingMatches = allMatches
            .filter((m) => m.tournament_id === tournament.id && m.status === "scheduled" && m.partner_a_id && m.partner_b_id)
            .sort((a, b) => ((a.scheduled_date || "") + (a.scheduled_time || "")).localeCompare((b.scheduled_date || "") + (b.scheduled_time || "")))
            .slice(0, 8);
          const pickableMatches = [
            ...liveMatches,
            ...upcomingMatches.filter((m) => !liveMatches.some((l) => l.id === m.id)),
          ];
          if (pickableMatches.length === 0) return null;
          return (
            <div className="mt-4 pt-4 border-t border-slate-100">
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Feature a Match</p>
                {featuredMatchId && (
                  <button
                    onClick={() => handleFeaturedMatch(featuredMatchId)}
                    className="text-xs text-slate-400 hover:text-red-400 transition-colors"
                  >
                    Clear
                  </button>
                )}
              </div>
              <p className="text-xs text-slate-400 mb-3">
                Select a match to show in full-screen VS mode. "Auto" shows all live matches.
              </p>
              <div className="space-y-1.5">
                <button
                  onClick={() => { setFeaturedMatchId(null); send({ type: "SET_FEATURED_MATCH", matchId: null }); }}
                  className={`w-full text-left px-3 py-2.5 rounded-xl border-2 text-sm transition-all ${
                    !featuredMatchId
                      ? "border-pickle-green bg-pickle-green/5 text-pickle-green font-semibold"
                      : "border-slate-100 text-slate-500 hover:border-slate-200"
                  }`}
                >
                  <div className="flex items-center gap-2">
                    <span className={`w-2 h-2 rounded-full ${!featuredMatchId ? "bg-pickle-green" : "bg-slate-200"}`} />
                    Auto — Show all live matches
                  </div>
                </button>
                {pickableMatches.map((m) => {
                  const pA = partnerMap[m.partner_a_id];
                  const pB = partnerMap[m.partner_b_id];
                  const isLive = m.status === "in_progress";
                  const isSelected = featuredMatchId === m.id;
                  return (
                    <button
                      key={m.id}
                      onClick={() => handleFeaturedMatch(m.id)}
                      className={`w-full text-left px-3 py-2.5 rounded-xl border-2 text-sm transition-all ${
                        isSelected
                          ? "border-pickle-green bg-pickle-green/5"
                          : "border-slate-100 hover:border-slate-200"
                      }`}
                    >
                      <div className="flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full shrink-0 ${isLive ? "bg-green-500 animate-pulse" : "bg-amber-400"}`} />
                        <div className="flex-1 min-w-0">
                          <div className={`font-semibold truncate ${isSelected ? "text-pickle-green" : "text-slate-700"}`}>
                            {pA?.team_name || "TBD"} <span className="font-normal text-slate-400">vs</span> {pB?.team_name || "TBD"}
                          </div>
                          <div className="text-xs text-slate-400 truncate">
                            {m.court ? `${m.court} · ` : ""}{isLive ? "Live" : (m.scheduled_time || "Scheduled")}
                          </div>
                        </div>
                        {isSelected && (
                          <span className="text-xs font-bold text-pickle-green shrink-0">Featured</span>
                        )}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })()}

        {/* Division filter */}
        {(activeView === "standings" || activeView === "bracket") && divisions.length > 1 && (
          <div className="mt-4 pt-4 border-t border-slate-100">
            <p className="text-xs font-bold text-slate-500 mb-2 uppercase tracking-wider">Filter Division</p>
            <div className="flex flex-wrap gap-2">
              <button
                onClick={() => handleDivisionFilter(null)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium border ${!filterDivisionId ? "bg-pickle-green text-white border-pickle-green" : "border-slate-200 text-slate-600 hover:border-pickle-green/40"}`}
              >
                All Divisions
              </button>
              {divisions.map((d) => (
                <button
                  key={d.id}
                  onClick={() => handleDivisionFilter(d.id)}
                  className={`px-3 py-1.5 rounded-lg text-sm font-medium border ${filterDivisionId === d.id ? "bg-pickle-green text-white border-pickle-green" : "border-slate-200 text-slate-600 hover:border-pickle-green/40"}`}
                >
                  {d.name}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* ── Sponsor management ── */}
      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-5">
        <h3 className="text-sm font-bold text-slate-700 mb-4">Sponsors</h3>

        {/* Add form */}
        <div className="flex gap-2 mb-4">
          <input
            type="text"
            placeholder="Sponsor name"
            value={sponsorName}
            onChange={(e) => setSponsorName(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") handleAddSponsor(); }}
            className="flex-1 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
          />
          <label className="cursor-pointer px-3 py-2 rounded-lg border border-slate-200 text-sm text-slate-600 hover:border-pickle-green/40 flex items-center gap-1.5">
            <Image size={14} />
            Logo
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={handleFileSelect}
            />
          </label>
          <button
            onClick={handleAddSponsor}
            disabled={!sponsorName.trim()}
            className="flex items-center gap-1.5 px-4 py-2 rounded-lg bg-pickle-green text-white text-sm font-semibold disabled:opacity-40 hover:bg-pickle-green/90 transition-colors"
          >
            <Plus size={14} />
            Add
          </button>
        </div>

        {sponsorPreview && (
          <div className="mb-4 p-3 bg-slate-50 rounded-xl flex items-center gap-3">
            <img src={sponsorPreview} alt="Preview" className="h-12 w-12 object-contain rounded" />
            <span className="text-sm text-slate-600">Logo preview — {sponsorName || "unnamed"}</span>
          </div>
        )}

        {/* Sponsor list */}
        {sortedSponsors.length === 0 ? (
          <p className="text-sm text-slate-400 text-center py-4">No sponsors added yet.</p>
        ) : (
          <div className="space-y-2">
            {sortedSponsors.map((s, idx) => (
              <div key={s.id} className="flex items-center gap-3 p-3 rounded-xl border border-slate-100 bg-slate-50">
                <div className="flex flex-col gap-0.5">
                  <button onClick={() => moveSponsor(idx, -1)} disabled={idx === 0} className="text-slate-400 hover:text-slate-600 disabled:opacity-20">
                    <ChevronUp size={14} />
                  </button>
                  <button onClick={() => moveSponsor(idx, 1)} disabled={idx === sortedSponsors.length - 1} className="text-slate-400 hover:text-slate-600 disabled:opacity-20">
                    <ChevronDown size={14} />
                  </button>
                </div>
                <div className="flex-1 font-medium text-slate-800 text-sm">{s.name}</div>
                <button
                  onClick={() => updateSponsor(tournament.id, s.id, { enabled: !s.enabled })}
                  className={`text-sm flex items-center gap-1 ${s.enabled ? "text-pickle-green" : "text-slate-400"}`}
                >
                  {s.enabled ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                  {s.enabled ? "On" : "Off"}
                </button>
                <button
                  onClick={() => handleHighlight(s.id)}
                  className="text-xs px-2.5 py-1 rounded-lg bg-amber-100 text-amber-700 hover:bg-amber-200 font-medium"
                >
                  Highlight
                </button>
                <button onClick={() => handleRemoveSponsor(s.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                  <Trash2 size={15} />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ── Slideshow settings ── */}
      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-5">
        <h3 className="text-sm font-bold text-slate-700 mb-4 flex items-center gap-2">
          <Settings size={14} /> Slideshow Settings
        </h3>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-xs font-bold text-slate-600 mb-1.5 block">View Interval (sec)</label>
            <input
              type="number" min={5} max={120} step={1}
              value={slideshowInterval}
              onChange={(e) => setSlideshowInterval(e.target.value)}
              className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
            />
            <p className="text-xs text-slate-400 mt-1">Seconds per view in auto-slideshow</p>
          </div>
          <div>
            <label className="text-xs font-bold text-slate-600 mb-1.5 block">Sponsor Interval (sec)</label>
            <input
              type="number" min={3} max={60} step={1}
              value={sponsorInterval}
              onChange={(e) => setSponsorInterval(e.target.value)}
              className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
            />
            <p className="text-xs text-slate-400 mt-1">Seconds per sponsor in sponsor show</p>
          </div>
        </div>
        <button
          onClick={saveIntervalSettings}
          className="mt-4 px-4 py-2 rounded-lg bg-pickle-green text-white text-sm font-semibold hover:bg-pickle-green/90 transition-colors"
        >
          Save Settings
        </button>
      </div>
    </div>
  );
}
