import React, { useState, useEffect } from "react";
import { getLogoUrl } from "../../utils/imageStorage";

export default function DisplaySponsor({ sponsor, tournament }) {
  const [logoUrl, setLogoUrl] = useState(null);

  useEffect(() => {
    if (!sponsor?.id) return;
    let url = null;
    getLogoUrl(sponsor.id).then((u) => {
      url = u;
      setLogoUrl(u);
    });
    return () => { if (url) URL.revokeObjectURL(url); };
  }, [sponsor?.id]);

  if (!sponsor) {
    return (
      <div className="flex-1 flex items-center justify-center text-pickle-cream/30 font-oswald text-2xl">
        No Sponsor Selected
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col items-center justify-center gap-6 px-8">
      {logoUrl ? (
        <img
          src={logoUrl}
          alt={sponsor.name}
          className="max-h-[55vh] max-w-[75vw] object-contain drop-shadow-2xl"
        />
      ) : (
        <div className="w-48 h-48 rounded-full bg-white/10 flex items-center justify-center">
          <span className="text-white/30 font-oswald text-4xl uppercase">{sponsor.name?.charAt(0) || "?"}</span>
        </div>
      )}
      <div className="text-pickle-cream font-display text-4xl text-center drop-shadow-lg">{sponsor.name}</div>
      <div className="text-pickle-cream/30 font-body text-base">{tournament?.name}</div>
    </div>
  );
}
