// SideNav.js - Refactored for Mobile Drawer
import React from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { useAppState } from "../../../app/providers";
import { selectQueueState } from "../../../state/selectors";
import { X } from "lucide-react"; // Import Close Icon

// Simple inline icon set (or Lucide if available, sticking to existing if simpler)
const icons = {
  dashboard: <span className="text-lg" aria-hidden="true">📊</span>,
  queue: <span className="text-lg" aria-hidden="true">🎾</span>,
  calendar: <span className="text-lg" aria-hidden="true">📅</span>,
  leaderboard: <span className="text-lg" aria-hidden="true">🏅</span>,
  reports: <span className="text-lg" aria-hidden="true">📈</span>,
  settings: <span className="text-lg" aria-hidden="true">⚙️</span>,
  logout: <span className="text-lg" aria-hidden="true">🚪</span>,
};

export default function SideNav({ collapsed, onToggle, mobileOpen, onMobileClose }) {
  const { userRole, logout } = useAppState(selectQueueState);
  const navigate = useNavigate();

  const base =
    "flex items-center gap-2 w-full px-3 py-2 rounded-md text-sm font-medium transition-all duration-200";
  const active = "bg-pickle-green text-pickle-cream shadow-md ring-1 ring-black/5";
  const idle = "text-pickle-green hover:bg-pickle-green/10 hover:text-pickle-green";

  // Desktop Width Logic
  const widthClass = collapsed ? "w-16" : "w-56";

  const handleLogout = () => {
    logout();
    navigate("/");
  };

  const Content = (
    <div className="flex flex-col h-full bg-pickle-cream">
      {/* Brand + toggle (Desktop) / Close (Mobile) */}
      <div className="flex items-center justify-between px-4 py-4 border-b border-pickle-green/10 bg-pickle-cream shrink-0">

        {/* Mobile: Close Button */}
        <div className="md:hidden flex items-center justify-between w-full">
          <span className="text-xs font-bold uppercase tracking-[0.2em] text-pickle-green/70">Menu</span>
          <button onClick={onMobileClose} className="p-1 rounded-md hover:bg-black/5">
            <X className="w-6 h-6 text-pickle-green" />
          </button>
        </div>

        {/* Desktop: Toggle Button */}
        <div className="hidden md:flex items-center justify-between w-full">
          <button
            type="button"
            onClick={onToggle}
            className="flex items-center justify-center w-8 h-8 rounded-full bg-pickle-green/10 text-pickle-green hover:bg-pickle-green hover:text-pickle-cream transition-colors text-lg"
            aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            <span aria-hidden="true">☰</span>
          </button>

          {!collapsed && (
            <div className="ml-3 text-xs font-bold uppercase tracking-[0.2em] text-pickle-green/70">
              Menu
            </div>
          )}
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-3 py-4 space-y-2 overflow-y-auto bg-pickle-cream custom-scrollbar">

        {/* Admin Only: Dashboard */}
        {userRole === "admin" && (
          <NavLink
            to="/dashboard"
            onClick={onMobileClose} // Auto-close on nav
            className={({ isActive }) => `${base} ${isActive ? active : idle}`}
            title="Dashboard"
          >
            {icons.dashboard}
            <span className={collapsed ? "md:hidden" : ""}>Dashboard</span>
          </NavLink>
        )}

        {/* Everyone: Queue */}
        <NavLink
          to="/queue"
          end
          onClick={onMobileClose}
          className={({ isActive }) => `${base} ${isActive ? active : idle}`}
          title="Queue (OP)"
        >
          {icons.queue}
          <span className={collapsed ? "md:hidden" : ""}>Queue (OP)</span>
        </NavLink>



        <NavLink
          to="/leaderboards"
          onClick={onMobileClose}
          className={({ isActive }) => `${base} ${isActive ? active : idle}`}
          title="Leaderboards"
        >
          {icons.leaderboard}
          <span className={collapsed ? "md:hidden" : ""}>Leaderboards</span>
        </NavLink>

        {/* Everyone: Calendar V2 */}
        <NavLink
          to="/calendar-v2"
          onClick={onMobileClose}
          className={({ isActive }) => `${base} ${isActive ? active : idle}`}
          title="Calendar V2"
        >
          {icons.calendar}
          <span className={collapsed ? "md:hidden" : ""}>Calendar V2</span>
        </NavLink>

        {/* Everyone: Tournaments */}
        <NavLink
          to="/tournament"
          onClick={onMobileClose}
          className={({ isActive }) => `${base} ${isActive ? active : idle}`}
          title="Tournaments"
        >
          <span className="text-lg" aria-hidden="true">🏆</span>
          <span className={collapsed ? "md:hidden" : ""}>Tournaments</span>
        </NavLink>

        {/* Admin Only: History & Settings */}
        {userRole === "admin" && (
          <>

            <NavLink
              to="/history"
              onClick={onMobileClose}
              className={({ isActive }) => `${base} ${isActive ? active : idle}`}
              title="History"
            >
              {icons.reports}
              <span className={collapsed ? "md:hidden" : ""}>History</span>
            </NavLink>

            <NavLink
              to="/settings"
              onClick={onMobileClose}
              className={({ isActive }) => `${base} ${isActive ? active : idle}`}
              title="Settings"
            >
              {icons.settings}
              <span className={collapsed ? "md:hidden" : ""}>Settings</span>
            </NavLink>
          </>
        )}
      </nav>

      {/* Bottom Actions */}
      <div className="p-3 border-t border-pickle-green/10 bg-pickle-cream shrink-0 mb-safe">
        <button
          onClick={handleLogout}
          className={`${base} ${idle} text-red-500 hover:text-red-600 hover:bg-red-50`}
          title="Switch Role"
        >
          {icons.logout}
          <span className={collapsed ? "md:hidden" : ""}>Switch Role</span>
        </button>
      </div>
    </div>
  );

  return (
    <>
      {/* Mobile Drawer Overlay */}
      {mobileOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 md:hidden transition-opacity"
          onClick={onMobileClose}
          aria-hidden="true"
        />
      )}

      {/* Mobile Sidebar (Fixed Drawer) */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-pickle-cream shadow-xl transform transition-transform duration-300 md:hidden border-r border-pickle-green/10
        ${mobileOpen ? "translate-x-0" : "-translate-x-full"}
      `}>
        {Content}
      </aside>

      {/* Desktop Sidebar (Static) */}
      <aside
        className={`hidden md:flex flex-col flex-shrink-0 border-r border-pickle-green/10 bg-pickle-cream text-pickle-green transition-all duration-300 relative ${widthClass}`}
      >
        {Content}
      </aside>
    </>
  );
}

