/**
 * validateScores(scores, settings)
 * Returns { valid: bool, winner: "a"|"b"|null, error: string|null }
 */
export function validateScores(scores, settings) {
  const { points_to_win = 11, win_by = 2, best_of = 1 } = settings;
  const gamesNeeded = Math.ceil(best_of / 2);

  if (!scores || scores.length === 0) {
    return { valid: false, winner: null, error: "At least one game score is required." };
  }

  let aWins = 0;
  let bWins = 0;

  for (const game of scores) {
    const a = Number(game.partner_a);
    const b = Number(game.partner_b);

    if (isNaN(a) || isNaN(b) || a < 0 || b < 0) {
      return { valid: false, winner: null, error: "Invalid score values." };
    }

    const maxScore = Math.max(a, b);
    const diff = Math.abs(a - b);

    if (maxScore < points_to_win) {
      return {
        valid: false,
        winner: null,
        error: `Winner must reach at least ${points_to_win} points.`,
      };
    }

    if (diff < win_by) {
      return {
        valid: false,
        winner: null,
        error: `Winner must lead by at least ${win_by} points.`,
      };
    }

    if (a > b) aWins++;
    else bWins++;
  }

  const winner = aWins >= gamesNeeded ? "a" : bWins >= gamesNeeded ? "b" : null;

  if (!winner) {
    return { valid: false, winner: null, error: "Match winner not yet determined." };
  }

  return { valid: true, winner, error: null };
}

/**
 * determineMatchWinner(scores, settings)
 * Returns "a" | "b" | null
 */
export function determineMatchWinner(scores, settings) {
  const { valid, winner } = validateScores(scores, settings);
  return valid ? winner : null;
}

/**
 * getTournamentSettings(tournament) — extract scoring settings from a tournament record
 */
export function getTournamentSettings(tournament) {
  return {
    points_to_win: tournament.points_to_win || 11,
    win_by: tournament.win_by || 2,
    best_of: tournament.best_of || 1,
  };
}
