import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { Lock, RefreshCw, Download, Trash2 } from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import ConfirmationModal from "../../../common/components/ConfirmationModal";
import toast from "react-hot-toast";

const SCORING_TYPES = [
  { value: "rally", label: "Rally Scoring" },
  { value: "sideout", label: "Side-Out Scoring" },
];

// Format is now configured per-division, not per-tournament.
function LockedBadge() {
  return (
    <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-400">
      <Lock size={9} /> Locked
    </span>
  );
}

export default function SettingsTab({ tournament }) {
  const navigate = useNavigate();
  const {
    updateTournament,
    deleteTournament,
    exportTournamentData,
    regenerateSchedule,
    shuffleAllGroups,
  } = useTournamentState();

  const isStarted = tournament.phase !== "setup";

  const [form, setForm] = useState({
    name: tournament.name || "",
    start_date: tournament.start_date || "",
    end_date: tournament.end_date || "",
    match_duration: tournament.match_duration || 60,
    daily_window_start: tournament.daily_window_start || "08:00",
    daily_window_end: tournament.daily_window_end || "20:00",
    games_per_day: tournament.games_per_day || 4,
    courts: tournament.courts || ["Court 1", "Court 2", "Court 3", "Court 4"],
    points_to_win: tournament.points_to_win || 11,
    win_by: tournament.win_by || 2,
    best_of: tournament.best_of || 3,
    scoring_type: tournament.scoring_type || "rally",
  });
  // Courts as newline-separated string for the textarea
  const [courtsText, setCourtsText] = useState(
    () => (tournament.courts || ["Court 1", "Court 2", "Court 3", "Court 4"]).join("\n")
  );
  const [dirty, setDirty] = useState(false);

  // Confirmation modals
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [confirmRegen, setConfirmRegen] = useState(false);
  const [confirmShuffle, setConfirmShuffle] = useState(false);

  useEffect(() => {
    setForm({
      name: tournament.name || "",
      start_date: tournament.start_date || "",
      end_date: tournament.end_date || "",
      match_duration: tournament.match_duration || 60,
      daily_window_start: tournament.daily_window_start || "08:00",
      daily_window_end: tournament.daily_window_end || "20:00",
      games_per_day: tournament.games_per_day || 4,
      points_to_win: tournament.points_to_win || 11,
      win_by: tournament.win_by || 2,
      best_of: tournament.best_of || 3,
      scoring_type: tournament.scoring_type || "rally",
      courts: tournament.courts || ["Court 1", "Court 2", "Court 3", "Court 4"],
    });
    setCourtsText((tournament.courts || ["Court 1", "Court 2", "Court 3", "Court 4"]).join("\n"));
    setDirty(false);
  }, [tournament.id]);

  const handleChange = (field, value) => {
    setForm((f) => ({ ...f, [field]: value }));
    setDirty(true);
  };

  const handleCourtsChange = (text) => {
    setCourtsText(text);
    const parsed = text
      .split("\n")
      .map((s) => s.trim())
      .filter(Boolean);
    setForm((f) => ({ ...f, courts: parsed.length ? parsed : ["Court 1"] }));
    setDirty(true);
  };

  const handleSave = (e) => {
    e.preventDefault();
    if (!form.name.trim()) {
      toast.error("Tournament name is required.");
      return;
    }
    if (!form.courts?.length) {
      toast.error("At least one court is required.");
      return;
    }
    updateTournament(tournament.id, form);
    setDirty(false);
    toast.success("Settings saved.");
  };

  const handleDelete = () => {
    deleteTournament(tournament.id);
    toast.success("Tournament deleted.");
    navigate("/tournament");
  };

  const handleExport = () => {
    if (exportTournamentData) {
      exportTournamentData(tournament.id);
    }
    toast.success("Exporting tournament data…");
  };

  const handleRegenSchedule = () => {
    if (regenerateSchedule) {
      regenerateSchedule(tournament.id);
      toast.success("Schedule regenerated for unplayed matches.");
    }
    setConfirmRegen(false);
  };

  const handleShuffle = () => {
    if (shuffleAllGroups) {
      shuffleAllGroups(tournament.id);
      toast.success("All groups shuffled.");
    }
    setConfirmShuffle(false);
  };

  return (
    <div className="p-4 md:p-6 space-y-6">
      <form onSubmit={handleSave}>
        {/* Editable config */}
        <SurfaceCard title="Tournament Settings">
          <div className="p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Name */}
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-slate-600 mb-1">Tournament Name</label>
              <input
                type="text"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-pickle-green/30"
                value={form.name}
                onChange={(e) => handleChange("name", e.target.value)}
                placeholder="e.g. Summer Slam 2025"
              />
            </div>

            {/* Dates */}
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Start Date</label>
              <input
                type="date"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.start_date}
                onChange={(e) => handleChange("start_date", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">End Date</label>
              <input
                type="date"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.end_date}
                onChange={(e) => handleChange("end_date", e.target.value)}
              />
            </div>

            {/* Match duration */}
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Match Duration (min)</label>
              <input
                type="number"
                min={15}
                max={180}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.match_duration}
                onChange={(e) => handleChange("match_duration", Number(e.target.value))}
              />
            </div>

            {/* Games per day */}
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Max Games Per Day Per Court</label>
              <input
                type="number"
                min={1}
                max={20}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.games_per_day}
                onChange={(e) => handleChange("games_per_day", Number(e.target.value))}
              />
            </div>

            {/* Daily window */}
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Daily Start Time</label>
              <input
                type="time"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.daily_window_start}
                onChange={(e) => handleChange("daily_window_start", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Daily End Time</label>
              <input
                type="time"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.daily_window_end}
                onChange={(e) => handleChange("daily_window_end", e.target.value)}
              />
            </div>

            {/* Courts */}
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-slate-600 mb-1">
                Courts <span className="font-normal text-slate-400">(one per line)</span>
              </label>
              <textarea
                rows={Math.max(2, form.courts?.length || 4)}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-pickle-green/30 resize-y"
                value={courtsText}
                onChange={(e) => handleCourtsChange(e.target.value)}
                placeholder={"Court 1\nCourt 2\nCourt 3\nCourt 4"}
              />
              <p className="text-xs text-slate-400 mt-1">
                {form.courts?.length || 0} court(s) configured. Used by the auto-scheduler.
              </p>
            </div>

            {/* Locked scoring fields */}
            <div>
              <div className="flex items-center gap-2 mb-1">
                <label className="block text-xs font-semibold text-slate-600">Scoring Type</label>
                {isStarted && <LockedBadge />}
              </div>
              <select
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                value={form.scoring_type}
                onChange={(e) => handleChange("scoring_type", e.target.value)}
                disabled={isStarted}
              >
                {SCORING_TYPES.map((o) => (
                  <option key={o.value} value={o.value}>{o.label}</option>
                ))}
              </select>
            </div>

            <div>
              <div className="flex items-center gap-2 mb-1">
                <label className="block text-xs font-semibold text-slate-600">Points to Win</label>
                {isStarted && <LockedBadge />}
              </div>
              <input
                type="number"
                min={7}
                max={21}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                value={form.points_to_win}
                onChange={(e) => handleChange("points_to_win", Number(e.target.value))}
                disabled={isStarted}
              />
            </div>

            <div>
              <div className="flex items-center gap-2 mb-1">
                <label className="block text-xs font-semibold text-slate-600">Win By</label>
                {isStarted && <LockedBadge />}
              </div>
              <input
                type="number"
                min={1}
                max={2}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                value={form.win_by}
                onChange={(e) => handleChange("win_by", Number(e.target.value))}
                disabled={isStarted}
              />
            </div>

            <div>
              <div className="flex items-center gap-2 mb-1">
                <label className="block text-xs font-semibold text-slate-600">Best Of (games)</label>
                {isStarted && <LockedBadge />}
              </div>
              <select
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                value={form.best_of}
                onChange={(e) => handleChange("best_of", Number(e.target.value))}
                disabled={isStarted}
              >
                <option value={1}>Best of 1</option>
                <option value={3}>Best of 3</option>
                <option value={5}>Best of 5</option>
              </select>
            </div>
          </div>

          <div className="px-4 md:px-6 pb-4 flex justify-end">
            <button
              type="submit"
              disabled={!dirty}
              className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm disabled:opacity-40 disabled:cursor-not-allowed transition-opacity"
            >
              Save Changes
            </button>
          </div>
        </SurfaceCard>
      </form>

      {/* Tools */}
      <SurfaceCard title="Tools">
        <div className="p-4 md:p-6 flex flex-col gap-3">
          <div className="flex items-center justify-between gap-4">
            <div>
              <div className="text-sm font-medium text-slate-700">Shuffle All Groups</div>
              <div className="text-xs text-slate-400 mt-0.5">Randomly redistribute all partners across their groups within each division.</div>
            </div>
            <button
              onClick={() => setConfirmShuffle(true)}
              disabled={isStarted}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium border border-slate-200 text-slate-600 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed whitespace-nowrap"
            >
              <RefreshCw size={12} /> Shuffle
            </button>
          </div>

          <hr className="border-slate-100" />

          <div className="flex items-center justify-between gap-4">
            <div>
              <div className="text-sm font-medium text-slate-700">Regenerate Schedule</div>
              <div className="text-xs text-slate-400 mt-0.5">Re-assign dates, times, and courts for all unplayed matches.</div>
            </div>
            <button
              onClick={() => setConfirmRegen(true)}
              disabled={tournament.phase === "setup"}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium border border-slate-200 text-slate-600 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed whitespace-nowrap"
            >
              <RefreshCw size={12} /> Regenerate
            </button>
          </div>

          <hr className="border-slate-100" />

          <div className="flex items-center justify-between gap-4">
            <div>
              <div className="text-sm font-medium text-slate-700">Export Tournament Data</div>
              <div className="text-xs text-slate-400 mt-0.5">Download a full JSON backup of this tournament.</div>
            </div>
            <button
              onClick={handleExport}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium border border-slate-200 text-slate-600 hover:bg-slate-50 whitespace-nowrap"
            >
              <Download size={12} /> Export
            </button>
          </div>
        </div>
      </SurfaceCard>

      {/* Danger zone */}
      <SurfaceCard title="Danger Zone">
        <div className="p-4 md:p-6">
          <div className="flex items-center justify-between gap-4 p-4 border border-red-200 rounded-xl bg-red-50/50">
            <div>
              <div className="text-sm font-semibold text-red-700">Delete Tournament</div>
              <div className="text-xs text-red-400 mt-0.5">
                Permanently deletes this tournament and all associated data. This cannot be undone.
              </div>
            </div>
            <button
              onClick={() => setConfirmDelete(true)}
              className="flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-semibold text-white bg-red-500 hover:bg-red-600 whitespace-nowrap shadow-sm"
            >
              <Trash2 size={12} /> Delete
            </button>
          </div>
        </div>
      </SurfaceCard>

      {/* Confirmation modals */}
      <ConfirmationModal
        isOpen={confirmDelete}
        title={`Delete "${tournament.name}"?`}
        message="This will permanently delete the tournament and all its divisions, groups, partners, and matches. This action cannot be undone."
        confirmLabel="Delete Tournament"
        isDestructive
        onConfirm={handleDelete}
        onCancel={() => setConfirmDelete(false)}
      />

      <ConfirmationModal
        isOpen={confirmRegen}
        title="Regenerate Schedule?"
        message="This will re-assign dates, times, and courts for all unplayed matches. Already completed matches are not affected."
        confirmLabel="Regenerate"
        onConfirm={handleRegenSchedule}
        onCancel={() => setConfirmRegen(false)}
      />

      <ConfirmationModal
        isOpen={confirmShuffle}
        title="Shuffle All Groups?"
        message="Partners will be randomly redistributed across groups in each division. This only works before the tournament starts."
        confirmLabel="Shuffle"
        onConfirm={handleShuffle}
        onCancel={() => setConfirmShuffle(false)}
      />
    </div>
  );
}
