import React, { useState, useEffect } from "react";

const GENDER_OPTIONS = [
  { value: "mixed", label: "Mixed" },
  { value: "men", label: "Men" },
  { value: "women", label: "Women" },
];

const FORMAT_OPTIONS = [
  { value: "round_robin", label: "Round Robin" },
  { value: "single_elimination", label: "Single Elimination" },
];

const defaults = {
  name: "",
  age_bracket: "",
  gender_category: "mixed",
  max_group_size: 5,
  advance_count: 2,
  format: "round_robin",
};

export default function DivisionFormModal({ division, onSave, onClose }) {
  const [form, setForm] = useState({ ...defaults, ...(division || {}) });

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const set = (key, val) => setForm((prev) => ({ ...prev, [key]: val }));

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;
    onSave({
      ...form,
      max_group_size: Number(form.max_group_size),
      advance_count: Number(form.advance_count),
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <form
        onSubmit={handleSubmit}
        className="relative bg-white rounded-xl shadow-2xl w-full max-w-md flex flex-col"
      >
        <div className="p-6 border-b border-slate-100">
          <h2 className="text-xl font-bold text-slate-900">
            {division ? "Edit Division" : "Add Division"}
          </h2>
        </div>

        <div className="p-6 flex flex-col gap-4">
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">Division Name *</label>
            <input
              className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
              value={form.name}
              onChange={(e) => set("name", e.target.value)}
              placeholder="e.g. 19+ Mixed"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Age Bracket</label>
              <input
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
                value={form.age_bracket}
                onChange={(e) => set("age_bracket", e.target.value)}
                placeholder="e.g. 19+"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Gender</label>
              <select
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.gender_category}
                onChange={(e) => set("gender_category", e.target.value)}
              >
                {GENDER_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
              </select>
            </div>
          </div>

          {/* Format */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">Format</label>
            <div className="grid grid-cols-2 gap-2">
              {FORMAT_OPTIONS.map((o) => (
                <label
                  key={o.value}
                  className={`flex items-center gap-2 border rounded-lg px-3 py-2.5 cursor-pointer transition-colors ${
                    form.format === o.value
                      ? "border-pickle-green bg-pickle-green/5 text-pickle-green"
                      : "border-slate-200 hover:bg-slate-50 text-slate-700"
                  }`}
                >
                  <input
                    type="radio"
                    name="format"
                    value={o.value}
                    checked={form.format === o.value}
                    onChange={() => set("format", o.value)}
                    className="accent-pickle-green"
                  />
                  <span className="text-sm font-medium">{o.label}</span>
                </label>
              ))}
            </div>
            <p className="text-xs text-slate-400 mt-1">
              {form.format === "round_robin"
                ? "All partners in each group play each other. Standings decide advancement."
                : "Partners are seeded into a bracket. Lose once and you're eliminated."}
            </p>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Max Group Size</label>
              <input
                type="number"
                min="2"
                max="20"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.max_group_size}
                onChange={(e) => set("max_group_size", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Advance Count</label>
              <input
                type="number"
                min="1"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.advance_count}
                onChange={(e) => set("advance_count", e.target.value)}
              />
              <p className="text-xs text-slate-400 mt-1">Partners per group advancing to playoffs</p>
            </div>
          </div>
        </div>

        <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
          <button type="button" onClick={onClose} className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100">
            Cancel
          </button>
          <button type="submit" className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm">
            {division ? "Save Changes" : "Add Division"}
          </button>
        </div>
      </form>
    </div>
  );
}
