import config from "../config";
import BaseService from "./BaseService";
import reclubDefaults from "../config/reclub";

/**
 * ReclubService
 * Placeholder integration for Reclub APIs.
 * Configure endpoints, org/location, and API key in client config.
 */
export class ReclubService extends BaseService {
  constructor() {
    const cfg = config.reclub || {};
    const base = cfg.apiBaseUrl || reclubDefaults.apiBaseUrl;
    super(base, {});
  }

  /**
   * Fetch players for a given day.
   * date: ISO string (YYYY-MM-DD) or Date instance.
   * You likely need to pass orgId/locationId in query; wired from config.
   */
  async getPlayersForDate(date) {
    const d = date instanceof Date
      ? date.toISOString().slice(0, 10)
      : String(date || "");
    const { orgId, locationId } = config.reclub || {};
    // TODO: Adjust endpoint/params to match real Reclub API
    return this.request("/players", {
      query: { date: d, orgId, locationId },
    });
  }

  /**
   * Fetch single player details by ID.
   */
  async getPlayerDetails(playerId) {
    // TODO: Adjust endpoint to match real Reclub API
    return this.request(`/players/${encodeURIComponent(playerId)}`);
  }

  /**
   * Fetch multiple players by user IDs (comma-separated or array)
   * Example endpoint: /players/userIds?scopes=BASIC_PROFILE&user_ids=1,2,3
   */
  async getPlayersByUserIds(userIds, { scopes = "BASIC_PROFILE" } = {}) {
    if (!userIds || (Array.isArray(userIds) && userIds.length === 0)) {
      return { players: [] };
    }
    const ids = Array.isArray(userIds) ? [...new Set(userIds)].join(",") : String(userIds);
    return this.request("/players/userIds", {
      headers: {
        Accept: "application/json",
        "x-output-casing": "camelCase",
      },
      query: {
        scopes,
        user_ids: ids,
      },
    });
  }

  /**
   * Fetch meet details by its reference code (e.g., GB7NMN).
   */
  async getMeetByRef(ref) {
    const code = String(ref || "").trim();
    if (!code) throw new Error("Meet code is required");

    return this.request(`/meets/by-ref/${encodeURIComponent(code)}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        "x-output-casing": "camelCase",
      },
    });
  }
}

// Export a ready-to-use singleton instance.
const reclubService = new ReclubService();
export default reclubService;
