import React, { useState, useEffect, useMemo } from "react";
import { ChevronRight, AlertTriangle } from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import BracketView from "./BracketView";
import ScoreEntryModal from "./ScoreEntryModal";
import { calculateGroupStandings } from "../utils/standings";
import toast from "react-hot-toast";

// ── Compact group standings table ───────────────────────────────────────────
function CompactGroupStandings({ group, division, allPartners, allMatches }) {
  const rows = useMemo(
    () => calculateGroupStandings(group.id, allPartners, allMatches),
    [group.id, allPartners, allMatches]
  );
  const advanceCount = division?.advance_count ?? 2;

  if (rows.length === 0) {
    return <p className="px-4 py-4 text-xs text-slate-400 text-center">No partners yet.</p>;
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs">
        <thead className="bg-slate-50 text-[10px] uppercase text-slate-500">
          <tr>
            <th className="text-center px-3 py-1.5 font-semibold w-8">#</th>
            <th className="text-left px-3 py-1.5 font-semibold">Team</th>
            <th className="text-center px-2 py-1.5 font-semibold">W</th>
            <th className="text-center px-2 py-1.5 font-semibold">L</th>
            <th className="text-center px-2 py-1.5 font-semibold">Pts</th>
            <th className="text-center px-2 py-1.5 font-semibold hidden sm:table-cell">PD</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {rows.map((row, idx) => {
            const isAdv = idx < advanceCount;
            return (
              <tr key={row.partner.id} className={isAdv ? "border-l-2 border-l-pickle-green" : ""}>
                <td className={`text-center px-3 py-2 font-bold text-xs ${isAdv ? "text-pickle-green" : "text-slate-400"}`}>{idx + 1}</td>
                <td className="px-3 py-2 font-medium text-slate-800">
                  {row.partner.team_name}
                  {isAdv && <span className="ml-1 text-[9px] font-bold text-pickle-green uppercase">ADV</span>}
                </td>
                <td className="text-center px-2 py-2 font-semibold text-green-600">{row.wins}</td>
                <td className="text-center px-2 py-2 text-red-400">{row.losses}</td>
                <td className="text-center px-2 py-2 font-bold text-slate-700">{row.points}</td>
                <td className={`text-center px-2 py-2 hidden sm:table-cell ${row.pointDiff > 0 ? "text-green-600" : row.pointDiff < 0 ? "text-red-400" : "text-slate-400"}`}>
                  {row.pointDiff > 0 ? `+${row.pointDiff}` : row.pointDiff}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// ── SE Group brackets sub-view ──────────────────────────────────────────────
function SEGroupBrackets({ divGroups, allMatches, allPartners, onScore, onEdit }) {
  const partnerMap = Object.fromEntries(allPartners.map((p) => [p.id, p]));
  return (
    <div className="space-y-4">
      {divGroups.map((g) => {
        const groupMatches = allMatches.filter(
          (m) => m.group_id === g.id && m.phase === "group_stage" && m.round != null
        );
        if (groupMatches.length === 0) return null;
        return (
          <div key={g.id}>
            <div className="px-4 pt-3 pb-1">
              <span className="text-xs font-bold text-slate-700">{g.name}</span>
            </div>
            <BracketView
              matches={groupMatches}
              partners={partnerMap}
              onScore={onScore}
              onEdit={onEdit}
            />
          </div>
        );
      })}
    </div>
  );
}

// ── Main tab ───────────────────────────────────────────────────────────────
export default function BracketingTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getGroupsForDivision,
    getMatchesForTournament,
    getPartnersForTournament,
    getPartnersForDivision,
    recordMatchResult,
    updateMatchPartners,
    advanceDivisionToPlayoffs,
  } = useTournamentState();

  const divisions = getDivisionsForTournament(tournament.id);
  const allMatches = getMatchesForTournament(tournament.id);
  const allPartners = getPartnersForTournament(tournament.id);

  const [selectedDivisionId, setSelectedDivisionId] = useState(() => divisions[0]?.id || "");
  const [subTab, setSubTab] = useState("bracket");
  const [scoreMatch, setScoreMatch] = useState(null);
  const [editMatch, setEditMatch] = useState(null);
  const [editForm, setEditForm] = useState({ partner_a_id: "", partner_b_id: "" });

  const selectedDivision = divisions.find((d) => d.id === selectedDivisionId) || divisions[0];
  const divFormat = selectedDivision?.format || "round_robin";
  const divAdvanceCount = selectedDivision?.advance_count ?? 2;
  const isRR = divFormat === "round_robin";
  const isSE = divFormat === "single_elimination";

  const divGroups = selectedDivision ? getGroupsForDivision(selectedDivision.id) : [];
  const groupCount = divGroups.length;

  // Matches scoped to selected division
  const seGroupMatches = useMemo(() => allMatches.filter(
    (m) => m.phase === "group_stage" && m.division_id === selectedDivision?.id && m.round != null
  ), [allMatches, selectedDivision?.id]);

  const divPlayoffMatches = useMemo(() => allMatches.filter(
    (m) => m.phase === "playoff" && m.division_id === selectedDivision?.id
  ), [allMatches, selectedDivision?.id]);

  const hasPlayoffBracket = divPlayoffMatches.length > 0;

  // Pending group-stage matches for this division
  const divPendingGroupMatches = useMemo(() => allMatches.filter(
    (m) =>
      m.division_id === selectedDivision?.id &&
      m.phase === "group_stage" &&
      !["completed", "bye", "cancelled"].includes(m.status)
  ).length, [allMatches, selectedDivision?.id]);

  /**
   * Determines whether a separate playoff bracket is needed for this division.
   *
   * No playoff needed:
   *  - SE + 1 group: the group bracket IS the final
   *  - RR + 1 group + advance_count=1: group winner = champion
   *
   * Playoff needed for all other cases.
   */
  const needsPlayoffs = useMemo(() => {
    if (!selectedDivision) return false;
    if (isSE && groupCount === 1) return false;       // SE 1 group = already final
    if (isRR && groupCount === 1 && divAdvanceCount <= 1) return false; // RR 1 group 1 winner = champion
    return true;
  }, [selectedDivision, isSE, isRR, groupCount, divAdvanceCount]);

  /**
   * Explanation label shown when no advance is needed
   */
  const noPlayoffReason = useMemo(() => {
    if (!selectedDivision) return null;
    if (isSE && groupCount === 1) return "Single Elimination with 1 group — this bracket IS the final.";
    if (isRR && groupCount === 1 && divAdvanceCount <= 1) return "Round Robin with 1 winner — group winner is the champion.";
    return null;
  }, [selectedDivision, isSE, isRR, groupCount, divAdvanceCount]);

  const partnerMap = Object.fromEntries(allPartners.map((p) => [p.id, p]));
  const divisionPartners = selectedDivision ? getPartnersForDivision(selectedDivision.id) : [];

  // What to display in bracket view
  // Priority: playoff bracket > SE group bracket > nothing
  const bracketMatches = hasPlayoffBracket ? divPlayoffMatches : seGroupMatches;

  // Sub-tabs logic
  const showStandingsTab = isRR;
  const showSEGroupsTab = isSE && !hasPlayoffBracket && seGroupMatches.length > 0;
  const showBracketTab = hasPlayoffBracket || (isSE && seGroupMatches.length > 0);

  const subTabs = [
    ...(showStandingsTab ? [{ key: "standings", label: "Group Standings" }] : []),
    ...(showSEGroupsTab ? [{ key: "bracket", label: `SE Draw (${groupCount} Group${groupCount > 1 ? "s" : ""})` }] : []),
    ...(hasPlayoffBracket ? [{ key: "bracket", label: "Playoff Bracket" }] : []),
    ...(!showBracketTab && !showStandingsTab ? [{ key: "bracket", label: "Bracket" }] : []),
  ];
  // Deduplicate (keep unique keys in order)
  const uniqueSubTabs = subTabs.filter((t, i, arr) => arr.findIndex((x) => x.key === t.key) === i);

  // Reset sub-tab when division changes
  useEffect(() => {
    setSubTab(isRR ? "standings" : "bracket");
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDivisionId]);

  useEffect(() => {
    if (!editMatch) return;
    const handler = (e) => { if (e.key === "Escape") setEditMatch(null); };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [editMatch]);

  const handleSaveResult = (scores) => {
    if (!scoreMatch) return;
    recordMatchResult(scoreMatch.id, scores, tournament.id);
    setScoreMatch(null);
    toast.success("Result recorded.");
  };

  const handleOpenEdit = (match) => {
    setEditMatch(match);
    setEditForm({
      partner_a_id: match.partner_a_id || "",
      partner_b_id: match.partner_b_id || "",
    });
  };

  const handleSaveEdit = (e) => {
    e.preventDefault();
    if (!editMatch) return;
    if (editForm.partner_a_id && editForm.partner_a_id === editForm.partner_b_id) {
      toast.error("Partner A and Partner B must be different.");
      return;
    }
    updateMatchPartners(editMatch.id, {
      partner_a_id: editForm.partner_a_id || null,
      partner_b_id: editForm.partner_b_id || null,
    });
    setEditMatch(null);
    toast.success("Bracket match updated.");
  };

  const handleAdvanceDivision = (force = false) => {
    if (!selectedDivision) return;
    advanceDivisionToPlayoffs(selectedDivision.id, force);
  };

  if (tournament.phase === "setup") {
    return (
      <div className="p-6 text-center text-slate-400 text-sm">
        Start the tournament to use the bracketing view.
      </div>
    );
  }

  if (divisions.length === 0) {
    return <div className="p-6 text-center text-slate-400 text-sm">No divisions found.</div>;
  }

  // Build the SurfaceCard header actions for this division
  const cardActions = (() => {
    if (!selectedDivision) return null;

    // Already has playoff bracket
    if (hasPlayoffBracket) return null;

    // SE + 1 group or RR + 1 winner: no playoff needed, show info
    if (!needsPlayoffs) {
      return (
        <span className="text-xs text-slate-400 italic">{noPlayoffReason}</span>
      );
    }

    // Needs playoffs: show advance button
    return (
      <div className="flex items-center gap-2 flex-wrap justify-end">
        {divPendingGroupMatches > 0 && (
          <span className="text-xs text-amber-600 font-medium">
            {divPendingGroupMatches} pending
          </span>
        )}
        <button
          onClick={() => handleAdvanceDivision(false)}
          className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm"
          title={`Generate playoff bracket for ${selectedDivision.name}`}
        >
          Generate Playoffs <ChevronRight size={12} />
        </button>
        {divPendingGroupMatches > 0 && (
          <button
            onClick={() => handleAdvanceDivision(true)}
            className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-amber-700 border border-amber-300 bg-amber-50 hover:bg-amber-100"
            title="Force advance even with incomplete matches"
          >
            <AlertTriangle size={11} /> Force
          </button>
        )}
      </div>
    );
  })();

  const cardTitle = (() => {
    if (!selectedDivision) return "Division";
    if (hasPlayoffBracket) return `${selectedDivision.name} — Playoff Bracket`;
    if (isSE && groupCount === 1) return `${selectedDivision.name} — Final Bracket`;
    if (isRR && groupCount === 1 && divAdvanceCount <= 1) return `${selectedDivision.name} — Group Standings`;
    if (isSE) return `${selectedDivision.name} — Group Draws`;
    return `${selectedDivision.name} — Group Standings`;
  })();

  return (
    <div className="p-4 md:p-6 space-y-4">
      {/* Division tabs */}
      <div className="flex overflow-x-auto border-b border-slate-200 -mb-1">
        {divisions.map((d) => (
          <button
            key={d.id}
            onClick={() => {
              setSelectedDivisionId(d.id);
              setSubTab(d.format === "round_robin" ? "standings" : "bracket");
            }}
            className={`px-4 py-2.5 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
              selectedDivisionId === d.id
                ? "border-pickle-green text-pickle-green"
                : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
            }`}
          >
            {d.name}
            {/* Badge: playoff status */}
            {(() => {
              const dPlayoffs = allMatches.filter((m) => m.phase === "playoff" && m.division_id === d.id);
              if (dPlayoffs.length > 0) {
                const done = dPlayoffs.every((m) => ["completed", "bye", "cancelled"].includes(m.status));
                return done
                  ? <span className="ml-1.5 text-[9px] font-bold text-green-600 bg-green-50 border border-green-200 rounded px-1">✓</span>
                  : <span className="ml-1.5 text-[9px] font-bold text-pickle-green bg-pickle-green/10 border border-pickle-green/20 rounded px-1">PO</span>;
              }
              return null;
            })()}
          </button>
        ))}
      </div>

      <SurfaceCard title={cardTitle} actions={cardActions}>
        {/* Sub-tab navigation */}
        {uniqueSubTabs.length > 1 && (
          <div className="flex border-b border-slate-100 px-4">
            {uniqueSubTabs.map((t) => (
              <button
                key={t.key}
                onClick={() => setSubTab(t.key)}
                className={`px-3 py-2 text-xs font-semibold border-b-2 transition-colors mr-1 ${
                  subTab === t.key
                    ? "border-pickle-green text-pickle-green"
                    : "border-transparent text-slate-500 hover:text-slate-700"
                }`}
              >
                {t.label}
              </button>
            ))}
          </div>
        )}

        {/* Standings sub-tab */}
        {subTab === "standings" && (
          <div className="space-y-0 divide-y divide-slate-100">
            {divGroups.length === 0 ? (
              <p className="px-4 py-8 text-sm text-slate-400 text-center">No groups in this division.</p>
            ) : (
              divGroups.map((group) => (
                <div key={group.id}>
                  <div className="px-4 pt-3 pb-1">
                    <span className="text-xs font-bold text-slate-700">{group.name}</span>
                  </div>
                  <CompactGroupStandings
                    group={group}
                    division={selectedDivision}
                    allPartners={allPartners}
                    allMatches={allMatches}
                  />
                </div>
              ))
            )}
            {selectedDivision && divGroups.length > 0 && needsPlayoffs && !hasPlayoffBracket && (
              <div className="flex items-center gap-2 px-4 py-2 text-xs text-slate-400">
                <span className="inline-block w-1.5 h-4 bg-pickle-green rounded-sm" />
                Top {selectedDivision.advance_count ?? 2} per group advance to playoffs
              </div>
            )}
            {selectedDivision && !needsPlayoffs && groupCount === 1 && isRR && (
              <div className="flex items-center gap-2 px-4 py-2 text-xs text-pickle-green font-semibold">
                🏆 Group winner is the division champion
              </div>
            )}
          </div>
        )}

        {/* Bracket sub-tab */}
        {subTab === "bracket" && (
          <>
            {/* SE with multiple groups: show per-group SE draws */}
            {isSE && !hasPlayoffBracket && seGroupMatches.length > 0 && (
              <SEGroupBrackets
                divGroups={divGroups}
                allMatches={allMatches}
                allPartners={allPartners}
                onScore={(match) => setScoreMatch(match)}
                onEdit={handleOpenEdit}
              />
            )}

            {/* Playoff bracket */}
            {hasPlayoffBracket && (
              <BracketView
                matches={divPlayoffMatches}
                partners={partnerMap}
                onScore={(match) => setScoreMatch(match)}
                onEdit={handleOpenEdit}
              />
            )}

            {/* Empty state */}
            {!hasPlayoffBracket && seGroupMatches.length === 0 && (
              <div className="px-4 py-10 text-center text-sm text-slate-400">
                {isSE
                  ? "Generate the SE bracket for each group in the Divisions & Groups tab."
                  : needsPlayoffs
                  ? "Complete group matches then generate playoffs using the button above."
                  : "Generate matches in the Divisions & Groups tab to get started."}
              </div>
            )}
          </>
        )}
      </SurfaceCard>

      {/* Score entry modal */}
      {scoreMatch && (
        <ScoreEntryModal
          match={scoreMatch}
          partnerA={scoreMatch.partner_a_id ? partnerMap[scoreMatch.partner_a_id] : null}
          partnerB={scoreMatch.partner_b_id ? partnerMap[scoreMatch.partner_b_id] : null}
          tournament={tournament}
          onSave={handleSaveResult}
          onClose={() => setScoreMatch(null)}
        />
      )}

      {/* Edit bracket participants modal */}
      {editMatch && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setEditMatch(null)} />
          <form
            onSubmit={handleSaveEdit}
            className="relative bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col"
          >
            <div className="p-6 border-b border-slate-100">
              <h2 className="text-lg font-bold text-slate-900">Edit Match Participants</h2>
              <p className="text-xs text-slate-400 mt-1">
                Changing participants will reset this match's result and status.
              </p>
            </div>
            <div className="p-6 flex flex-col gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Partner A (Top Slot)</label>
                <select
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
                  value={editForm.partner_a_id}
                  onChange={(e) => setEditForm((f) => ({ ...f, partner_a_id: e.target.value }))}
                >
                  <option value="">— TBD —</option>
                  {divisionPartners.map((p) => (
                    <option key={p.id} value={p.id}>{p.team_name}</option>
                  ))}
                </select>
              </div>
              <div className="text-center text-xs font-bold text-slate-400 uppercase tracking-wide">vs</div>
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Partner B (Bottom Slot)</label>
                <select
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
                  value={editForm.partner_b_id}
                  onChange={(e) => setEditForm((f) => ({ ...f, partner_b_id: e.target.value }))}
                >
                  <option value="">— TBD —</option>
                  {divisionPartners.map((p) => (
                    <option key={p.id} value={p.id}>{p.team_name}</option>
                  ))}
                </select>
              </div>
            </div>
            <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
              <button
                type="button"
                onClick={() => setEditMatch(null)}
                className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-amber-500 hover:bg-amber-600 shadow-sm"
              >
                Save Changes
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}
