import React, { useState, useEffect, useRef, useMemo } from "react";
import { useParams } from "react-router-dom";
import useTournamentDisplay from "./hooks/useTournamentDisplay";
import DisplayHeader from "./components/display/DisplayHeader";
import DisplayTournamentInfo from "./components/display/DisplayTournamentInfo";
import DisplayCurrentMatch from "./components/display/DisplayCurrentMatch";
import DisplayLiveCourts from "./components/display/DisplayLiveCourts";
import DisplayStandings from "./components/display/DisplayStandings";
import DisplayBracket from "./components/display/DisplayBracket";
import DisplayUpcoming from "./components/display/DisplayUpcoming";
import DisplayResults from "./components/display/DisplayResults";
import DisplaySponsor from "./components/display/DisplaySponsor";
import DisplaySponsorSlideshow from "./components/display/DisplaySponsorSlideshow";
import DisplaySlideshow from "./components/display/DisplaySlideshow";

export default function TournamentDisplayPage() {
  const { tournamentId } = useParams();
  const {
    tournament,
    divisions: divMap,
    groups: grpMap,
    partners: partMap,
    matches: matchMap,
    getDivisionsForTournament,
    getMatchesForTournament,
    getPartnersForTournament,
  } = useTournamentDisplay(tournamentId);

  const [activeView, setActiveView] = useState("tournament_info");
  const [filterDivisionId, setFilterDivisionId] = useState(null);
  const [activeSponsorId, setActiveSponsorId] = useState(null);
  const [featuredMatchId, setFeaturedMatchId] = useState(null);
  const [slideIndex, setSlideIndex] = useState(0);
  const [totalSlides, setTotalSlides] = useState(1);
  const bcRef = useRef(null);

  // Derived arrays
  const divisions = useMemo(() => getDivisionsForTournament(tournamentId), [getDivisionsForTournament, tournamentId]);
  const allMatches = useMemo(() => getMatchesForTournament(tournamentId), [getMatchesForTournament, tournamentId]);
  const allPartners = useMemo(() => getPartnersForTournament(tournamentId), [getPartnersForTournament, tournamentId]);
  const groups = useMemo(() => Object.values(grpMap).filter((g) => g.tournament_id === tournamentId), [grpMap, tournamentId]);

  // BroadcastChannel for remote control
  useEffect(() => {
    if (!tournamentId) return;
    const channelName = `tournament_display_${tournamentId}`;
    let bc = null;
    try {
      bc = new BroadcastChannel(channelName);
      bc.onmessage = (e) => {
        const { type, view, divisionId, sponsorId, matchId } = e.data || {};
        if (type === "CHANGE_VIEW" && view) {
          setActiveView(view);
          if (matchId !== undefined) setFeaturedMatchId(matchId || null);
        }
        if (type === "SET_DIVISION") setFilterDivisionId(divisionId || null);
        if (type === "SET_SPONSOR") setActiveSponsorId(sponsorId || null);
        if (type === "SET_FEATURED_MATCH") setFeaturedMatchId(matchId || null);
        // Reply with status
        try {
          bc.postMessage({ type: "DISPLAY_STATUS", view: activeView, connected: true });
        } catch {}
      };
      bcRef.current = bc;
      // Heartbeat
      const heartbeat = setInterval(() => {
        try { bc.postMessage({ type: "DISPLAY_STATUS", view: activeView, connected: true }); } catch {}
      }, 10000);
      return () => {
        clearInterval(heartbeat);
        bc.close();
        bcRef.current = null;
      };
    } catch {
      return undefined;
    }
  }, [tournamentId]);

  // Keep heartbeat view in sync
  useEffect(() => {
    if (bcRef.current) {
      try { bcRef.current.postMessage({ type: "DISPLAY_STATUS", view: activeView, connected: true }); } catch {}
    }
  }, [activeView]);

  const activeSponsor = useMemo(() => {
    if (!activeSponsorId || !tournament) return null;
    return (tournament.sponsors || []).find((s) => s.id === activeSponsorId) || null;
  }, [activeSponsorId, tournament]);

  if (!tournament) {
    return (
      <div className="min-h-screen bg-pickle-dgreen flex items-center justify-center text-center p-8">
        <div>
          <div className="font-display text-5xl text-pickle-cream mb-4">Tournament Not Found</div>
          <div className="text-pickle-cream/40 font-body text-lg">Check the URL and try again.</div>
        </div>
      </div>
    );
  }

  const sharedProps = {
    tournament,
    divisions,
    groups,
    partners: allPartners,
    matches: allMatches,
    filterDivisionId,
    featuredMatchId,
  };

  function renderView() {
    switch (activeView) {
      case "current_match": return <DisplayCurrentMatch {...sharedProps} />;
      case "live_courts": return <DisplayLiveCourts {...sharedProps} />;
      case "standings": return <DisplayStandings {...sharedProps} />;
      case "bracket": return <DisplayBracket {...sharedProps} />;
      case "upcoming": return <DisplayUpcoming {...sharedProps} />;
      case "results": return <DisplayResults {...sharedProps} />;
      case "sponsor_highlight": return <DisplaySponsor sponsor={activeSponsor} tournament={tournament} />;
      case "sponsor_slideshow": return <DisplaySponsorSlideshow tournament={tournament} />;
      case "slideshow": return (
        <DisplaySlideshow
          {...sharedProps}
          onSlideChange={(idx, total) => { setSlideIndex(idx); setTotalSlides(total); }}
        />
      );
      case "tournament_info":
      default:
        return <DisplayTournamentInfo {...sharedProps} />;
    }
  }

  return (
    <div className="min-h-screen bg-pickle-dgreen flex flex-col overflow-hidden font-body">
      <DisplayHeader
        tournament={tournament}
        activeView={activeView}
        slideIndex={slideIndex}
        totalSlides={totalSlides}
      />
      <main className="flex-1 flex flex-col overflow-hidden">
        {renderView()}
      </main>
    </div>
  );
}
