import React, { useMemo } from "react";
import { MapPin } from "lucide-react";

function fmt12(time24) {
  if (!time24) return "—";
  const [h, m] = time24.split(":").map(Number);
  const ampm = h >= 12 ? "PM" : "AM";
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${ampm}`;
}

export default function DisplayUpcoming({ tournament, matches, partners, divisions }) {
  const partnerMap = useMemo(() => Object.fromEntries(partners.map((p) => [p.id, p])), [partners]);
  const divMap = useMemo(() => Object.fromEntries(divisions.map((d) => [d.id, d])), [divisions]);

  const upcoming = useMemo(() => {
    return matches
      .filter((m) => m.tournament_id === tournament.id && m.status === "scheduled" && m.partner_a_id && m.partner_b_id)
      .sort((a, b) => {
        const da = (a.scheduled_date || "9999") + (a.scheduled_time || "99:99");
        const db = (b.scheduled_date || "9999") + (b.scheduled_time || "99:99");
        return da.localeCompare(db);
      })
      .slice(0, 8); // Show next 8 matches based on schedule
  }, [matches, tournament.id]);

  if (upcoming.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center text-center">
        <div className="text-pickle-cream/30 font-oswald font-bold text-4xl uppercase tracking-widest">No Upcoming Matches</div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col justify-center p-6 overflow-auto">
      <div className="max-w-5xl mx-auto w-full space-y-3">
        {upcoming.map((m, idx) => {
          const teamA = partnerMap[m.partner_a_id];
          const teamB = partnerMap[m.partner_b_id];
          const div = divMap[m.division_id];
          return (
            <div
              key={m.id}
              className={`flex items-center gap-6 rounded-2xl px-7 py-5 ${idx % 2 === 0 ? "bg-white/10" : "bg-white/5"}`}
            >
              {/* Time + Date */}
              <div className="w-28 shrink-0 text-right">
                <div className="font-oswald font-bold text-pickle-cream text-2xl leading-tight">{fmt12(m.scheduled_time)}</div>
                {m.scheduled_date && (
                  <div className="text-pickle-cream/40 text-base font-body mt-0.5">
                    {new Date(m.scheduled_date + "T12:00:00").toLocaleDateString([], { month: "short", day: "numeric" })}
                  </div>
                )}
              </div>

              {/* Court */}
              <div className="w-28 shrink-0 flex items-center gap-2 text-pickle-cream/50 text-xl font-body">
                <MapPin size={16} />
                <span className="truncate">{m.court || "—"}</span>
              </div>

              {/* Teams */}
              <div className="flex-1 font-oswald font-bold text-white text-2xl min-w-0">
                <span>{teamA?.team_name || "TBD"}</span>
                <span className="text-white/35 text-xl mx-3">vs</span>
                <span>{teamB?.team_name || "TBD"}</span>
              </div>

              {/* Division */}
              {div && (
                <div className="text-pickle-cream/40 text-lg font-body shrink-0">{div.name}</div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
