import React from "react";

const formatCurrency = (val) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val || 0);

export default function RevenueDetailModal({ isOpen, onClose, data, range }) {
    if (!isOpen || !data) return null;

    const { openPlay, rentals, payments } = data;
    const totalIncome = (openPlay?.totalIncome || 0) + (rentals?.totalIncome || 0);

    // Aggregate total payments across OP and Rentals
    const aggregatedPayments = [
        { label: "Cash", color: "bg-emerald-500", ...payments.openPlay.cash },
        { label: "GCash", color: "bg-sky-500", ...payments.openPlay.gcash },
        { label: "GoTyme", color: "bg-purple-500", ...payments.openPlay.gotyme },
        { label: "Unpaid", color: "bg-amber-500", ...payments.openPlay.notPaid },
        { label: "Free", color: "bg-slate-400", ...payments.openPlay.free },
    ].map(p => {
        const ren = payments.rentals[p.label.toLowerCase() === 'unpaid' ? 'notPaid' : p.label.toLowerCase()] || { count: 0, amount: 0 };
        return {
            ...p,
            totalCount: (p.count || 0) + (ren.count || 0),
            totalAmount: (p.amount || 0) + (ren.amount || 0)
        };
    });

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-white sticky top-0">
                    <div>
                        <h2 className="text-lg font-bold text-slate-900">Revenue Details</h2>
                        <p className="text-xs text-slate-500 uppercase tracking-wide">{range} Report</p>
                    </div>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-100 text-slate-500 transition-colors">✕</button>
                </div>

                <div className="p-6 overflow-y-auto">
                    <div className="text-center mb-8">
                        <p className="text-sm text-slate-500 mb-1">Total Income</p>
                        <h1 className="text-4xl font-bold text-slate-900 tracking-tight">{formatCurrency(totalIncome)}</h1>
                    </div>

                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Breakdown by Payment Method</h3>
                    <div className="space-y-3">
                        {aggregatedPayments.map((p, i) => (
                            <div key={i} className="flex items-center justify-between p-3 rounded-lg border border-slate-50 hover:border-slate-100 bg-slate-50/50 transition-colors">
                                <div className="flex items-center gap-3">
                                    <div className={`w-2.5 h-2.5 rounded-full ${p.color}`}></div>
                                    <span className="font-medium text-slate-700 text-sm">{p.label}</span>
                                </div>
                                <div className="text-right">
                                    <div className="text-sm font-bold text-slate-900">{formatCurrency(p.totalAmount)}</div>
                                    <div className="text-[10px] text-slate-400">{p.totalCount} transactions</div>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="mt-8 pt-6 border-t border-slate-100">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Sources</h3>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-3 bg-indigo-50 rounded-lg">
                                <div className="text-xs text-indigo-600 font-medium mb-1">Open Play</div>
                                <div className="text-lg font-bold text-indigo-900">{formatCurrency(openPlay.totalIncome)}</div>
                            </div>
                            <div className="p-3 bg-emerald-50 rounded-lg">
                                <div className="text-xs text-emerald-600 font-medium mb-1">Rentals</div>
                                <div className="text-lg font-bold text-emerald-900">{formatCurrency(rentals.totalIncome)}</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
