import React, { useMemo, useEffect } from "react";
import LevelAvatar from "./LevelAvatar";

export default function PlayersModal({ open, courtName, players, onClose, onSpeak, variant }) {
  // 🧠 Always call hooks — even if modal is closed
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  // modal uses a clean, static background

  // 🎨 Level colors for avatar frame
  const levelColor = useMemo(
    () => ({
      Beginner: "#F59E0B",          // amber-500
      "Low Intermediate": "#22C55E", // green-500
      "High Intermediate": "#3B82F6",// blue-500
      Advance: "#8B5CF6",            // violet-500
    }),
    []
  );

  const sortedPlayers = useMemo(() => {
    const teamOrder = { blue: 0, green: 1 };
    return [...players].sort((a, b) => {
      const aRank = teamOrder[a.team] ?? 2;
      const bRank = teamOrder[b.team] ?? 2;
      if (aRank !== bRank) return aRank - bRank;
      return (a.name || "").localeCompare(b.name || "");
    });
  }, [players]);

  // 🧱 If not open, render nothing
  if (!open) return null;

  // Render NEW Display Variant
  if (variant === "display") {
    const courtNum = courtName.replace(/[^0-9]/g, "") || "?";
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center p-8">
        {/* Backdrop */}
        <div className="absolute inset-0 bg-black/95 backdrop-blur-md" onClick={onClose} />

        {/* 
            Container: 
            - Use flex row for side-by-side. 
        */}
        <div className="relative w-full max-w-[95vw] h-[85vh] bg-pickle-cream rounded-[3rem] overflow-hidden shadow-2xl flex border-8 border-white">

          {/* Left: Giant Number */}
          {/* Increased width alloc to 35% to give it more breathing room if needed, or stick to 30% but allow font to burst */}
          <div className="w-[35%] flex items-center justify-center border-r-4 border-pickle-dgreen/10 bg-pickle-cream">
            <span className="text-[70vh] leading-none font-oswald font-bold text-pickle-dgreen select-none drop-shadow-sm">
              {courtNum}
            </span>
          </div>

          {/* Right: Players List */}
          <div className="flex-1 flex flex-col px-12 py-10">
            {/* Header */}
            <div className="mb-8 text-center">
              <h2 className="text-[7vh] font-black font-anton uppercase text-pickle-dgreen leading-none tracking-tight">
                Court Players
              </h2>
            </div>

            {/* List Container - vertically centered */}
            <div className="flex-1 flex flex-col justify-center gap-[3vh]">
              {sortedPlayers.length === 0 ? (
                <div className="text-center text-[6vh] text-pickle-dgreen/40 font-oswald uppercase">Empty Court</div>
              ) : (
                sortedPlayers.map((p) => (
                  <div key={p.id} className="flex-1 bg-pickle-dgreen rounded-full flex items-center px-6 gap-8 hover:scale-[1.01] transition-transform shadow-md border-4 border-pickle-cream/30 min-h-[14vh] justify-between">

                    <div className="flex items-center gap-6 overflow-hidden flex-1">
                      {/* Avatar - Larger */}
                      <div className="h-[11vh] w-[11vh] rounded-full bg-white border-4 border-pickle-gold flex items-center justify-center overflow-hidden shrink-0">
                        {p.imageUrl || p.photo ? (
                          <img src={p.imageUrl || p.photo} alt={p.name} className="w-full h-full object-cover" />
                        ) : (
                          <span className="text-[6vh]">😎</span>
                        )}
                      </div>

                      {/* Name - Significantly Larger */}
                      <span className="block text-[8vh] font-oswald font-bold text-white uppercase tracking-wide truncate leading-none pt-2">
                        {p.name}
                      </span>
                    </div>

                    {/* Matches - Adjusted size */}
                    <span className="text-[5vh] font-oswald text-pickle-gold/90 font-bold shrink-0">
                      ({p.matches ?? 0})
                    </span>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Render DEFAULT / EXISTING Modal
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />

      {/* Modal Card */}
      <div className="relative bg-white rounded-xl shadow-3xl w-[min(98vw,1080px)] p-8 animate-[fadeIn_120ms_ease-out] flex gap-6 scale-[0.85] origin-center">
        {/* Left: Large Court Number */}
        <div className="flex-shrink-0 flex items-center justify-center w-1/4">
          <h1 className="text-[25rem] font-extrabold text-[#1E3A8A] leading-none select-none">
            {courtName.replace(/[^0-9]/g, "") || "?"}
          </h1>
        </div>

        {/* Right: Player List + Controls */}
        <div className="flex-1">
          {/* Header */}
          <div className="relative mb-5 text-center">
            <h3 className="text-4xl font-bold text-[#1E3A8A]">
              {courtName} — Players
            </h3>
            <button
              onClick={onClose}
              className="absolute right-0 top-0 text-gray-500 hover:text-gray-700 text-base"
              aria-label="Close"
            >
              ✖
            </button>
          </div>

          {/* Player list */}
          <ul className="space-y-2 mb-4">
            {players.length === 0 ? (
              <li className="text-gray-600 text-lg">No players assigned.</li>
            ) : (
              sortedPlayers.map((p) => {
                const teamClass =
                  p.team === "green"
                    ? "bg-gradient-to-r from-green-100 via-green-50 to-white border border-green-200"
                    : p.team === "blue"
                      ? "bg-gradient-to-r from-blue-100 via-blue-50 to-white border border-blue-200"
                      : "bg-white border border-gray-200";
                const teamLabel = p.team === "green" ? "Green Team" : p.team === "blue" ? "Blue Team" : null;
                return (
                  <li
                    key={p.id}
                    className={`relative overflow-hidden flex items-center justify-between rounded-lg px-4 py-3 ${teamClass}`}
                  >
                    <div className="flex items-center w-full relative justify-between z-10">
                      <div className="flex items-center gap-5">
                        <LevelAvatar
                          src={p.imageUrl || p.photo || p.avatarUrl || null}
                          alt={p.name}
                          fallback={p.name}
                          frameColor={levelColor[p.level] || "#3B82F6"}
                          size={120}
                          ring={5}
                          gap={3}
                        />
                        <div className="flex flex-col gap-1">
                          <span
                            className="text-5xl md:text-[6rem] font-extrabold text-[#1E3A8A] leading-none break-words text-left"
                            style={{ textShadow: "0 2px 4px rgba(0,0,0,0.25)" }}
                          >
                            {p.name}
                          </span>
                          {teamLabel && (
                            <span
                              className={`w-max text-xs font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full ${p.team === "green" ? "bg-green-600/90 text-white" : "bg-blue-700/90 text-white"
                                }`}
                            >
                              {teamLabel}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>

                    <span className="relative z-10 text-xs text-gray-700 whitespace-nowrap bg-white/70 rounded px-2 py-1">
                      ({p.matches})
                    </span>

                  </li>
                );
              })
            )}
          </ul>

          {/* Buttons */}
          <div className="flex items-center justify-end gap-2">
            <button
              onClick={onSpeak}
              className="bg-[#1E3A8A] text-white px-4 py-2 rounded hover:bg-[#243c90] text-sm"
            >
              🔊 Speak Names
            </button>
            <button
              onClick={onClose}
              className="px-3 py-2 rounded border text-sm hover:bg-gray-50"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div >
  );
}

