import React from "react";

/**
 * Global Error Boundary
 * Wraps the entire application or major routes to catch runtime errors.
 * Provides options to Reload or Reset Data (clear localStorage).
 */
class GlobalErrorBoundary extends React.Component {
    constructor(props) {
        super(props);
        this.state = { hasError: false, error: null, errorInfo: null };
    }

    static getDerivedStateFromError(error) {
        // Update state so the next render will show the fallback UI.
        return { hasError: true, error };
    }

    componentDidCatch(error, errorInfo) {
        // You can also log the error to an error reporting service
        console.error("Uncaught error:", error, errorInfo);
        this.setState({ errorInfo });
    }

    handleReload = () => {
        window.location.reload();
    };



    render() {
        if (this.state.hasError) {
            return (
                <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
                    <div className="bg-white p-8 rounded-2xl shadow-xl max-w-lg w-full border border-slate-100">
                        <div className="mb-6">
                            <span className="text-6xl">🤕</span>
                        </div>
                        <h1 className="text-2xl font-bold text-slate-800 mb-2">
                            Oops! Something went wrong.
                        </h1>
                        <p className="text-slate-500 mb-6">
                            We encountered an unexpected error. Usually reloading the page fixes this.
                        </p>

                        {this.state.error && (
                            <div className="text-left bg-red-50 p-4 rounded-lg mb-6 border border-red-100 overflow-auto max-h-48">
                                <p className="text-red-800 font-mono text-xs break-all">
                                    {this.state.error.toString()}
                                </p>
                                {this.state.errorInfo && (
                                    <pre className="text-red-700/70 font-mono text-[10px] mt-2 whitespace-pre-wrap">
                                        {this.state.errorInfo.componentStack}
                                    </pre>
                                )}
                            </div>
                        )}

                        <div className="flex flex-col gap-3">
                            <button
                                onClick={this.handleReload}
                                className="w-full py-3 px-4 bg-pickle-green hover:bg-pickle-green/90 text-white font-bold rounded-xl transition-all shadow-sm hover:shadow active:scale-95"
                            >
                                ↻ Reload Application
                            </button>
                        </div>
                    </div>
                </div>
            );
        }

        return this.props.children;
    }
}

export default GlobalErrorBoundary;
