import React, { useState, useMemo } from "react";
import { Plus, Pencil, Trash2, Search } from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import ConfirmationModal from "../../../common/components/ConfirmationModal";
import PartnerFormModal from "./PartnerFormModal";
import toast from "react-hot-toast";

/** Compute age from YYYY-MM-DD string. Returns null if invalid. */
function computeAge(dob) {
  if (!dob) return null;
  const birth = new Date(dob + "T00:00:00");
  if (isNaN(birth)) return null;
  const today = new Date();
  let age = today.getFullYear() - birth.getFullYear();
  const m = today.getMonth() - birth.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
  return age;
}

/** Compact gender label */
function genderChip(g) {
  if (!g) return null;
  const map = { Male: "M", Female: "F", "Non-binary": "NB" };
  return map[g] || g[0];
}

export default function PartnersTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getGroupsForDivision,
    getPartnersForTournament,
    addPartner,
    updatePartner,
    removePartner,
  } = useTournamentState();

  const divisions = getDivisionsForTournament(tournament.id);
  const allPartners = getPartnersForTournament(tournament.id);

  // Build groupsByDivision map for the form
  const groupsByDivision = useMemo(() => {
    const map = {};
    divisions.forEach((d) => {
      map[d.id] = getGroupsForDivision(d.id);
    });
    return map;
  }, [divisions, getGroupsForDivision]);

  // All groups flat for display
  const allGroups = useMemo(
    () => divisions.flatMap((d) => getGroupsForDivision(d.id)),
    [divisions, getGroupsForDivision]
  );

  const [filterDivision, setFilterDivision] = useState("");
  const [filterGroup, setFilterGroup] = useState("");
  const [search, setSearch] = useState("");
  const [addOpen, setAddOpen] = useState(false);
  const [editTarget, setEditTarget] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);

  const filteredGroups = filterDivision
    ? (groupsByDivision[filterDivision] || [])
    : allGroups;

  const filtered = useMemo(() => {
    return allPartners.filter((p) => {
      if (filterDivision && p.division_id !== filterDivision) return false;
      if (filterGroup && p.group_id !== filterGroup) return false;
      if (search) {
        const q = search.toLowerCase();
        if (
          !p.team_name.toLowerCase().includes(q) &&
          !p.player_1_name.toLowerCase().includes(q) &&
          !p.player_2_name.toLowerCase().includes(q)
        ) return false;
      }
      return true;
    });
  }, [allPartners, filterDivision, filterGroup, search]);

  const getDivisionName = (did) => divisions.find((d) => d.id === did)?.name || "—";
  const getGroupName = (gid) => allGroups.find((g) => g.id === gid)?.name || "Unassigned";

  const handleAdd = (data) => {
    addPartner({ ...data, tournament_id: tournament.id });
    setAddOpen(false);
    toast.success("Partner added.");
  };

  const handleEdit = (data) => {
    updatePartner(editTarget.id, data);
    setEditTarget(null);
    toast.success("Partner updated.");
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    removePartner(deleteTarget.id, tournament.phase);
    setDeleteTarget(null);
  };

  return (
    <div className="p-4 md:p-6 space-y-4">
      <SurfaceCard
        title={`Partners (${allPartners.length})`}
        actions={
          <button
            onClick={() => setAddOpen(true)}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm"
          >
            <Plus size={14} /> Add Partner
          </button>
        }
      >
        {/* Filters */}
        <div className="px-4 pt-3 pb-2 flex flex-wrap gap-2">
          <div className="relative">
            <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              className="pl-8 pr-3 py-1.5 border border-slate-200 rounded-lg text-xs focus:outline-none focus:ring-1 focus:ring-pickle-green/30 w-40"
              placeholder="Search…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <select
            className="border border-slate-200 rounded-lg px-2 py-1.5 text-xs focus:outline-none"
            value={filterDivision}
            onChange={(e) => { setFilterDivision(e.target.value); setFilterGroup(""); }}
          >
            <option value="">All Divisions</option>
            {divisions.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
          <select
            className="border border-slate-200 rounded-lg px-2 py-1.5 text-xs focus:outline-none disabled:bg-slate-50"
            value={filterGroup}
            onChange={(e) => setFilterGroup(e.target.value)}
            disabled={!filterDivision}
          >
            <option value="">All Groups</option>
            {filteredGroups.map((g) => <option key={g.id} value={g.id}>{g.name}</option>)}
          </select>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-xs uppercase text-slate-500">
              <tr>
                <th className="text-left px-4 py-2 font-semibold">Team</th>
                <th className="text-left px-3 py-2 font-semibold">Player 1</th>
                <th className="text-left px-3 py-2 font-semibold">Player 2</th>
                <th className="text-left px-3 py-2 font-semibold hidden md:table-cell">Age</th>
                <th className="text-left px-3 py-2 font-semibold hidden md:table-cell">Gender</th>
                <th className="text-left px-3 py-2 font-semibold">Division</th>
                <th className="text-left px-3 py-2 font-semibold">Group</th>
                <th className="text-left px-3 py-2 font-semibold">Seed</th>
                <th className="px-3 py-2" />
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={9} className="text-center py-8 text-slate-400 text-xs">
                    {allPartners.length === 0 ? "No partners yet. Add one to get started." : "No partners match your filters."}
                  </td>
                </tr>
              )}
              {filtered.map((p) => {
                const age1 = computeAge(p.player_1_dob);
                const age2 = computeAge(p.player_2_dob);
                const g1 = genderChip(p.player_1_gender);
                const g2 = genderChip(p.player_2_gender);
                return (
                  <tr key={p.id} className={`hover:bg-slate-50 ${p.withdrawn ? "opacity-50" : ""}`}>
                    <td className="px-4 py-2.5 font-medium text-slate-800 text-xs">
                      {p.team_name}
                      {p.withdrawn && <span className="ml-1 text-red-400 text-[10px]">(withdrawn)</span>}
                    </td>
                    <td className="px-3 py-2.5 text-slate-600 text-xs">{p.player_1_name}</td>
                    <td className="px-3 py-2.5 text-slate-600 text-xs">{p.player_2_name}</td>
                    <td className="px-3 py-2.5 text-slate-500 text-xs hidden md:table-cell">
                      {age1 != null || age2 != null
                        ? `${age1 ?? "—"} / ${age2 ?? "—"}`
                        : "—"}
                    </td>
                    <td className="px-3 py-2.5 text-slate-500 text-xs hidden md:table-cell">
                      {g1 || g2
                        ? <span>{g1 ?? "—"} / {g2 ?? "—"}</span>
                        : "—"}
                    </td>
                    <td className="px-3 py-2.5 text-slate-500 text-xs">{getDivisionName(p.division_id)}</td>
                    <td className="px-3 py-2.5 text-slate-500 text-xs">{getGroupName(p.group_id)}</td>
                    <td className="px-3 py-2.5 text-slate-500 text-xs">{p.seed ?? "—"}</td>
                    <td className="px-3 py-2.5">
                      <div className="flex items-center gap-1 justify-end">
                        <button
                          onClick={() => setEditTarget(p)}
                          className="p-1 rounded text-slate-400 hover:text-pickle-green hover:bg-slate-100"
                          title="Edit"
                        >
                          <Pencil size={12} />
                        </button>
                        <button
                          onClick={() => setDeleteTarget(p)}
                          className="p-1 rounded text-slate-400 hover:text-red-500 hover:bg-red-50"
                          title="Remove"
                        >
                          <Trash2 size={12} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </SurfaceCard>

      {/* Add modal */}
      {addOpen && (
        <PartnerFormModal
          divisions={divisions}
          groupsByDivision={groupsByDivision}
          onSave={handleAdd}
          onClose={() => setAddOpen(false)}
        />
      )}

      {/* Edit modal */}
      {editTarget && (
        <PartnerFormModal
          partner={editTarget}
          divisions={divisions}
          groupsByDivision={groupsByDivision}
          onSave={handleEdit}
          onClose={() => setEditTarget(null)}
        />
      )}

      {/* Delete confirmation */}
      <ConfirmationModal
        isOpen={!!deleteTarget}
        title={`Remove "${deleteTarget?.team_name}"?`}
        message={
          tournament.phase === "setup"
            ? "This partner pair will be permanently removed."
            : "The partner will be marked as withdrawn. Their pending matches will be forfeited."
        }
        confirmLabel={tournament.phase === "setup" ? "Remove" : "Withdraw"}
        isDestructive
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
      />
    </div>
  );
}
