// Utility helpers for dashboard and history analytics
// - buildPerPlayerMatchStats
// - buildPerPlayerWaitBeforeMatch
// - buildDailyReport

const toYMD = (date) => {
  if (!date) return "";
  // If strict YYYY-MM-DD string, return as is
  if (typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date)) return date;

  const d = new Date(date);
  if (!Number.isFinite(d.getTime())) return "";
  // Return Local YMD YYYY-MM-DD
  return d.toLocaleDateString('en-CA');
};

const formatNumber = (value) => (Number.isFinite(value) ? value : 0);

export const buildPerPlayerMatchStats = (matches = []) => {
  const results = [];

  matches.forEach((match) => {
    if (!match) return;
    const { id: matchId, winner, teams } = match;
    const greenIds = Array.isArray(teams?.green) ? teams.green : [];
    const blueIds = Array.isArray(teams?.blue) ? teams.blue : [];

    const greenResult = winner === "green" ? "win" : winner === "blue" ? "loss" : "tie";
    const blueResult = winner === "blue" ? "win" : winner === "green" ? "loss" : "tie";

    greenIds.forEach((playerId) => {
      results.push({
        playerId,
        matchId,
        result: greenResult,
        plusMinus: greenResult === "win" ? 1 : greenResult === "loss" ? -1 : 0,
      });
    });

    blueIds.forEach((playerId) => {
      results.push({
        playerId,
        matchId,
        result: blueResult,
        plusMinus: blueResult === "win" ? 1 : blueResult === "loss" ? -1 : 0,
      });
    });
  });

  return results;
};

export const buildPerPlayerWaitBeforeMatch = (matches = []) => {
  const perPlayerMatches = new Map();

  matches.forEach((match) => {
    if (!match) return;
    const lineupIds = Array.isArray(match.lineup)
      ? match.lineup.map((p) => p.id).filter(Boolean)
      : [];
    lineupIds.forEach((playerId) => {
      if (!perPlayerMatches.has(playerId)) perPlayerMatches.set(playerId, []);
      perPlayerMatches.get(playerId).push(match);
    });
  });

  const result = new Map(); // Map<playerId, Map<matchId, waitBeforeMs>>

  perPlayerMatches.forEach((playerMatches, playerId) => {
    const sorted = [...playerMatches].sort(
      (a, b) => (a.startTime || 0) - (b.startTime || 0)
    );
    let prevEnd = null;
    sorted.forEach((match) => {
      const start = formatNumber(match.startTime) || null;
      const end = formatNumber(match.endTime) || start;
      let waitMs = 0;
      if (prevEnd != null && start != null && start > prevEnd) {
        waitMs = start - prevEnd;
      }
      if (!result.has(playerId)) result.set(playerId, new Map());
      result.get(playerId).set(match.id, waitMs);
      prevEnd = end ?? prevEnd;
    });
  });

  return result;
};

export const aggregatePayments = (items = [], getStatusAndAmount) => {
  const breakdown = {
    cash: { count: 0, amount: 0 },
    gcash: { count: 0, amount: 0 },
    gotyme: { count: 0, amount: 0 }, // Added standard key
    free: { count: 0, amount: 0 },
    notPaid: { count: 0, amount: 0 },
    cancelled: { count: 0, amount: 0 },
  };

  items.forEach((item) => {
    if (!item) return;
    const { status, amount } = getStatusAndAmount(item) || {};
    const value = typeof amount === "number" ? amount : 0;

    const statusStr = String(status || "not_paid").toLowerCase();
    const methodStr = String(item.paymentMethod || "").toLowerCase();

    // Classification Logic
    if (statusStr === "cancelled") {
      breakdown.cancelled.count += 1;
      breakdown.cancelled.amount += value;
      return;
    }

    if (statusStr === "unpaid" || statusStr === "not_paid" || (!statusStr && !methodStr)) {
      breakdown.notPaid.count += 1;
      breakdown.notPaid.amount += value;
      return;
    }

    // Process Paid/Free items
    if (methodStr === "free" || statusStr === "free") {
      breakdown.free.count += 1;
      breakdown.free.amount += value;
    } else if (methodStr.includes("gcash")) {
      breakdown.gcash.count += 1;
      breakdown.gcash.amount += value;
    } else if (methodStr.includes("gotyme")) {
      breakdown.gotyme.count += 1;
      breakdown.gotyme.amount += value;
    } else {
      // Default to Cash if 'paid' but no specific method, or actual 'cash' method
      breakdown.cash.count += 1;
      breakdown.cash.amount += value;
    }
  });

  return breakdown;
};

export const buildDailyReport = (opSessions = [], bookingsV2 = {}, slotsV2 = {}, date = new Date(), globalPlayers = []) => {
  const targetYMD = toYMD(date);

  // Exclude cancelled sessions from income and unpaid counts per business rules
  const sessionsToday = (opSessions || []).filter((s) => {
    const base = s.startedAt || s.endedAt || 0;
    const isSameDay = toYMD(base) === targetYMD;
    const status = String(s.status || "").toLowerCase();
    return isSameDay && status !== "cancelled";
  });

  // Open Play aggregates
  let totalPlayers = 0;
  // Income should only include Cash and GCash payments
  let totalIncome = 0;
  const playerStats = new Map();
  const allMatches = [];

  sessionsToday.forEach((session) => {
    const players = session.players || [];
    const matches = session.matches || [];
    totalPlayers += players.length;

    players.forEach((p) => {
      const status = String(p.paymentStatus || "").toLowerCase();
      const method = String(p.paymentMethod || "").toLowerCase();
      const price = typeof p.price === "number" ? p.price : 0;

      const isPaid = status === 'paid' || status === 'cash' || status === 'gcash';
      if (isPaid) {
        totalIncome += price;
      }
      const existing = playerStats.get(p.id) || {
        id: p.id,
        name: p.name,
        matches: 0,
        longestWaitTimeMs: 0,
      };
      const matchesCount = (p.matches ?? existing.matches ?? 0) || 0;
      const longestWaitTimeMs = Math.max(
        existing.longestWaitTimeMs || 0,
        p.longestWaitTimeMs || 0
      );
      playerStats.set(p.id, {
        ...existing,
        name: p.name,
        matches: matchesCount,
        longestWaitTimeMs,
      });
    });

    matches.forEach((m) => allMatches.push(m));
  });

  const allPlayers = Array.from(playerStats.values());
  const totalMatchesPlayed = allPlayers.reduce(
    (sum, p) => sum + (p.matches || 0),
    0
  );
  const avgGamesPerPlayer = allPlayers.length
    ? totalMatchesPlayed / allPlayers.length
    : 0;

  const waits = allPlayers.map((p) => p.longestWaitTimeMs || 0).filter((ms) => ms > 0);
  const maxWaitMs = waits.length ? Math.max(...waits) : 0;
  const avgWaitMs = waits.length
    ? waits.reduce((sum, v) => sum + v, 0) / waits.length
    : 0;

  let maxGames = 0;
  const topPlayersByGames = allPlayers
    .slice()
    .sort((a, b) => (b.matches || 0) - (a.matches || 0))
    .slice(0, 10)
    .map((p) => {
      const m = p.matches || 0;
      if (m > maxGames) maxGames = m;
      return { playerId: p.id, name: p.name, matches: m };
    });

  const openPlayPayments = aggregatePayments(
    sessionsToday.flatMap((session) => session.players || []),
    (player) => ({
      status: player.paymentStatus,
      amount: typeof player.price === "number" ? player.price : 0,
    })
  );
  // Rentals Analytics (V2)
  const rentalsToday = [];
  const rentalPaymentsList = [];

  // For Rental Income: prefer booking-level amountPaid (discount-aware).
  // Track counted bookings outside loop to avoid double-counting per multi-slot bookings.
  const countedBookingIds = new Set();

  // Iterate all slots for the target date
  Object.values(slotsV2 || {}).forEach(slot => {
    if (!slot) return;
    const sYMD = slot.date || toYMD(slot.startTime);
    if (sYMD !== targetYMD) return;
    if (slot.status === 'CANCELLED') return;

    const parentBooking = bookingsV2[slot.bookingId];
    if (!parentBooking) return; // Orphaned slot?

    if (!countedBookingIds.has(slot.bookingId)) {
      countedBookingIds.add(slot.bookingId);
      const pSum = parentBooking.paymentSummary || {};
      // amountPaid is the actual received money (discounted price user paid)
      const paid = pSum.amountPaid || 0;
      if (paid > 0) {
        rentalPaymentsList.push({
          status: 'paid',
          amount: paid,
          paymentMethod: pSum.paymentMethod || 'CASH'
        });
      } else {
        rentalPaymentsList.push({
          status: 'not_paid',
          amount: pSum.totalAmount || slot.price || 0,
          paymentMethod: null
        });
      }
    }
  });


  // Unique Rentals Count (Based on slots active today)
  const uniqueRentalIds = new Set();
  Object.values(slotsV2 || {}).forEach(slot => {
    const sYMD = slot.date || toYMD(slot.startTime);
    if (slot && sYMD === targetYMD && slot.status !== 'CANCELLED') {
      uniqueRentalIds.add(slot.bookingId);
    }
  });

  const rentalStats = {
    totalRentals: uniqueRentalIds.size,
    totalIncome: rentalPaymentsList.reduce((sum, item) => item.status === 'paid' ? sum + item.amount : sum, 0),
    byCourt: {} // Utilization calc below
  };

  // Utilization (V2)
  // Sum duration of slots today per court
  Object.values(slotsV2 || {}).forEach(slot => {
    const sYMD = slot.date || toYMD(slot.startTime);
    if (!slot || sYMD !== targetYMD || slot.status === 'CANCELLED') return;
    let hours = 0;
    if (typeof slot.startTime === 'number' && typeof slot.endTime === 'number') {
      hours = Math.max(0, (slot.endTime - slot.startTime) / 60);
    } else {
      const start = new Date(slot.startTime);
      const end = new Date(slot.endTime);
      hours = Math.max(0, (end - start) / (1000 * 60 * 60));
    }
    const courtName = `Court ${slot.courtId}`;
    rentalStats.byCourt[courtName] = (rentalStats.byCourt[courtName] || 0) + hours;
  });

  const rentalPayments = aggregatePayments(rentalPaymentsList, (item) => ({
    status: item.status,
    amount: item.amount,
    paymentMethod: item.paymentMethod
  }));

  // Match history analytics (aggregate across today's sessions)
  const matchesWithDuration = allMatches
    .map((m) => {
      const start = Number(m.startTime || 0);
      const end = Number(m.endTime || 0);
      const durationMs = Number(m.durationMs || (end && start ? Math.max(0, end - start) : 0));
      return { ...m, durationMs };
    })
    .filter((m) => Number(m.durationMs) > 0);

  const totalDuration = matchesWithDuration.reduce((sum, m) => sum + (m.durationMs || 0), 0);
  const avgDurationMs = matchesWithDuration.length ? Math.round(totalDuration / matchesWithDuration.length) : null;
  let shortestMatch = matchesWithDuration.length ? matchesWithDuration[0] : null;
  let longestMatch = matchesWithDuration.length ? matchesWithDuration[0] : null;
  matchesWithDuration.forEach((m) => {
    if (shortestMatch && m.durationMs < shortestMatch.durationMs) shortestMatch = m;
    if (longestMatch && m.durationMs > longestMatch.durationMs) longestMatch = m;
  });
  const courtCounts = {};
  matchesWithDuration.forEach((m) => {
    const key = m.courtName || (m.courtId != null ? `Court ${m.courtId}` : "Unknown court");
    courtCounts[key] = (courtCounts[key] || 0) + 1;
  });
  let mostActiveCourt = null;
  Object.entries(courtCounts).forEach(([courtName, count]) => {
    if (!mostActiveCourt || count > mostActiveCourt.count) {
      mostActiveCourt = { courtName, count };
    }
  });
  const playerCounts = {};
  matchesWithDuration.forEach((m) => {
    const ids = [...(m.teams?.green || []), ...(m.teams?.blue || [])];
    ids.forEach((id) => { playerCounts[id] = (playerCounts[id] || 0) + 1; });
  });
  let topPlayer = null;
  Object.entries(playerCounts).forEach(([id, count]) => {
    // We don't have player names here reliably; fill with ID reference
    if (!topPlayer || count > topPlayer.count) {
      const found = globalPlayers.find(p => String(p.id) === String(id));
      const name = found ? found.name : `P${id}`;
      topPlayer = { id, name, count };
    }
  });

  const playerWinStats = new Map();
  allMatches.forEach(m => {
    if (!m.winner) return;
    const greenIds = m.teams?.green || [];
    const blueIds = m.teams?.blue || [];
    const winner = m.winner;
    const process = (ids, result) => {
      ids.forEach(id => {
        const p = playerWinStats.get(id) || { id: id, wins: 0, total: 0, name: `P${id}` };
        p.total += 1;
        if (result === 'win') p.wins += 1;
        playerWinStats.set(id, p);
      });
    };
    process(greenIds, winner === 'green' ? 'win' : 'loss');
    process(blueIds, winner === 'blue' ? 'win' : 'loss');
  });

  const topPlayersByWinRate = Array.from(playerWinStats.values())
    .map(p => {
      const ref = playerStats.get(p.id?.toString()) || playerStats.get(Number(p.id));
      if (ref && ref.name) {
        p.name = ref.name;
      } else {
        const globalRef = globalPlayers.find(gp => String(gp.id) === String(p.id));
        if (globalRef) p.name = globalRef.name;
      }
      p.percent = p.total > 0 ? (p.wins / p.total) * 100 : 0;
      return p;
    })
    .filter(p => p.total >= 2) // Min 2 matches
    .sort((a, b) => {
      if (b.percent !== a.percent) return b.percent - a.percent;
      return b.wins - a.wins;
    })
    .slice(0, 10);

  const topPlayerByWinRate = topPlayersByWinRate.length > 0 ? topPlayersByWinRate[0] : null;

  const arrivalTimes = [];
  sessionsToday.forEach(s => {
    (s.players || []).forEach(p => {
      const time = p.arrivalTime || p.joinedAt;
      if (time) {
        const d = new Date(time);
        if (Number.isFinite(d.getTime())) {
          arrivalTimes.push(d.getHours() * 60 + d.getMinutes());
        }
      }
    });
  });
  const avgArrivalMin = arrivalTimes.length ? Math.round(arrivalTimes.reduce((a, b) => a + b, 0) / arrivalTimes.length) : null;
  const avgArrivalTime = avgArrivalMin !== null ? `${Math.floor(avgArrivalMin / 60).toString().padStart(2, '0')}:${(avgArrivalMin % 60).toString().padStart(2, '0')}` : "N/A";

  return {
    date: targetYMD,
    rentals: rentalStats,
    openPlay: {
      totalPlayers,
      totalIncome,
    },
    games: {
      avgWaitMs,
      maxWaitMs,
      avgGamesPerPlayer,
      maxGamesPerPlayer: maxGames,
      topPlayersByGames,
      topPlayerByWinRate,
      avgArrivalTime,
      summary: { avgDurationMs, shortestMatch, longestMatch, mostActiveCourt, topPlayer },
    },
    payments: {
      openPlay: openPlayPayments,
      rentals: rentalPayments,
    },
  };
};

// Compute daily metrics (income, players) for the last N days ending at `today` (inclusive).
// Returns an array of { date: 'YYYY-MM-DD', openPlayIncome, rentalIncome, total, visitorCount } sorted ascending by date.
export const computeDailyMetricsLastNDays = (
  opSessions = [],
  bookingsV2 = {},
  slotsV2 = {},
  N = 7,
  today = new Date()
) => {
  const days = Math.max(1, Number(N) || 7);
  const base = new Date(today);
  const start = new Date(base.getFullYear(), base.getMonth(), base.getDate() - (days - 1), 0, 0, 0, 0);

  // Use consistent Local YMD generation
  const toYMDLocal = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

  const result = [];
  for (let i = 0; i < days; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i, 0, 0, 0, 0);
    const ymd = toYMDLocal(d);

    // Open Play stats per day
    const sessionsOnDay = (opSessions || []).filter((s) => {
      const y = toYMD(s.startedAt || s.endedAt || 0);
      const status = String(s.status || "").toLowerCase();
      return y === ymd && status !== "cancelled";
    });

    let dailyVisitors = 0;
    const openPlayIncome = sessionsOnDay.reduce((sum, s) => {
      const players = s.players || [];
      dailyVisitors += players.length;
      const inc = players.reduce((pSum, p) => {
        const status = String(p.paymentStatus || "").toLowerCase();
        // New logic: Only count if explicitly 'paid' (or free, which is technically paid 0)
        // Legacy: 'cash'/'gcash' were statuses. New: status='paid', method='cash'
        const isPaid = status === 'paid' || status === 'free' || status === 'cash' || status === 'gcash';
        const price = typeof p.price === "number" ? p.price : 0;
        return isPaid ? pSum + price : pSum;
      }, 0);
      return sum + inc;
    }, 0);

    // Rental stats per day (V2)
    let dailyRentalIncome = 0;
    const uniqueRentalsOnDay = new Set();

    Object.values(slotsV2 || {}).forEach(slot => {
      if (!slot) return;
      const sYMD = slot.date || toYMD(slot.startTime);
      if (sYMD !== ymd) return;
      if (slot.status === 'CANCELLED') return;

      uniqueRentalsOnDay.add(slot.bookingId);
    });

    // Compute rental income per day using booking-level amountPaid (discount-aware)
    // Group by bookingId first to avoid double-counting
    const bookingsOnDay = new Set();
    Object.values(slotsV2 || {}).forEach(slot => {
      if (!slot) return;
      const sYMD = slot.date || toYMD(slot.startTime);
      if (sYMD !== ymd) return;
      if (slot.status === 'CANCELLED') return;
      bookingsOnDay.add(slot.bookingId);
    });

    bookingsOnDay.forEach(bookingId => {
      const booking = bookingsV2[bookingId];
      if (!booking) return;
      const pSum = booking.paymentSummary || {};
      const paid = pSum.amountPaid || 0;
      if (paid > 0) {
        dailyRentalIncome += paid;
      } else {
        // Fallback for legacy bookings without paymentSummary
        const bSlots = Object.values(slotsV2).filter(s =>
          s && s.bookingId === bookingId && (s.date || toYMD(s.startTime)) === ymd && s.status !== 'CANCELLED'
        );
        dailyRentalIncome += bSlots.filter(s => s.isPaid).reduce((sum, s) => sum + (s.price || 0), 0);
      }
    });

    result.push({
      date: ymd,
      openPlayIncome,
      rentalIncome: dailyRentalIncome,
      total: openPlayIncome + dailyRentalIncome,
      visitorCount: dailyVisitors,
      rentalCount: uniqueRentalsOnDay.size
    });
  }

  return result;
};

// Compute daily metrics for an arbitrary date range (start -> end inclusive)
export const computeDailyMetricsInRange = (
  opSessions = [],
  bookingsV2 = {},
  slotsV2 = {},
  startDateStr, // 'YYYY-MM-DD'
  endDateStr    // 'YYYY-MM-DD'
) => {
  const start = new Date(startDateStr);
  const end = new Date(endDateStr);
  const result = [];

  // Safety check
  if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];

  // Iterate days
  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    const ymd = d.toISOString().slice(0, 10);

    // Open Play calculations
    const sessionsOnDay = (opSessions || []).filter((s) => {
      const dateStr = s.startedAt || s.endedAt || "";
      return toYMD(dateStr) === ymd && String(s.status).toLowerCase() !== "cancelled";
    });

    let dailyVisitors = 0;
    const openPlayIncome = sessionsOnDay.reduce((sum, s) => {
      const players = s.players || [];
      dailyVisitors += players.length;
      const inc = players.reduce((pSum, p) => {
        const status = String(p.paymentStatus || "").toLowerCase();
        const price = typeof p.price === "number" ? p.price : 0;
        const isPaid = status === 'paid' || status === 'cash' || status === 'gcash';
        return isPaid ? pSum + price : pSum;
      }, 0);
      return sum + inc;
    }, 0);

    // Rental stats (V2) - use booking-level amountPaid (discount-aware)
    let dailyRentalIncome = 0;
    const uniqueRentalsOnDay = new Set();
    const countedForIncome = new Set();
    Object.values(slotsV2 || {}).forEach(slot => {
      if (!slot) return;
      const sYMD = slot.date || toYMD(slot.startTime);
      if (sYMD !== ymd) return;
      if (slot.status === 'CANCELLED') return;
      uniqueRentalsOnDay.add(slot.bookingId);
      if (!countedForIncome.has(slot.bookingId)) {
        countedForIncome.add(slot.bookingId);
        const booking = bookingsV2[slot.bookingId];
        const pSum = booking?.paymentSummary || {};
        const paid = pSum.amountPaid || 0;
        if (paid > 0) {
          dailyRentalIncome += paid;
        } else if (slot.isPaid) {
          // Legacy fallback: slot-level isPaid
          dailyRentalIncome += (slot.price || 0);
        }
      }
    });

    result.push({
      date: ymd,
      openPlayIncome,
      rentalIncome: dailyRentalIncome,
      total: openPlayIncome + dailyRentalIncome,
      visitorCount: dailyVisitors,
      rentalCount: uniqueRentalsOnDay.size
    });
  }

  return result;
};

// Compute income for the last N days ending at `today` (inclusive).
// Returns an array of { date: 'YYYY-MM-DD', openPlayIncome, rentalIncome, total } sorted ascending by date.


// Build a range-aware report for dashboard tiles.
// range: 'day' | 'week' | 'month'
// today: Date
// Returns shape compatible with dashboard usage:
// {
//   label, date,
//   openPlay: { totalPlayers, totalIncome },
//   rentals: { totalRentals, totalIncome },
//   games: { avgWaitMs, maxWaitMs, avgGamesPerPlayer, maxGamesPerPlayer, topPlayersByGames },
//   payments: { openPlay: buckets, rentals: buckets },
//   incomeSeries?: [{date, openPlayIncome, rentalIncome, total}]
// }
export const buildRangeReport = (
  range = "day",
  today = new Date(),
  opSessions = [],
  bookingsV2 = {},
  slotsV2 = {},
  settings = {},
  globalPlayers = []
) => {
  const label = range === "day" ? "Today" : range === "week" ? "This Week" : "This Month";

  let startDate, endDate;
  const t = new Date(today);

  if (range === "day") {
    const daily = buildDailyReport(opSessions, bookingsV2, slotsV2, today, globalPlayers);
    return { label, ...daily, dailyMetrics: [] };
  } else if (range === "week") {
    // This Week (Sunday to Saturday)
    const day = t.getDay(); // 0 (Sun) - 6 (Sat)
    const diff = t.getDate() - day; // adjust when day is sunday
    startDate = new Date(t.setDate(diff));
    endDate = new Date(t.setDate(startDate.getDate() + 6));
  } else {
    // This Month (1st to Last Day)
    startDate = new Date(t.getFullYear(), t.getMonth(), 1);
    endDate = new Date(t.getFullYear(), t.getMonth() + 1, 0);
  }

  // Ensure robust local YMD strings
  const sStr = startDate.toLocaleDateString('en-CA');
  const eStr = endDate.toLocaleDateString('en-CA');

  // Use Range Compute
  const series = computeDailyMetricsInRange(opSessions, bookingsV2, slotsV2, sStr, eStr);
  const dateRangeSet = new Set(series.map((d) => d.date));

  // No extra dateFilterFn needed as precise range is used
  const dateFilterFn = (ymd) => true;

  // Aggregate Range
  const sessionsInRange = (opSessions || []).filter((s) => {
    const ymd = toYMD(s.startedAt || s.endedAt || 0);
    const status = String(s.status || "").toLowerCase();
    return status !== "cancelled" && dateRangeSet.has(ymd); // Exact match in set
  });
  // Filter Bookings/Slots in range for aggregate (V2)
  // For V2, we care about SLOTS in range for income/usage, and BOOKINGS for count?
  // Daily logic iterates days. Here we need totals across range.

  // Actually, for aggregate totals, it's safer to just sum up the 'series' result we just computed?
  // The series has daily income. Summing it gives range total income.
  // Visitor count sum gives total visitors (unique per day).

  // BUT we also need breakdown by Payment Method, Game Stats etc. which Series doesn't have.
  // So we do need to iterate raw data within range.

  const slotsInRange = [];
  const bookingsIdsInRange = new Set();

  Object.values(slotsV2 || {}).forEach(slot => {
    if (!slot) return;
    const ymd = slot.date || toYMD(slot.startTime);
    if (slot.status !== 'CANCELLED' && dateRangeSet.has(ymd) && dateFilterFn(ymd)) {
      slotsInRange.push(slot);
      bookingsIdsInRange.add(slot.bookingId);
    }
  });

  // Open Play Totals
  let totalPlayers = 0;
  let totalOpIncome = 0;
  const playerStats = new Map();
  sessionsInRange.forEach((session) => {
    const players = session.players || [];
    totalPlayers += players.length;
    players.forEach((p) => {
      const status = String(p.paymentStatus || "").toLowerCase();
      const price = typeof p.price === "number" ? p.price : 0;
      const isPaid = status === 'paid' || status === 'cash' || status === 'gcash';
      if (isPaid) {
        totalOpIncome += price;
      }
      const existing = playerStats.get(p.id) || { id: p.id, name: p.name, matches: 0, longestWaitTimeMs: 0 };
      const matchesCount = (p.matches ?? existing.matches ?? 0) || 0;
      const longestWaitTimeMs = Math.max(existing.longestWaitTimeMs || 0, p.longestWaitTimeMs || 0);
      playerStats.set(p.id, { ...existing, name: p.name, matches: matchesCount, longestWaitTimeMs });
    });
  });

  // Game Stats Calculation ... (Omitting full rewrite, assume identical logic preserved above)
  const allPlayers = Array.from(playerStats.values());
  const totalMatchesPlayed = allPlayers.reduce((sum, p) => sum + (p.matches || 0), 0);
  const avgGamesPerPlayer = allPlayers.length ? totalMatchesPlayed / allPlayers.length : 0;
  const waits = allPlayers.map((p) => p.longestWaitTimeMs || 0).filter((ms) => ms > 0);
  const maxWaitMs = waits.length ? Math.max(...waits) : 0;
  const avgWaitMs = waits.length ? waits.reduce((sum, v) => sum + v, 0) / waits.length : 0;

  let maxGames = 0;
  const topPlayersByGames = allPlayers
    .slice()
    .sort((a, b) => (b.matches || 0) - (a.matches || 0))
    .slice(0, 10)
    .map((p) => {
      const m = p.matches || 0;
      if (m > maxGames) maxGames = m;
      return { playerId: p.id, name: p.name, matches: m };
    });

  // Gameplay Stats
  const allMatchesInRange = [];
  sessionsInRange.forEach(s => {
    if (s.matches) allMatchesInRange.push(...s.matches);
  });

  const playerWinStats = new Map();
  allMatchesInRange.forEach(m => {
    if (!m.winner) return;
    const greenIds = m.teams?.green || [];
    const blueIds = m.teams?.blue || [];
    const winner = m.winner;
    const process = (ids, result) => {
      ids.forEach(id => {
        const p = playerWinStats.get(id) || { id: id, wins: 0, total: 0, name: `P${id}` };
        p.total += 1;
        if (result === 'win') p.wins += 1;
        playerWinStats.set(id, p);
      });
    };
    process(greenIds, winner === 'green' ? 'win' : 'loss');
    process(blueIds, winner === 'blue' ? 'win' : 'loss');
  });

  const topPlayersByWinRate = Array.from(playerWinStats.values())
    .map(p => {
      const ref = playerStats.get(p.id?.toString()) || playerStats.get(Number(p.id));
      if (ref && ref.name) {
        p.name = ref.name;
      } else {
        const globalRef = globalPlayers.find(gp => String(gp.id) === String(p.id));
        if (globalRef) p.name = globalRef.name;
      }
      p.percent = p.total > 0 ? (p.wins / p.total) * 100 : 0;
      return p;
    })
    .filter(p => p.total >= 2) // Min 2 matches
    .sort((a, b) => {
      if (b.percent !== a.percent) return b.percent - a.percent;
      return b.wins - a.wins; // Tie-break with more wins
    })
    .slice(0, 10);

  const topPlayerByWinRate = topPlayersByWinRate.length > 0 ? topPlayersByWinRate[0] : null;

  const arrivalTimes = [];
  sessionsInRange.forEach(s => {
    (s.players || []).forEach(p => {
      const time = p.arrivalTime || p.joinedAt;
      if (time) {
        const d = new Date(time);
        if (Number.isFinite(d.getTime())) {
          arrivalTimes.push(d.getHours() * 60 + d.getMinutes());
        }
      }
    });
  });
  const avgArrivalMin = arrivalTimes.length ? Math.round(arrivalTimes.reduce((a, b) => a + b, 0) / arrivalTimes.length) : null;
  const avgArrivalTime = avgArrivalMin !== null ? `${Math.floor(avgArrivalMin / 60).toString().padStart(2, '0')}:${(avgArrivalMin % 60).toString().padStart(2, '0')}` : "N/A";

  // Rentals Logic (V2 Aggregate in Range)
  const rentalHoursByCourt = {};
  slotsInRange.forEach(slot => {
    let hours = 0;
    if (typeof slot.startTime === 'number' && typeof slot.endTime === 'number') {
      hours = Math.max(0, (slot.endTime - slot.startTime) / 60);
    } else {
      const start = new Date(slot.startTime);
      const end = new Date(slot.endTime);
      hours = Math.max(0, (end - start) / (1000 * 60 * 60));
    }
    const name = `Court ${slot.courtId}`;
    rentalHoursByCourt[name] = (rentalHoursByCourt[name] || 0) + hours;
  });

  // Rental income per range: use booking-level amountPaid (discount-aware)
  // Group by unique booking to avoid slot double-counting
  const uniqueBookingIdsForIncome = new Set(slotsInRange.map(s => s.bookingId));
  const rentalIncomeTotal = Array.from(uniqueBookingIdsForIncome).reduce((sum, bookingId) => {
    const booking = bookingsV2[bookingId];
    const pSum = booking?.paymentSummary || {};
    const paid = pSum.amountPaid || 0;
    if (paid > 0) return sum + paid;
    // Fallback: sum isPaid slots for legacy
    const bSlots = slotsInRange.filter(s => s.bookingId === bookingId);
    return sum + bSlots.filter(s => s.isPaid).reduce((s2, sl) => s2 + (sl.price || 0), 0);
  }, 0);

  const rentalPaymentsList = slotsInRange.map(slot => {
    const pb = bookingsV2[slot.bookingId];
    return {
      status: slot.isPaid ? 'paid' : 'not_paid',
      amount: slot.price || 0,
      paymentMethod: slot.isPaid ? (pb?.paymentSummary?.paymentMethod || 'CASH') : null
    };
  });

  // Reconstruct an "Items" list for the Modal (List of bookings involved)
  // We can pass the full booking objects for the modal list
  const rentalsItems = Array.from(bookingsIdsInRange).map(id => bookingsV2[id]).filter(Boolean);

  const rentalsTotals = {
    totalRentals: bookingsIdsInRange.size,
    totalIncome: rentalIncomeTotal,
    items: rentalsItems, // For legacy compatibility in modal, might need adapter
  };

  const payments = {
    openPlay: aggregatePayments(sessionsInRange.flatMap((s) => s.players || []), (p) => ({ status: p.paymentStatus, amount: typeof p.price === 'number' ? p.price : 0, paymentMethod: p.paymentMethod })),
    rentals: aggregatePayments(rentalPaymentsList, (item) => ({ status: item.status, amount: item.amount, paymentMethod: item.paymentMethod })),
  };

  return {
    label,
    date: toYMD(today),
    openPlay: { totalPlayers, totalIncome: totalOpIncome },
    rentals: { ...rentalsTotals, byCourt: rentalHoursByCourt },
    games: { avgWaitMs, maxWaitMs, avgGamesPerPlayer, maxGamesPerPlayer: maxGames, topPlayersByGames, topPlayersByWinRate, topPlayerByWinRate, avgArrivalTime },
    payments,
    dailyMetrics: series,
  };
};

// Compute utilization (booked vs. free hours) for the last N days
// Returns array of { date, bookedHours, freeHours, totalHours }
export const computeUtilizationForLastNDays = (
  bookingsV2 = {},
  slotsV2 = {},
  calendarCourtsCount = 0,
  settings = {},
  N = 7,
  today = new Date()
) => {
  const days = Math.max(1, Number(N) || 7);
  const base = new Date(today);
  const start = new Date(base.getFullYear(), base.getMonth(), base.getDate() - (days - 1), 0, 0, 0, 0);
  const openHour = Number(settings?.calendarOpenHour ?? 7);
  const closeHour = Number(settings?.calendarCloseHour ?? 22);
  const hoursPerDay = Math.max(0, closeHour - openHour);
  const totalHoursPerDay = Math.max(0, hoursPerDay * Math.max(1, Number(calendarCourtsCount) || 0));

  const toYMDLocal = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate(), 0, 0, 0, 0).toISOString().slice(0, 10);

  const result = [];
  for (let i = 0; i < days; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i, 0, 0, 0, 0);
    const ymd = toYMDLocal(d);

    // Sum hours of slots on this day
    let bookedHours = 0;
    Object.values(slotsV2 || {}).forEach(slot => {
      if (!slot || slot.status === 'CANCELLED') return;
      const sYMD = toYMD(slot.startTime);
      if (sYMD !== ymd) return;

      const startTime = new Date(slot.startTime);
      const endTime = new Date(slot.endTime);
      const duration = (endTime - startTime) / (1000 * 60 * 60); // hours
      bookedHours += duration;
    });

    const freeHours = Math.max(0, totalHoursPerDay - bookedHours);
    result.push({ date: ymd, bookedHours, freeHours, totalHours: totalHoursPerDay });
  }
  return result;
};
