import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAppState } from "../../app/providers";
import { selectQueueState } from "../../state/selectors";

export default function LandingPage() {
    const navigate = useNavigate();
    const { setUserRole, settings } = useAppState(selectQueueState);

    const [isAdminPromptOpen, setIsAdminPromptOpen] = useState(false);
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");

    const handleStaffLogin = () => {
        console.log("LOGIN: Staff clicked");
        try {
            setUserRole("staff");
            console.log("LOGIN: Role set");
            navigate("/calendar-v2");
            console.log("LOGIN: Navigated");
        } catch (e) {
            console.error("LOGIN ERROR:", e);
        }
    };

    const handleAdminLogin = () => {
        if (password === (settings?.masterPassword || "Pickle001!")) {
            setUserRole("admin");
            navigate("/dashboard");
        } else {
            setError("Incorrect password");
        }
    };

    return (
        <div className="min-h-screen w-full bg-pickle-cream flex items-center justify-center p-4 font-body text-pickle-green">
            <div className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl border border-pickle-green/10 overflow-hidden flex flex-col md:flex-row">

                {/* Left Side: Branding */}
                <div className="bg-pickle-green text-pickle-cream p-10 flex flex-col justify-center items-center md:w-5/12 text-center">
                    <div className="w-24 h-24 bg-pickle-cream rounded-full flex items-center justify-center mb-6 shadow-lg">
                        <span className="text-4xl">🥒</span>
                    </div>
                    <h1 className="text-4xl font-display mb-2">Pickle Studio</h1>
                    <p className="opacity-80 text-sm">Court Management System</p>
                </div>

                {/* Right Side: Selection */}
                <div className="p-10 md:w-7/12 flex flex-col justify-center">

                    {!isAdminPromptOpen ? (
                        <>
                            <h2 className="text-2xl font-bold mb-8 text-center uppercase tracking-wide">Select User Role</h2>
                            <div className="space-y-4">
                                <button
                                    onClick={handleStaffLogin}
                                    className="w-full group relative p-6 border-2 border-pickle-green/10 rounded-2xl hover:border-pickle-green hover:bg-pickle-green/5 transition-all text-left"
                                >
                                    <div className="flex items-center gap-4">
                                        <span className="text-3xl p-3 bg-pickle-green/10 rounded-full group-hover:bg-pickle-green group-hover:text-pickle-cream transition-colors">👋</span>
                                        <div>
                                            <h3 className="text-lg font-bold text-pickle-green">Staff</h3>
                                            <p className="text-xs text-slate-500">Operations, Queue, Calendar</p>
                                        </div>
                                    </div>
                                </button>

                                <button
                                    onClick={() => setIsAdminPromptOpen(true)}
                                    className="w-full group relative p-6 border-2 border-pickle-green/10 rounded-2xl hover:border-pickle-green hover:bg-pickle-green/5 transition-all text-left"
                                >
                                    <div className="flex items-center gap-4">
                                        <span className="text-3xl p-3 bg-purple-100 text-purple-700 rounded-full group-hover:bg-purple-600 group-hover:text-white transition-colors">🔒</span>
                                        <div>
                                            <h3 className="text-lg font-bold text-pickle-green">Admin / Owner</h3>
                                            <p className="text-xs text-slate-500">Full Access to All Modules</p>
                                        </div>
                                    </div>
                                </button>
                            </div>
                        </>
                    ) : (
                        <div className="animate-in slide-in-from-right fade-in duration-300">
                            <button
                                onClick={() => {
                                    setIsAdminPromptOpen(false);
                                    setError("");
                                    setPassword("");
                                }}
                                className="text-xs font-bold text-slate-400 hover:text-pickle-green mb-6 flex items-center gap-1"
                            >
                                ← BACK
                            </button>
                            <h2 className="text-xl font-bold mb-2">Admin Access</h2>
                            <p className="text-xs text-slate-500 mb-6">Enter the master password to continue.</p>

                            <form onSubmit={(e) => { e.preventDefault(); handleAdminLogin(); }}>
                                <input
                                    type="password"
                                    autoFocus
                                    className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl focus:border-pickle-green focus:ring-pickle-green outline-none transition-all mb-4 font-mono text-lg"
                                    placeholder="Password"
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                />
                                {error && <p className="text-red-500 text-xs font-bold mb-4">{error}</p>}

                                <button
                                    type="submit"
                                    className="w-full bg-pickle-green text-pickle-cream py-4 rounded-xl font-bold hover:bg-pickle-green/90 transition-transform active:scale-95 shadow-lg"
                                >
                                    Unlock Dashboard
                                </button>
                            </form>
                        </div>
                    )}

                </div>
            </div>

            <div className="absolute bottom-4 text-center w-full text-pickle-green/20 text-[10px] font-mono pointer-events-none">
                POWERED BY DINK MANAGER
            </div>
        </div>
    );
}
