import React, { useState, useMemo } from "react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import { calculateGroupStandings } from "../utils/standings";

function GroupStandingsTable({ group, division, allPartners, allMatches }) {
  const rows = useMemo(
    () => calculateGroupStandings(group.id, allPartners, allMatches),
    [group.id, allPartners, allMatches]
  );

  const advanceCount = division?.advance_count ?? 2;

  if (rows.length === 0) {
    return (
      <div className="px-4 py-6 text-center text-xs text-slate-400">
        No partners in this group yet.
      </div>
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs">
        <thead className="bg-slate-50 text-xs uppercase text-slate-500">
          <tr>
            <th className="text-center px-3 py-2 font-semibold w-10">#</th>
            <th className="text-left px-3 py-2 font-semibold">Team</th>
            <th className="text-left px-3 py-2 font-semibold hidden sm:table-cell">P1</th>
            <th className="text-left px-3 py-2 font-semibold hidden sm:table-cell">P2</th>
            <th className="text-center px-3 py-2 font-semibold">W</th>
            <th className="text-center px-3 py-2 font-semibold">L</th>
            <th className="text-center px-3 py-2 font-semibold">Pts</th>
            <th className="text-center px-3 py-2 font-semibold hidden md:table-cell">PD</th>
            <th className="text-center px-3 py-2 font-semibold hidden md:table-cell">PS</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {rows.map((row, idx) => {
            const isAdvancing = idx < advanceCount;
            return (
              <tr
                key={row.partner.id}
                className={`hover:bg-slate-50 ${isAdvancing ? "border-l-2 border-pickle-green" : ""}`}
              >
                <td className={`text-center px-3 py-2.5 font-bold text-xs ${isAdvancing ? "text-pickle-green" : "text-slate-400"}`}>
                  {idx + 1}
                </td>
                <td className="px-3 py-2.5 font-medium text-slate-800">
                  {row.partner.team_name}
                  {isAdvancing && (
                    <span className="ml-1.5 text-[9px] font-semibold text-pickle-green uppercase tracking-wide">ADV</span>
                  )}
                </td>
                <td className="px-3 py-2.5 text-slate-500 hidden sm:table-cell">{row.partner.player_1_name}</td>
                <td className="px-3 py-2.5 text-slate-500 hidden sm:table-cell">{row.partner.player_2_name}</td>
                <td className="text-center px-3 py-2.5 font-semibold text-green-600">{row.wins}</td>
                <td className="text-center px-3 py-2.5 text-red-400">{row.losses}</td>
                <td className="text-center px-3 py-2.5 font-bold text-slate-700">{row.points}</td>
                <td className={`text-center px-3 py-2.5 hidden md:table-cell ${row.pointDiff > 0 ? "text-green-600" : row.pointDiff < 0 ? "text-red-400" : "text-slate-400"}`}>
                  {row.pointDiff > 0 ? `+${row.pointDiff}` : row.pointDiff}
                </td>
                <td className="text-center px-3 py-2.5 text-slate-500 hidden md:table-cell">{row.pointsScored}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function PlayoffStandingsSection({ tournament, allMatches, allPartners }) {
  const playoffMatches = allMatches.filter(
    (m) => m.tournament_id === tournament.id && m.phase === "playoff" && m.status === "completed"
  );

  if (playoffMatches.length === 0) {
    return (
      <div className="px-4 py-8 text-center text-sm text-slate-400">
        No completed playoff matches yet.
      </div>
    );
  }

  // Find the champion: winner of the last completed match (highest round)
  const maxRound = Math.max(...playoffMatches.map((m) => m.round || 0));
  const finalMatches = playoffMatches.filter((m) => m.round === maxRound);
  const champion = finalMatches.length > 0 && finalMatches[0].winner_id
    ? allPartners.find((p) => p.id === finalMatches[0].winner_id)
    : null;

  return (
    <div className="px-4 py-4 space-y-4">
      {champion && (
        <div className="flex items-center gap-3 p-4 bg-amber-50 border border-amber-200 rounded-xl">
          <span className="text-2xl">🏆</span>
          <div>
            <div className="text-xs font-semibold text-amber-600 uppercase tracking-wide">Champion</div>
            <div className="font-bold text-slate-900 text-base">{champion.team_name}</div>
            <div className="text-xs text-slate-500">{champion.player_1_name} &amp; {champion.player_2_name}</div>
          </div>
        </div>
      )}
      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead className="bg-slate-50 text-xs uppercase text-slate-500">
            <tr>
              <th className="text-left px-3 py-2 font-semibold">Round</th>
              <th className="text-left px-3 py-2 font-semibold">Match</th>
              <th className="text-left px-3 py-2 font-semibold">Winner</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {[...playoffMatches]
              .sort((a, b) => (a.round || 0) - (b.round || 0))
              .map((m) => {
                const pA = allPartners.find((p) => p.id === m.partner_a_id);
                const pB = allPartners.find((p) => p.id === m.partner_b_id);
                const winner = m.winner_id ? allPartners.find((p) => p.id === m.winner_id) : null;
                return (
                  <tr key={m.id} className="hover:bg-slate-50">
                    <td className="px-3 py-2.5 text-slate-500">Round {m.round}</td>
                    <td className="px-3 py-2.5 text-slate-700">
                      {pA?.team_name || "TBD"} <span className="text-slate-400">vs</span> {pB?.team_name || "TBD"}
                    </td>
                    <td className="px-3 py-2.5 font-medium text-pickle-green">
                      {winner?.team_name || "—"}
                    </td>
                  </tr>
                );
              })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default function StandingsTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getGroupsForDivision,
    getPartnersForTournament,
    getMatchesForTournament,
  } = useTournamentState();

  const divisions = getDivisionsForTournament(tournament.id);
  const allPartners = getPartnersForTournament(tournament.id);
  const allMatches = getMatchesForTournament(tournament.id);

  const [selectedDivisionId, setSelectedDivisionId] = useState(() => divisions[0]?.id || "");

  const selectedDivision = divisions.find((d) => d.id === selectedDivisionId) || divisions[0];
  const groups = selectedDivision ? getGroupsForDivision(selectedDivision.id) : [];

  const isPlayoffs = tournament.phase === "playoffs" || tournament.phase === "completed";

  if (tournament.phase === "setup") {
    return (
      <div className="p-6 text-center text-slate-400 text-sm">
        Start the tournament to see standings.
      </div>
    );
  }

  if (divisions.length === 0) {
    return (
      <div className="p-6 text-center text-slate-400 text-sm">
        No divisions found for this tournament.
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-4">
      {/* Division tabs */}
      <div className="flex overflow-x-auto border-b border-slate-200 -mb-1">
        {divisions.map((d) => (
          <button
            key={d.id}
            onClick={() => setSelectedDivisionId(d.id)}
            className={`px-4 py-2.5 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
              selectedDivisionId === d.id
                ? "border-pickle-green text-pickle-green"
                : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
            }`}
          >
            {d.name}
          </button>
        ))}
      </div>

      {/* Group Stage Standings */}
      {!isPlayoffs && selectedDivision && (
        <div className="space-y-4">
          {groups.length === 0 ? (
            <div className="text-center text-sm text-slate-400 py-8">No groups in this division.</div>
          ) : (
            groups.map((group) => (
              <SurfaceCard key={group.id} title={group.name}>
                <GroupStandingsTable
                  group={group}
                  division={selectedDivision}
                  allPartners={allPartners}
                  allMatches={allMatches}
                />
              </SurfaceCard>
            ))
          )}
          <div className="flex items-center gap-2 text-xs text-slate-400 px-1">
            <span className="inline-block w-2 h-4 bg-pickle-green rounded-sm" />
            <span>Top {selectedDivision.advance_count ?? 2} per group advance to playoffs</span>
          </div>
        </div>
      )}

      {/* Playoffs / Completed: show both group standings (read-only) and playoff results */}
      {isPlayoffs && (
        <div className="space-y-6">
          <SurfaceCard title="Playoff Results">
            <PlayoffStandingsSection
              tournament={tournament}
              allMatches={allMatches}
              allPartners={allPartners}
            />
          </SurfaceCard>

          {selectedDivision && groups.length > 0 && (
            <div className="space-y-3">
              <h3 className="text-sm font-semibold text-slate-600 px-1">Group Stage Final Standings</h3>
              {groups.map((group) => (
                <SurfaceCard key={group.id} title={group.name}>
                  <GroupStandingsTable
                    group={group}
                    division={selectedDivision}
                    allPartners={allPartners}
                    allMatches={allMatches}
                  />
                </SurfaceCard>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
