import React from "react";
import useTournamentManager from "../hooks/useTournamentManager";

const TournamentStateContext = React.createContext(null);
TournamentStateContext.displayName = "TournamentStateContext";

export function TournamentStateProvider({ children }) {
  const state = useTournamentManager();
  return (
    <TournamentStateContext.Provider value={state}>
      {children}
    </TournamentStateContext.Provider>
  );
}

export function useTournamentState(selector) {
  const context = React.useContext(TournamentStateContext);
  if (!context) {
    throw new Error("useTournamentState must be used within a TournamentStateProvider");
  }
  return React.useMemo(() => {
    if (typeof selector === "function") {
      return selector(context);
    }
    return context;
  }, [context, selector]);
}
