import React, { useState, useMemo } from "react";
import { Play, ClipboardList, Pencil, Plus, Minus, Flag, History } from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import ScoreEntryModal from "./ScoreEntryModal";
import toast from "react-hot-toast";

const STATUS_STYLES = {
  scheduled: "bg-slate-100 text-slate-500",
  in_progress: "bg-blue-100 text-blue-700",
  completed: "bg-green-100 text-green-700",
  cancelled: "bg-red-100 text-red-600",
  bye: "bg-amber-100 text-amber-700",
};

const STATUS_LABELS = {
  scheduled: "Scheduled",
  in_progress: "Live",
  completed: "Done",
  cancelled: "Cancelled",
  bye: "Bye",
};

function StatusBadge({ status }) {
  return (
    <span className={`shrink-0 inline-flex items-center px-2 py-0.5 rounded-full text-xs font-semibold ${STATUS_STYLES[status] || STATUS_STYLES.scheduled}`}>
      {STATUS_LABELS[status] || status}
    </span>
  );
}

function fmt12(time24) {
  if (!time24) return null;
  const [h, m] = time24.split(":").map(Number);
  const ampm = h >= 12 ? "PM" : "AM";
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${ampm}`;
}

function fmtDate(dateStr) {
  if (!dateStr) return null;
  const [, mo, d] = dateStr.split("-").map(Number);
  const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  return `${months[mo - 1]} ${d}`;
}

/** ScoreCounter — +/- buttons beside a team name for live score tracking */
function ScoreCounter({ label, score, onChange }) {
  return (
    <div className="flex items-center gap-2 py-2">
      <span className="flex-1 font-semibold text-slate-800 text-base truncate">{label}</span>
      <div className="flex items-center gap-1 shrink-0">
        <button
          onClick={() => onChange(Math.max(0, score - 1))}
          className="w-8 h-8 flex items-center justify-center rounded-lg border border-slate-200 text-slate-500 hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition-colors"
        >
          <Minus size={14} />
        </button>
        <span className="w-10 text-center font-bold text-xl text-slate-900 tabular-nums">{score}</span>
        <button
          onClick={() => onChange(score + 1)}
          className="w-8 h-8 flex items-center justify-center rounded-lg border border-slate-200 text-slate-500 hover:bg-green-50 hover:text-green-600 hover:border-green-200 transition-colors"
        >
          <Plus size={14} />
        </button>
      </div>
    </div>
  );
}

export default function CourtsTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getGroupsForDivision,
    getMatchesForTournament,
    partners,
    updateMatchStatus,
    updateMatchSchedule,
    updateMatchLiveScore,
    recordMatchResult,
  } = useTournamentState();

  const allMatches = getMatchesForTournament(tournament.id);
  const courts = useMemo(
    () => (tournament.courts?.length ? tournament.courts : ["Court 1"]),
    [tournament.courts]
  );

  const divisions = useMemo(
    () => getDivisionsForTournament(tournament.id),
    [getDivisionsForTournament, tournament.id]
  );

  const [selectedDivisionId, setSelectedDivisionId] = useState(() => divisions[0]?.id || "");

  const divisionMap = useMemo(
    () => Object.fromEntries(divisions.map((d) => [d.id, d])),
    [divisions]
  );
  const groupMap = useMemo(() => {
    const map = {};
    divisions.forEach((d) => {
      getGroupsForDivision(d.id).forEach((g) => { map[g.id] = g; });
    });
    return map;
  }, [divisions, getGroupsForDivision]);

  const [scoreMatch, setScoreMatch] = useState(null);
  const [prefillScores, setPrefillScores] = useState(null);
  const [rescheduleMatch, setRescheduleMatch] = useState(null);
  const [rescheduleForm, setRescheduleForm] = useState({ date: "", time: "", court: "" });
  // assignForms: { [matchId]: { court: string, date: string } }
  const [assignForms, setAssignForms] = useState({});
  // Track which court history sections are expanded
  const [expandedHistory, setExpandedHistory] = useState({});

  const getPartner = (pid) => (pid ? partners[pid] : null);

  /** Active matches per court (non-completed, non-bye, has court assigned, filtered by division) */
  const activeMatchesByCourt = useMemo(() => {
    const result = {};
    courts.forEach((c) => { result[c] = []; });

    const divFilter = selectedDivisionId;
    allMatches
      .filter(
        (m) =>
          m.court &&
          m.status !== "bye" &&
          m.status !== "completed" &&
          m.status !== "cancelled" &&
          (!divFilter || m.division_id === divFilter)
      )
      .forEach((m) => {
        const c = m.court;
        if (!result[c]) result[c] = [];
        result[c].push(m);
      });

    // Sort by date then time (nulls last)
    Object.values(result).forEach((arr) => {
      arr.sort((a, b) => {
        const dateA = a.scheduled_date || "9999-99-99";
        const dateB = b.scheduled_date || "9999-99-99";
        if (dateA !== dateB) return dateA.localeCompare(dateB);
        return (a.scheduled_time || "").localeCompare(b.scheduled_time || "");
      });
    });

    return result;
  }, [allMatches, courts, selectedDivisionId]);

  /** Completed matches per court (for history section) */
  const completedMatchesByCourt = useMemo(() => {
    const result = {};
    courts.forEach((c) => { result[c] = []; });

    const divFilter = selectedDivisionId;
    allMatches
      .filter(
        (m) =>
          m.court &&
          m.status === "completed" &&
          (!divFilter || m.division_id === divFilter)
      )
      .forEach((m) => {
        const c = m.court;
        if (!result[c]) result[c] = [];
        result[c].push(m);
      });

    Object.values(result).forEach((arr) => {
      arr.sort((a, b) => {
        const dateA = a.scheduled_date || "9999-99-99";
        const dateB = b.scheduled_date || "9999-99-99";
        if (dateA !== dateB) return dateA.localeCompare(dateB);
        return (a.scheduled_time || "").localeCompare(b.scheduled_time || "");
      });
    });

    return result;
  }, [allMatches, courts, selectedDivisionId]);

  /** All unscheduled matches (badge count) */
  const allUnscheduledMatches = useMemo(
    () =>
      allMatches.filter(
        (m) => !m.court && m.status !== "bye" && m.status !== "completed" && m.status !== "cancelled"
      ),
    [allMatches]
  );

  /** Unscheduled matches filtered by selected division */
  const unscheduledMatches = useMemo(
    () =>
      allUnscheduledMatches.filter(
        (m) => !selectedDivisionId || m.division_id === selectedDivisionId
      ),
    [allUnscheduledMatches, selectedDivisionId]
  );

  /**
   * Courts that have at least 1 non-completed, non-cancelled, non-bye match assigned.
   * Only 1 match can be assigned per court at a time — must complete before assigning another.
   */
  const busyCourts = useMemo(() => {
    const set = new Set();
    allMatches.forEach((m) => {
      if (m.court && !["completed", "cancelled", "bye"].includes(m.status)) {
        set.add(m.court);
      }
    });
    return set;
  }, [allMatches]);

  const handleMarkInProgress = (match) => {
    if (busyCourts.has(match.court)) {
      toast.error(`${match.court} already has a match in progress.`);
      return;
    }
    updateMatchStatus(match.id, "in_progress");
    toast.success("Match started.");
  };

  const handleEndGame = (match) => {
    const liveScore = match.live_score || { partner_a: 0, partner_b: 0 };
    setPrefillScores([{ game: 1, partner_a: liveScore.partner_a, partner_b: liveScore.partner_b }]);
    setScoreMatch(match);
  };

  const handleSaveResult = (scores) => {
    if (!scoreMatch) return;
    recordMatchResult(scoreMatch.id, scores, tournament.id);
    updateMatchLiveScore(scoreMatch.id, { partner_a: 0, partner_b: 0 });
    setScoreMatch(null);
    setPrefillScores(null);
    toast.success("Result recorded.");
  };

  const handleCloseScoreModal = () => {
    setScoreMatch(null);
    setPrefillScores(null);
  };

  const handleOpenReschedule = (match) => {
    setRescheduleMatch(match);
    setRescheduleForm({
      date: match.scheduled_date || "",
      time: match.scheduled_time || "",
      court: match.court || "",
    });
  };

  const handleSaveReschedule = (e) => {
    e.preventDefault();
    updateMatchSchedule(rescheduleMatch.id, {
      date: rescheduleForm.date,
      time: rescheduleForm.time,
      court: rescheduleForm.court,
    });
    setRescheduleMatch(null);
    toast.success("Match updated.");
  };

  const setAssignField = (matchId, key, value) => {
    setAssignForms((prev) => ({
      ...prev,
      [matchId]: { ...(prev[matchId] || {}), [key]: value },
    }));
  };

  const handleAssign = (matchId) => {
    const form = assignForms[matchId] || {};
    if (!form.court) { toast.error("Select a court first."); return; }

    // Enforce: only 1 active match per court
    if (busyCourts.has(form.court)) {
      toast.error(`${form.court} already has an active match. Complete it before assigning another.`);
      return;
    }

    // Auto-fill today's date (or tournament start date if that's in the future)
    const today = new Date().toISOString().split("T")[0];
    const autoDate = tournament.start_date && tournament.start_date > today
      ? tournament.start_date
      : today;

    updateMatchSchedule(matchId, { date: autoDate, time: undefined, court: form.court });
    setAssignForms((prev) => { const next = { ...prev }; delete next[matchId]; return next; });
    toast.success(`Match assigned to ${form.court}.`);
  };

  const handleLiveScoreChange = (match, side, newVal) => {
    const current = match.live_score || { partner_a: 0, partner_b: 0 };
    updateMatchLiveScore(match.id, {
      ...current,
      [side === "a" ? "partner_a" : "partner_b"]: newVal,
    });
  };

  const toggleHistory = (court) => {
    setExpandedHistory((prev) => ({ ...prev, [court]: !prev[court] }));
  };

  if (tournament.phase === "setup") {
    return (
      <div className="p-6 text-center text-slate-400 text-sm">
        Start the tournament to use the court view.
      </div>
    );
  }

  // Grid layout
  const colCount = courts.length <= 2 ? courts.length : courts.length <= 4 ? 2 : courts.length <= 6 ? 3 : 4;
  const cardMinWidthClass = colCount <= 2 ? "min-w-[280px]" : colCount === 3 ? "min-w-[240px]" : "min-w-[200px]";
  const cardWidthStyle = { width: `calc(${100 / colCount}% - 1.5rem)` };

  const inputCls = "w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30";

  return (
    <div className="p-4 md:p-6 space-y-5">
      {/* ── Division tabs ── */}
      {divisions.length > 1 && (
        <div className="flex overflow-x-auto border-b border-slate-200 -mb-1">
          <button
            onClick={() => setSelectedDivisionId("")}
            className={`px-4 py-2.5 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
              selectedDivisionId === ""
                ? "border-pickle-green text-pickle-green"
                : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
            }`}
          >
            All
          </button>
          {divisions.map((d) => (
            <button
              key={d.id}
              onClick={() => setSelectedDivisionId(d.id)}
              className={`px-4 py-2.5 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
                selectedDivisionId === d.id
                  ? "border-pickle-green text-pickle-green"
                  : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
              }`}
            >
              {d.name}
            </button>
          ))}
        </div>
      )}

      {/* ── Court columns ── */}
      <div className="flex flex-wrap justify-center gap-6">
        {courts.map((court) => {
          const courtMatches = activeMatchesByCourt[court] || [];
          const doneMatches = completedMatchesByCourt[court] || [];
          const isHistoryOpen = expandedHistory[court];
          const courtBusy = busyCourts.has(court);

          return (
            <div
              key={court}
              style={cardWidthStyle}
              className={`${cardMinWidthClass} bg-white rounded-2xl border shadow-sm overflow-hidden flex flex-col ${courtBusy ? "border-blue-200" : "border-slate-100"}`}
            >
              {/* Court header */}
              <div className={`px-4 py-3 border-b flex items-center justify-between ${courtBusy ? "bg-blue-50 border-blue-100" : "bg-slate-50 border-slate-100"}`}>
                <h3 className="font-bold text-slate-800 text-base">{court}</h3>
                {courtBusy && (
                  <span className="text-xs font-semibold text-blue-600 bg-blue-100 rounded-full px-2 py-0.5">● Live</span>
                )}
              </div>

              {/* Active matches */}
              {courtMatches.length === 0 ? (
                <div className="px-4 py-6 text-center text-sm text-slate-400 italic flex-1">
                  No matches scheduled
                </div>
              ) : (
                <ul className="divide-y divide-slate-100 flex-1">
                  {courtMatches.map((m) => {
                    const pA = getPartner(m.partner_a_id);
                    const pB = getPartner(m.partner_b_id);
                    const isLive = m.status === "in_progress";
                    const liveScore = m.live_score || { partner_a: 0, partner_b: 0 };
                    const canStart = m.status === "scheduled" && !busyCourts.has(court);

                    return (
                      <li
                        key={m.id}
                        className={`px-4 py-3 flex flex-col gap-2 ${isLive ? "bg-blue-50/60 border-l-4 border-l-blue-400" : ""}`}
                      >
                        {/* Date + time + status row */}
                        <div className="flex items-center justify-between gap-2">
                          <div className="flex items-center gap-1.5">
                            {m.scheduled_date && (
                              <span className="text-xs font-medium text-slate-400 bg-slate-100 rounded px-1.5 py-0.5">
                                {fmtDate(m.scheduled_date)}
                              </span>
                            )}
                            {m.scheduled_time && (
                              <span className="font-bold text-pickle-green text-sm tabular-nums">
                                {fmt12(m.scheduled_time)}
                              </span>
                            )}
                          </div>
                          <div className="flex items-center gap-1">
                            <StatusBadge status={m.status} />
                            {canStart && (
                              <button
                                onClick={() => handleMarkInProgress(m)}
                                className="p-1 rounded text-slate-400 hover:text-blue-600 hover:bg-blue-50 transition-colors"
                                title="Start match"
                              >
                                <Play size={13} />
                              </button>
                            )}
                            {m.status === "scheduled" && busyCourts.has(court) && (
                              <span className="text-[10px] text-amber-500 font-semibold">Court busy</span>
                            )}
                            <button
                              onClick={() => { setPrefillScores(null); setScoreMatch(m); }}
                              className="p-1 rounded text-slate-400 hover:text-pickle-green hover:bg-pickle-green/10 transition-colors"
                              title="Record Scores"
                            >
                              <ClipboardList size={13} />
                            </button>
                            <button
                              onClick={() => handleOpenReschedule(m)}
                              className="p-1 rounded text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors"
                              title="Edit schedule"
                            >
                              <Pencil size={13} />
                            </button>
                          </div>
                        </div>

                        {/* Team names + live score counters */}
                        {isLive ? (
                          <div className="flex flex-col gap-2">
                            <div className="border border-blue-100 rounded-xl bg-white px-3 divide-y divide-slate-100">
                              <ScoreCounter
                                label={pA?.team_name || "TBD"}
                                score={liveScore.partner_a}
                                onChange={(v) => handleLiveScoreChange(m, "a", v)}
                              />
                              <ScoreCounter
                                label={pB?.team_name || "TBD"}
                                score={liveScore.partner_b}
                                onChange={(v) => handleLiveScoreChange(m, "b", v)}
                              />
                            </div>
                            <button
                              onClick={() => handleEndGame(m)}
                              className="w-full flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg text-xs font-bold bg-red-500 text-white hover:bg-red-600 transition-colors shadow-sm"
                            >
                              <Flag size={12} />
                              End Game ({liveScore.partner_a} – {liveScore.partner_b})
                            </button>
                          </div>
                        ) : (
                          <div className="flex flex-col gap-0.5">
                            <span className="font-semibold text-slate-800 text-sm truncate">{pA?.team_name || "TBD"}</span>
                            <span className="text-xs text-slate-400 font-medium px-2">vs</span>
                            <span className="font-semibold text-slate-800 text-sm truncate">{pB?.team_name || "TBD"}</span>
                          </div>
                        )}

                        {/* Division / Group badge */}
                        {(divisionMap[m.division_id] || (m.group_id && groupMap[m.group_id])) && (
                          <div className="flex items-center gap-1 flex-wrap">
                            {divisionMap[m.division_id] && (
                              <span className="text-[10px] font-semibold bg-slate-100 text-slate-500 rounded px-1.5 py-0.5 leading-none">
                                {divisionMap[m.division_id].name}
                              </span>
                            )}
                            {m.group_id && groupMap[m.group_id] && (
                              <span className="text-[10px] font-medium bg-pickle-green/10 text-pickle-green rounded px-1.5 py-0.5 leading-none">
                                {groupMap[m.group_id].name}
                              </span>
                            )}
                          </div>
                        )}
                      </li>
                    );
                  })}
                </ul>
              )}

              {/* Match History (completed) */}
              {doneMatches.length > 0 && (
                <div className="border-t border-slate-100">
                  <button
                    onClick={() => toggleHistory(court)}
                    className="w-full flex items-center justify-between px-4 py-2 text-xs font-semibold text-slate-500 hover:bg-slate-50 transition-colors"
                  >
                    <span className="flex items-center gap-1.5">
                      <History size={12} />
                      History ({doneMatches.length})
                    </span>
                    <span className="text-slate-300">{isHistoryOpen ? "▲" : "▼"}</span>
                  </button>
                  {isHistoryOpen && (
                    <ul className="divide-y divide-slate-100 bg-slate-50/50">
                      {doneMatches.map((m) => {
                        const pA = getPartner(m.partner_a_id);
                        const pB = getPartner(m.partner_b_id);
                        return (
                          <li key={m.id} className="px-4 py-2.5 flex flex-col gap-1 opacity-75">
                            <div className="flex items-center justify-between gap-2">
                              <div className="flex items-center gap-1.5">
                                {m.scheduled_date && (
                                  <span className="text-[10px] text-slate-400">{fmtDate(m.scheduled_date)}</span>
                                )}
                                {m.scheduled_time && (
                                  <span className="text-[10px] font-medium text-slate-500">{fmt12(m.scheduled_time)}</span>
                                )}
                              </div>
                              <div className="flex items-center gap-1">
                                <StatusBadge status={m.status} />
                                <button
                                  onClick={() => { setPrefillScores(null); setScoreMatch(m); }}
                                  className="p-1 rounded text-slate-300 hover:text-pickle-green hover:bg-pickle-green/10 transition-colors"
                                  title="View / Edit Scores"
                                >
                                  <ClipboardList size={12} />
                                </button>
                              </div>
                            </div>
                            <div className="text-xs text-slate-600">
                              <span className="font-medium">{pA?.team_name || "TBD"}</span>
                              <span className="text-slate-400 mx-1">vs</span>
                              <span className="font-medium">{pB?.team_name || "TBD"}</span>
                            </div>
                            {m.scores?.length > 0 && (
                              <div className="text-xs text-green-700 font-semibold">
                                {m.scores.map((g, i) => (
                                  <span key={i}>{i > 0 ? " · " : ""}{g.partner_a}–{g.partner_b}</span>
                                ))}
                              </div>
                            )}
                          </li>
                        );
                      })}
                    </ul>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* ── Unscheduled matches ── */}
      {allUnscheduledMatches.length > 0 && (
        <SurfaceCard title={`Unscheduled Matches (${allUnscheduledMatches.length})`}>
          {/* Division filter tabs (only if more than one division) */}
          {divisions.length > 1 && (
            <div className="flex overflow-x-auto border-b border-slate-100">
              <button
                onClick={() => setSelectedDivisionId("")}
                className={`px-3 py-2 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
                  selectedDivisionId === ""
                    ? "border-pickle-green text-pickle-green"
                    : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
                }`}
              >
                All
              </button>
              {divisions.map((d) => {
                const count = allUnscheduledMatches.filter((m) => m.division_id === d.id).length;
                if (count === 0) return null;
                return (
                  <button
                    key={d.id}
                    onClick={() => setSelectedDivisionId(d.id)}
                    className={`px-3 py-2 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
                      selectedDivisionId === d.id
                        ? "border-pickle-green text-pickle-green"
                        : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
                    }`}
                  >
                    {d.name} ({count})
                  </button>
                );
              })}
            </div>
          )}

          {unscheduledMatches.length === 0 ? (
            <div className="px-4 py-6 text-center text-sm text-slate-400">
              No unscheduled matches for this division.
            </div>
          ) : (
            <ul className="divide-y divide-slate-100">
              {unscheduledMatches.map((m) => {
                const pA = getPartner(m.partner_a_id);
                const pB = getPartner(m.partner_b_id);
                const af = assignForms[m.id] || {};
                return (
                  <li key={m.id} className="px-4 py-2.5 flex flex-wrap items-center gap-2">
                    <div className="flex-1 min-w-[120px]">
                      <span className="text-sm font-semibold text-slate-700">
                        {pA?.team_name || "TBD"}
                        <span className="text-slate-400 font-normal mx-1">vs</span>
                        {pB?.team_name || "TBD"}
                      </span>
                      {(divisionMap[m.division_id] || (m.group_id && groupMap[m.group_id])) && (
                        <div className="flex items-center gap-1 mt-0.5">
                          {divisionMap[m.division_id] && (
                            <span className="text-[10px] font-semibold bg-slate-100 text-slate-500 rounded px-1.5 py-0.5 leading-none">
                              {divisionMap[m.division_id].name}
                            </span>
                          )}
                          {m.group_id && groupMap[m.group_id] && (
                            <span className="text-[10px] font-medium bg-pickle-green/10 text-pickle-green rounded px-1.5 py-0.5 leading-none">
                              {groupMap[m.group_id].name}
                            </span>
                          )}
                        </div>
                      )}
                    </div>

                    {/* Court select — date auto-filled on assign */}
                    <select
                      className={`border rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-pickle-green/30 ${
                        af.court && busyCourts.has(af.court)
                          ? "border-red-300 bg-red-50 text-red-600"
                          : "border-slate-200"
                      }`}
                      value={af.court || ""}
                      onChange={(e) => setAssignField(m.id, "court", e.target.value)}
                    >
                      <option value="">Court…</option>
                      {courts.map((c) => (
                        <option key={c} value={c} disabled={busyCourts.has(c)}>
                          {c}{busyCourts.has(c) ? " (busy)" : ""}
                        </option>
                      ))}
                    </select>

                    <button
                      onClick={() => handleAssign(m.id)}
                      disabled={!af.court || busyCourts.has(af.court)}
                      className="px-3 py-1 rounded-lg text-xs font-semibold bg-pickle-green text-white hover:bg-pickle-green/90 transition-colors shadow-sm disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                      Assign
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </SurfaceCard>
      )}

      {/* ── Score entry modal ── */}
      {scoreMatch && (
        <ScoreEntryModal
          match={scoreMatch}
          partnerA={getPartner(scoreMatch.partner_a_id)}
          partnerB={getPartner(scoreMatch.partner_b_id)}
          tournament={tournament}
          onSave={handleSaveResult}
          onClose={handleCloseScoreModal}
          prefillScores={prefillScores}
        />
      )}

      {/* ── Reschedule / Edit match modal ── */}
      {rescheduleMatch && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-black/50 backdrop-blur-sm"
            onClick={() => setRescheduleMatch(null)}
          />
          <form
            onSubmit={handleSaveReschedule}
            className="relative bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col"
          >
            <div className="p-6 border-b border-slate-100">
              <h2 className="text-lg font-bold text-slate-900">Edit Match Schedule</h2>
              <p className="text-xs text-slate-400 mt-1">
                {getPartner(rescheduleMatch.partner_a_id)?.team_name || "TBD"} vs{" "}
                {getPartner(rescheduleMatch.partner_b_id)?.team_name || "TBD"}
              </p>
            </div>
            <div className="p-6 flex flex-col gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Date</label>
                <input
                  type="date"
                  className={inputCls}
                  value={rescheduleForm.date}
                  onChange={(e) => setRescheduleForm((f) => ({ ...f, date: e.target.value }))}
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Time</label>
                <input
                  type="time"
                  className={inputCls}
                  value={rescheduleForm.time}
                  onChange={(e) => setRescheduleForm((f) => ({ ...f, time: e.target.value }))}
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Court</label>
                <select
                  className={inputCls}
                  value={rescheduleForm.court}
                  onChange={(e) => setRescheduleForm((f) => ({ ...f, court: e.target.value }))}
                >
                  <option value="">Select court…</option>
                  {courts.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
            </div>
            <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
              <button
                type="button"
                onClick={() => setRescheduleMatch(null)}
                className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm"
              >
                Save
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}
