import React, { useEffect, useMemo, useState } from "react";
import { MonitorOff, MonitorPlay, Trophy } from "lucide-react";
import toast from "react-hot-toast";
import { SurfaceCard } from "../../common/components";
import { useAppState } from "../../app/providers";
import { selectQueueState } from "../../state/selectors";
import PlayerLeaderboardTable from "./components/PlayerLeaderboardTable";
import {
  buildPlayerLeaderboard,
  clearLeaderboardDisplay,
  LEADERBOARD_DISPLAY_EVENT,
  LEADERBOARD_DISPLAY_STORAGE_KEY,
  LEADERBOARD_DISPLAY_MODE,
  LEADERBOARD_DISPLAY_MS,
  readLeaderboardDisplay,
  requestLeaderboardDisplay,
  sliceLeaderboardTop,
} from "./utils/playerLeaderboard";
import { getMonthKey, getSessionMonthKeys, sessionBelongsToMonth } from "../history/utils/sessionMonth";

function formatSessionWhen(ts) {
  if (!ts) return "—";
  return new Date(ts).toLocaleString([], { dateStyle: "medium", timeStyle: "short" });
}

export default function LeaderboardPage() {
  const { players, matches, opSessions = [] } = useAppState(selectQueueState);
  const liveRows = useMemo(() => buildPlayerLeaderboard(players, matches), [players, matches]);
  const [pageTab, setPageTab] = useState("live");
  const [monthFilter, setMonthFilter] = useState(() => getMonthKey(new Date()));
  const [selectedSessionId, setSelectedSessionId] = useState(null);
  const [displayUntil, setDisplayUntil] = useState(() => {
    const { until } = readLeaderboardDisplay();
    return until > Date.now() ? until : 0;
  });
  const [now, setNow] = useState(() => Date.now());
  const remainingSec = displayUntil > now ? Math.ceil((displayUntil - now) / 1000) : 0;
  const isDisplaying = remainingSec > 0;

  const closedSessions = useMemo(() => {
    const unique = new Map();
    (Array.isArray(opSessions) ? opSessions : []).forEach((session) => {
      if (!session?.id) return;
      const status = String(session.status || "").toLowerCase();
      if (status === "cancelled" || status === "active") return;
      if (!session.endedAt && status !== "completed") return;
      const existing = unique.get(session.id);
      if (!existing || (session.matches?.length || 0) > (existing.matches?.length || 0)) {
        unique.set(session.id, session);
      }
    });
    return Array.from(unique.values()).sort(
      (a, b) => (b.endedAt || b.startedAt || 0) - (a.endedAt || a.startedAt || 0)
    );
  }, [opSessions]);

  const monthOptions = useMemo(() => {
    const keys = new Set();
    closedSessions.forEach((s) => {
      getSessionMonthKeys(s).forEach((key) => keys.add(key));
    });
    keys.add(getMonthKey(new Date()));
    return Array.from(keys).filter(Boolean).sort().reverse();
  }, [closedSessions]);

  const monthSessions = useMemo(
    () => closedSessions.filter((s) => sessionBelongsToMonth(s, monthFilter)),
    [closedSessions, monthFilter]
  );

  const selectedSession = useMemo(
    () => monthSessions.find((s) => s.id === selectedSessionId) || closedSessions.find((s) => s.id === selectedSessionId) || null,
    [monthSessions, closedSessions, selectedSessionId]
  );

  const historyRows = useMemo(
    () => (selectedSession ? buildPlayerLeaderboard(selectedSession.players || [], selectedSession.matches || []) : []),
    [selectedSession]
  );

  useEffect(() => {
    if (!displayUntil) return undefined;
    const remaining = displayUntil - Date.now();
    if (remaining <= 0) {
      setDisplayUntil(0);
      return undefined;
    }
    const timer = setTimeout(() => setDisplayUntil(0), remaining);
    const tick = setInterval(() => setNow(Date.now()), 250);
    return () => {
      clearTimeout(timer);
      clearInterval(tick);
    };
  }, [displayUntil]);

  useEffect(() => {
    const syncDisplay = () => {
      const { until } = readLeaderboardDisplay();
      setDisplayUntil(until > Date.now() ? until : 0);
      setNow(Date.now());
    };
    const onStorage = (event) => {
      if (event.key === LEADERBOARD_DISPLAY_STORAGE_KEY) syncDisplay();
    };
    window.addEventListener("storage", onStorage);
    window.addEventListener("focus", syncDisplay);
    let channel;
    if ("BroadcastChannel" in window) {
      channel = new BroadcastChannel("dink_manager");
      channel.onmessage = (event) => {
        if (event.data?.type !== LEADERBOARD_DISPLAY_EVENT) return;
        const until = Number(event.data.until);
        setDisplayUntil(Number.isFinite(until) && until > Date.now() ? until : 0);
        setNow(Date.now());
      };
    }
    return () => {
      window.removeEventListener("storage", onStorage);
      window.removeEventListener("focus", syncDisplay);
      channel?.close();
    };
  }, []);

  const handleDisplay = (mode = LEADERBOARD_DISPLAY_MODE.FULL) => {
    const until = requestLeaderboardDisplay(LEADERBOARD_DISPLAY_MS, mode);
    setDisplayUntil(until);
    setNow(Date.now());
    const label = mode === LEADERBOARD_DISPLAY_MODE.TOP5 ? "Top 5" : "leaderboard";
    toast.success(`Showing ${label} on the display for ${Math.round(LEADERBOARD_DISPLAY_MS / 60000)} minutes`);
  };

  const handleCloseDisplay = () => {
    clearLeaderboardDisplay();
    setDisplayUntil(0);
    toast.success("Display closed");
  };

  const countdownLabel = `${Math.floor(remainingSec / 60)}:${String(remainingSec % 60).padStart(2, "0")}`;

  return (
    <div className="p-4 w-full h-full flex flex-col overflow-hidden bg-gray-50 relative">
      <div className="mb-4 flex flex-wrap items-start justify-between gap-3 shrink-0">
        <div>
          <h1 className="text-2xl font-display text-pickle-green mb-1">Leaderboards</h1>
          <p className="text-xs text-slate-600 mt-0.5">
            Ranked by wins, then point differential. Reopen any closed session from Past sessions.
          </p>
        </div>
        {pageTab === "live" && (
          <div className="flex flex-wrap items-center gap-2 shrink-0">
            {isDisplaying && (
              <button
                type="button"
                onClick={handleCloseDisplay}
                className="inline-flex items-center gap-2 px-4 py-2 rounded-full text-xs font-semibold text-pickle-green bg-white border border-slate-200 hover:bg-slate-50 shadow-sm"
              >
                <MonitorOff className="w-4 h-4" />
                Close display
                <span className="tabular-nums text-pickle-green">{countdownLabel}</span>
              </button>
            )}
            <button
              type="button"
              onClick={() => handleDisplay(LEADERBOARD_DISPLAY_MODE.TOP5)}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-full text-xs font-semibold text-white shadow-sm"
              style={{ background: "linear-gradient(135deg, #9C824A 0%, #704506 100%)" }}
            >
              <Trophy className="w-4 h-4" />
              Display Top 5
            </button>
            <button
              type="button"
              onClick={() => handleDisplay(LEADERBOARD_DISPLAY_MODE.FULL)}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-full text-xs font-semibold text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm"
            >
              <MonitorPlay className="w-4 h-4" />
              Display on screen
            </button>
          </div>
        )}
      </div>

      <div className="mb-3 inline-flex items-center rounded-full border border-slate-200 bg-white p-1 text-xs shrink-0 w-fit">
        <button
          type="button"
          onClick={() => setPageTab("live")}
          className={`px-4 py-1.5 rounded-full font-semibold ${
            pageTab === "live" ? "bg-pickle-green text-white" : "text-slate-600 hover:bg-slate-50"
          }`}
        >
          Live
        </button>
        <button
          type="button"
          onClick={() => setPageTab("history")}
          className={`px-4 py-1.5 rounded-full font-semibold ${
            pageTab === "history" ? "bg-pickle-green text-white" : "text-slate-600 hover:bg-slate-50"
          }`}
        >
          Past sessions
        </button>
      </div>

      {pageTab === "live" ? (
        <SurfaceCard
          className="flex-1 min-h-0 overflow-hidden flex flex-col"
          title="All players"
          description="Matches, win rate, wins, losses, PD, and level."
          bodyClassName="flex-1 min-h-0 overflow-hidden mt-3"
        >
          <PlayerLeaderboardTable
            rows={liveRows}
            emptyLabel="No players yet. Add players from Queue (OP)."
          />
        </SurfaceCard>
      ) : (
        <div className="flex-1 min-h-0 grid grid-cols-1 lg:grid-cols-[minmax(280px,340px)_1fr] gap-4">
          <SurfaceCard
            className="min-h-0 overflow-hidden flex flex-col"
            title="Closed sessions"
            description="Pick a night to reopen that leaderboard."
            bodyClassName="flex-1 min-h-0 overflow-hidden mt-3"
            actions={
              <select
                value={monthFilter}
                onChange={(e) => {
                  setMonthFilter(e.target.value);
                  setSelectedSessionId(null);
                }}
                className="border rounded px-2 py-1 text-xs bg-white"
              >
                {monthOptions.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            }
          >
            <div className="h-full overflow-auto custom-scrollbar space-y-2 pr-1">
              {monthSessions.length === 0 ? (
                <p className="text-sm text-slate-500 py-8 text-center">
                  Close an Open Play session to save a leaderboard you can reopen.
                </p>
              ) : (
                monthSessions.map((session) => {
                  const rows = buildPlayerLeaderboard(session.players || [], session.matches || []);
                  const top = sliceLeaderboardTop(rows, 1)[0];
                  const active = selectedSessionId === session.id;
                  return (
                    <button
                      key={session.id}
                      type="button"
                      onClick={() => setSelectedSessionId(session.id)}
                      className={`w-full text-left rounded-xl border px-3 py-3 transition-colors ${
                        active
                          ? "border-[#9C824A] bg-[#9C824A]/5"
                          : "border-slate-200 bg-white hover:border-slate-300 hover:bg-slate-50"
                      }`}
                    >
                      <div className="text-sm font-semibold text-slate-900">
                        {session.name || "Open Play"}
                      </div>
                      <div className="text-[11px] text-slate-500 mt-0.5">
                        {formatSessionWhen(session.endedAt || session.startedAt)}
                      </div>
                      <div className="mt-2 flex items-center justify-between text-[11px] text-slate-600">
                        <span>
                          {(session.players || []).length} players · {(session.matches || []).length} matches
                        </span>
                        <span className="font-semibold text-pickle-green truncate max-w-[45%]">
                          {top ? `#1 ${top.name}` : "No ranked players"}
                        </span>
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </SurfaceCard>
          <SurfaceCard
            className="min-h-0 overflow-hidden flex flex-col"
            title={selectedSession ? selectedSession.name || "Session leaderboard" : "Session leaderboard"}
            description={
              selectedSession
                ? `${formatSessionWhen(selectedSession.startedAt)} – ${formatSessionWhen(selectedSession.endedAt)}`
                : "Select a closed session to revisit rankings."
            }
            bodyClassName="flex-1 min-h-0 overflow-hidden mt-3"
          >
            {selectedSession ? (
              <PlayerLeaderboardTable
                rows={historyRows}
                emptyLabel="This session has no ranked players."
              />
            ) : (
              <p className="text-sm text-slate-500 py-10 text-center">
                Choose a session on the left. Rankings are saved when you close Open Play.
              </p>
            )}
          </SurfaceCard>
        </div>
      )}
    </div>
  );
}
