import React, { useEffect, useState } from "react";
import config from "../../../config";
import LevelAvatar from "../../queue/components/LevelAvatar";

const PODIUM_ORDER = [1, 0, 2]; // visual: 2nd, 1st, 3rd
const RANK_GLOW = [
  "0 0 22px 8px rgba(255, 215, 0, 0.45), 0 0 48px 14px rgba(156, 130, 74, 0.32)",
  "0 0 18px 6px rgba(192, 197, 206, 0.35), 0 0 34px 10px rgba(248, 223, 186, 0.2)",
  "0 0 18px 6px rgba(156, 130, 74, 0.4), 0 0 34px 10px rgba(112, 69, 6, 0.25)",
];
const RANK_GLOW_PEAK = [
  "0 0 32px 12px rgba(255, 215, 0, 0.55), 0 0 64px 18px rgba(156, 130, 74, 0.32)",
  "0 0 28px 10px rgba(192, 197, 206, 0.5), 0 0 48px 14px rgba(248, 223, 186, 0.28)",
  "0 0 28px 10px rgba(156, 130, 74, 0.55), 0 0 48px 14px rgba(112, 69, 6, 0.3)",
];
const RANK_RING = ["#FFD700", "#C0C5CE", "#9C824A"];

function formatPd(value) {
  const n = Number(value) || 0;
  return n > 0 ? `+${n}` : String(n);
}

function useOverlayAutoClose(until, onClose) {
  useEffect(() => {
    let closed = false;
    const tick = () => {
      if (Date.now() >= until && !closed) {
        closed = true;
        onClose?.();
      }
    };
    tick();
    const id = setInterval(tick, 250);
    return () => clearInterval(id);
  }, [until, onClose]);
}

function OverlayClock() {
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <div className="text-right leading-none">
      <div className="text-4xl md:text-5xl font-oswald font-bold text-white tabular-nums drop-shadow-md">
        {now.toLocaleTimeString("en-PH", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: true })}
      </div>
      <div className="text-base text-white/80 uppercase tracking-widest mt-2 font-medium">
        {now.toLocaleDateString("en-PH", { weekday: "short", month: "short", day: "numeric" })}
      </div>
    </div>
  );
}

function StatBlock({ label, value, color, large, scale }) {
  return (
    <div className="min-w-0 text-center px-2">
      <p className={`uppercase tracking-[0.18em] text-white/40 ${large ? "text-xs" : "text-[10px]"}`}>{label}</p>
      <p
        className={`font-oswald font-black tabular-nums mt-1 ${large ? "text-3xl md:text-4xl" : "text-2xl md:text-3xl"}`}
        style={{ color, fontSize: Math.round((large ? 36 : 30) * scale) }}
      >
        {value}
      </p>
    </div>
  );
}

function RankStats({ row, large, scale }) {
  return (
    <div className="flex items-end justify-center" style={{ gap: Math.round(24 * scale) }}>
      <StatBlock label="Win rate" value={`${row.winRate}%`} color="#FFD700" large={large} scale={scale} />
      <StatBlock label="Record" value={`${row.wins}–${row.losses}`} color="rgba(255,255,255,0.88)" large={large} scale={scale} />
      <StatBlock label="PD" value={formatPd(row.points)} color="#9C824A" large={large} scale={scale} />
    </div>
  );
}

function PlayerCard({ row, rank, featured, scale }) {
  const isPodium = rank <= 3;
  const size = Math.round((featured ? 220 : isPodium ? 168 : 108) * scale);
  const ring = isPodium ? RANK_RING[rank - 1] : "#F8DFBA";

  if (!isPodium) {
    return (
      <div
        className="h-full min-h-0 flex items-center gap-8 rounded-3xl border px-8 py-5"
        style={{
          background: "rgba(255,255,255,0.03)",
          borderColor: "rgba(255,255,255,0.08)",
          padding: `${Math.round(20 * scale)}px ${Math.round(32 * scale)}px`,
          gap: Math.round(32 * scale),
        }}
      >
        <span className="shrink-0 text-center font-oswald font-black leading-none text-[#F8DFBA]" style={{ width: Math.round(96 * scale), fontSize: Math.round(60 * scale) }}>
          #{rank}
        </span>
        <LevelAvatar
          src={row.imageUrl}
          alt={row.name}
          fallback={row.name}
          frameColor={ring}
          size={size}
          ring={5}
          background="#fff"
        />
        <div className="flex-1 min-w-0">
          <p className="font-oswald font-black uppercase tracking-wide text-white truncate" style={{ fontSize: Math.round(36 * scale) }}>
            {row.name}
          </p>
          <p className="text-sm uppercase tracking-[0.18em] text-white/45 mt-2">{row.level || "—"}</p>
        </div>
        <div className="shrink-0">
          <RankStats row={row} scale={scale} />
        </div>
      </div>
    );
  }

  return (
    <div
      className="h-full min-h-0 flex flex-col rounded-3xl border px-8 py-7"
      style={{
        background: featured
          ? "linear-gradient(180deg, rgba(156,130,74,0.18) 0%, rgba(58,77,57,0.95) 45%)"
          : "rgba(255,255,255,0.04)",
        borderColor: `${ring}66`,
        padding: `${Math.round(28 * scale)}px ${Math.round(32 * scale)}px`,
        animation: "picklePodiumGlow 2.6s ease-in-out infinite",
        boxShadow: RANK_GLOW[rank - 1],
        "--pickle-glow": RANK_GLOW[rank - 1],
        "--pickle-glow-peak": RANK_GLOW_PEAK[rank - 1],
      }}
    >
      <span className="font-oswald font-black text-[#F8DFBA]/85 leading-none" style={{ fontSize: Math.round((featured ? 48 : 36) * scale) }}>
        #{rank}
      </span>
      <div className="flex-1 min-h-0 flex flex-col items-center justify-center text-center" style={{ gap: Math.round(20 * scale) }}>
        <LevelAvatar
          src={row.imageUrl}
          alt={row.name}
          fallback={row.name}
          frameColor={ring}
          size={size}
          ring={featured ? 6 : 5}
          background="#fff"
        />
        <div className="min-w-0 w-full">
          <p
            className="font-oswald font-black uppercase tracking-wide text-white truncate"
            style={{ fontSize: Math.round((featured ? 48 : 36) * scale) }}
          >
            {row.name}
          </p>
          <p className="text-sm uppercase tracking-[0.2em] text-white/45 mt-2">{row.level || "—"}</p>
        </div>
        <RankStats row={row} large={featured} scale={scale} />
      </div>
    </div>
  );
}

export default function PlayerLeaderboardTop5Overlay({ rows = [], until, onClose }) {
  const [scale, setScale] = useState(() => Math.min(1, Math.max(0.4, window.innerHeight / 1080)));
  useEffect(() => {
    const onResize = () => setScale(Math.min(1, Math.max(0.4, window.innerHeight / 1080)));
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);
  const top5 = rows.slice(0, 5);
  const podium = top5.slice(0, 3);
  const rest = top5.slice(3);
  useOverlayAutoClose(until, onClose);

  return (
    <div className="fixed inset-0 z-[80] bg-[#3E430F] flex flex-col p-6 md:p-8">
      <style>{`
        @keyframes picklePodiumGlow {
          0%, 100% { box-shadow: var(--pickle-glow); }
          50% { box-shadow: var(--pickle-glow-peak); }
        }
      `}</style>
      <header className="flex items-center justify-between mb-5 px-2 shrink-0">
        <div className="flex items-center gap-5">
          <img
            src={config.assetPath("logo.jpg")}
            alt={config.displayName}
            className="h-16 md:h-24 w-auto object-contain"
          />
          <div className="flex flex-col leading-none">
            <h2 className="text-2xl md:text-4xl text-white font-bold tracking-wide">Top 5 Players</h2>
            <p className="text-[10px] text-[#F8DFBA] uppercase tracking-[0.3em] mt-1 font-medium">
              {config.tagline || "Premium Court Experience"}
            </p>
          </div>
        </div>
        <OverlayClock />
      </header>
      <div className="h-px bg-gradient-to-r from-transparent via-[#9C824A]/40 to-transparent mb-5 mx-2 shrink-0" />

      {top5.length === 0 ? (
        <div className="flex-1 flex items-center justify-center text-white/40 uppercase tracking-[0.2em] text-sm">
          No completed matches yet.
        </div>
      ) : (
        <div className="flex-1 min-h-0 flex flex-col gap-6 w-full">
          <div className="flex-[3] min-h-0 grid grid-cols-3 gap-6">
            {PODIUM_ORDER.map((idx) => {
              const row = podium[idx];
              if (!row) return <div key={`empty-${idx}`} />;
              const rank = idx + 1;
              return (
                <div key={`podium-${row.id}`} className="min-h-0">
                  <PlayerCard row={row} rank={rank} featured={rank === 1} scale={scale} />
                </div>
              );
            })}
          </div>
          {rest.length > 0 && (
            <div className="flex-[1.15] min-h-0 grid grid-cols-1 md:grid-cols-2 gap-6">
              {rest.map((row, i) => (
                <PlayerCard key={row.id} row={row} rank={i + 4} scale={scale} />
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
