import React from "react";
import ReactDOM from "react-dom/client";
import { createHashRouter, RouterProvider } from "react-router-dom";
import App from "./App";
import "./index.css";
import { AppStateProvider } from "./app/providers";
import { seedIfEmpty } from "./state/seed";
import { bootstrapStorage } from "./state/storage";

function renderApp() {
  // Seed demo data only if there is no existing state.
  seedIfEmpty();

  const router = createHashRouter([
    {
      path: "/*",
      element: <App />,
    },
  ]);

  ReactDOM.createRoot(document.getElementById("root")).render(
    <React.StrictMode>
      <AppStateProvider>
        <RouterProvider
          router={router}
          future={{
            v7_startTransition: true,
            v7_relativeSplatPath: true,
            v7_normalizeFormMethod: true,
            v7_fetcherPersist: true,
          }}
        />
      </AppStateProvider>
    </React.StrictMode>
  );
}

// Hydrate persistence (IndexedDB, migrating from localStorage once) into the
// in-memory cache BEFORE rendering, so the app's synchronous loadState() works
// exactly as before. Always renders, even if bootstrap fails.
bootstrapStorage()
  .catch((err) => console.error("Storage bootstrap error", err))
  .finally(renderApp);


