import React, { useState, useMemo } from "react";
import { Plus, Pencil, Trash2, Shuffle, Users, Zap, AlertTriangle, X } from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import ConfirmationModal from "../../../common/components/ConfirmationModal";
import DivisionFormModal from "./DivisionFormModal";
import toast from "react-hot-toast";
import { suggestGroupCount, snakeSeedPartners } from "../utils/grouping";

const FORMAT_LABELS = {
  round_robin: "Round Robin",
  single_elimination: "SE Bracket",
};
const FORMAT_CHIP_COLORS = {
  round_robin: "bg-blue-50 text-blue-600 border-blue-100",
  single_elimination: "bg-amber-50 text-amber-700 border-amber-100",
};

// ── Group card component ─────────────────────────────────────────────────────
function GroupCards({
  group,
  partners,
  matchCount,
  onDeleteGroup,
  onUnassignPartner,
  onShuffleMatches,
  isEditing,
  editName,
  onStartEdit,
  onEditChange,
  onSaveEdit,
  onCancelEdit,
}) {
  return (
    <div className="border border-slate-200 rounded-xl overflow-hidden bg-white shadow-sm">
      <div className="flex items-center justify-between px-4 py-3 bg-slate-50 border-b border-slate-200">
        <div className="flex items-center gap-2 flex-1 min-w-0">
          {isEditing ? (
            <form onSubmit={(e) => { e.preventDefault(); onSaveEdit(); }} className="flex items-center gap-1.5">
              <input
                autoFocus
                className="border border-pickle-green/50 rounded-lg px-2 py-0.5 text-sm font-bold focus:outline-none focus:ring-2 focus:ring-pickle-green/30 w-36"
                value={editName}
                onChange={(e) => onEditChange(e.target.value)}
              />
              <button type="submit" className="text-xs font-bold text-pickle-green hover:text-pickle-green/80 px-1">✓</button>
              <button type="button" onClick={onCancelEdit} className="text-xs text-slate-400 hover:text-slate-600 px-1">✕</button>
            </form>
          ) : (
            <div className="flex items-center gap-1.5 flex-wrap">
              <span className="text-sm font-bold text-slate-800">{group.name}</span>
              <button onClick={onStartEdit} className="p-0.5 rounded text-slate-300 hover:text-pickle-green transition-colors" title="Rename group">
                <Pencil size={11} />
              </button>
              {matchCount > 0 && (
                <span className="text-xs font-medium bg-pickle-green/10 text-pickle-green rounded-full px-2 py-0.5">
                  {matchCount} match{matchCount !== 1 ? "es" : ""}
                </span>
              )}
              {matchCount > 1 && onShuffleMatches && (
                <button
                  onClick={onShuffleMatches}
                  className="flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium text-slate-500 border border-slate-200 hover:bg-slate-100 hover:text-pickle-green transition-colors"
                  title="Shuffle match order for this group"
                >
                  <Shuffle size={10} /> Shuffle Order
                </button>
              )}
            </div>
          )}
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <span className="text-xs text-slate-400 font-medium">{partners.length} teams</span>
          <button
            onClick={() => onDeleteGroup(group.id)}
            className="p-1 rounded text-slate-300 hover:text-red-500 hover:bg-red-50"
            title="Delete group"
          >
            <Trash2 size={12} />
          </button>
        </div>
      </div>

      {partners.length === 0 ? (
        <p className="text-sm text-slate-400 italic px-4 py-4">No partners assigned yet.</p>
      ) : (
        <div className="p-3 grid grid-cols-2 gap-2">
          {partners.map((p) => (
            <div key={p.id} className="relative bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm hover:shadow-md transition-shadow">
              <div className="px-3 pt-2.5 pb-1.5 bg-pickle-green/5 border-b border-pickle-green/10">
                <p className="text-sm font-bold text-pickle-green leading-tight pr-6 truncate">{p.team_name}</p>
                {p.seed != null && (
                  <span className="absolute top-2 right-2 text-[9px] font-bold bg-pickle-green text-white rounded-full px-1.5 py-0.5">
                    #{p.seed}
                  </span>
                )}
              </div>
              <div className="px-3 py-2">
                <p className="text-sm text-slate-700 truncate leading-snug">{p.player_1_name || "—"}</p>
                <p className="text-sm text-slate-700 truncate leading-snug">{p.player_2_name || "—"}</p>
              </div>
              <button
                onClick={() => onUnassignPartner(p.id)}
                className="absolute bottom-2 right-2 text-slate-300 hover:text-red-400 text-base leading-none font-bold"
                title="Unassign"
              >
                ×
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── 2-step Clear Matches confirmation modal ──────────────────────────────────
function ClearMatchesModal({ divisionName, totalCount, hotCount, onConfirm, onCancel }) {
  const [step, setStep] = useState(1);

  if (step === 1) {
    return (
      <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onCancel} />
        <div className="relative bg-white rounded-xl shadow-2xl w-full max-w-sm">
          <div className="p-6 border-b border-slate-100 flex items-start justify-between">
            <div>
              <h2 className="text-lg font-bold text-slate-900">Clear All Matches?</h2>
              <p className="text-xs text-slate-400 mt-1">{divisionName}</p>
            </div>
            <button onClick={onCancel} className="p-1 rounded text-slate-400 hover:text-slate-600">
              <X size={16} />
            </button>
          </div>
          <div className="p-6 space-y-3">
            <p className="text-sm text-slate-700">
              This will permanently delete all <strong>{totalCount}</strong> generated match{totalCount !== 1 ? "es" : ""} for this division.
            </p>
            {hotCount > 0 && (
              <div className="flex items-start gap-2 p-3 bg-amber-50 border border-amber-200 rounded-lg">
                <AlertTriangle size={16} className="text-amber-500 mt-0.5 shrink-0" />
                <p className="text-xs text-amber-700">
                  <strong>{hotCount}</strong> match{hotCount !== 1 ? "es are" : " is"} currently <strong>in progress or completed</strong>. Results will be lost.
                </p>
              </div>
            )}
          </div>
          <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
            <button onClick={onCancel} className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100">
              Cancel
            </button>
            <button
              onClick={() => hotCount > 0 ? setStep(2) : onConfirm()}
              className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-red-500 hover:bg-red-600 shadow-sm"
            >
              {hotCount > 0 ? "Continue →" : "Clear All Matches"}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Step 2 — final warning for completed/in-progress matches
  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onCancel} />
      <div className="relative bg-white rounded-xl shadow-2xl w-full max-w-sm border-2 border-red-200">
        <div className="p-6 border-b border-red-100 flex items-start justify-between bg-red-50">
          <div className="flex items-center gap-2">
            <AlertTriangle size={20} className="text-red-500" />
            <h2 className="text-lg font-bold text-red-700">Final Warning</h2>
          </div>
          <button onClick={onCancel} className="p-1 rounded text-red-400 hover:text-red-600">
            <X size={16} />
          </button>
        </div>
        <div className="p-6">
          <p className="text-sm text-slate-700">
            You are about to permanently delete <strong>{hotCount}</strong> completed or in-progress match{hotCount !== 1 ? "es" : ""}. <span className="text-red-600 font-semibold">This cannot be undone.</span>
          </p>
          <p className="text-sm text-slate-500 mt-2">All scores and results will be lost.</p>
        </div>
        <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
          <button onClick={onCancel} className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100">
            Cancel
          </button>
          <button
            onClick={onConfirm}
            className="px-4 py-2 rounded-lg text-sm font-bold text-white bg-red-600 hover:bg-red-700 shadow-sm"
          >
            Yes, Delete Everything
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Main tab component ─────────────────────────────────────────────────────
export default function DivisionsGroupsTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getGroupsForDivision,
    getPartnersForDivision,
    getPartnersForGroup,
    getMatchesForGroup,
    matches,
    createDivision,
    updateDivision,
    deleteDivision,
    createGroup,
    updateGroup,
    deleteGroup,
    autoCreateGroups,
    assignPartnerToGroup,
    shuffleGroupAssignments,
    updatePartner,
    generateGroupMatches,
    generateAllDivisionMatches,
    clearMatchesForDivision,
    shuffleGroupMatchOrder,
  } = useTournamentState();

  const divisions = getDivisionsForTournament(tournament.id);
  const [selectedDivisionId, setSelectedDivisionId] = useState(divisions[0]?.id || null);

  const [addDivOpen, setAddDivOpen] = useState(false);
  const [editDiv, setEditDiv] = useState(null);
  const [deleteDiv, setDeleteDiv] = useState(null);
  const [newGroupName, setNewGroupName] = useState("");
  const [addGroupOpen, setAddGroupOpen] = useState(false);
  const [editGroupId, setEditGroupId] = useState(null);
  const [editGroupName, setEditGroupName] = useState("");
  const [clearDivision, setClearDivision] = useState(null); // { id, name, totalCount, hotCount }

  const selectedDivision = divisions.find((d) => d.id === selectedDivisionId);
  const divGroups = selectedDivisionId ? getGroupsForDivision(selectedDivisionId) : [];
  const divPartners = selectedDivisionId ? getPartnersForDivision(selectedDivisionId) : [];
  const unassignedPartners = divPartners.filter((p) => !p.group_id && !p.withdrawn);

  // Division-level match stats
  const divMatches = useMemo(() => {
    if (!selectedDivisionId) return [];
    return Object.values(matches).filter(
      (m) => m.division_id === selectedDivisionId && m.phase === "group_stage"
    );
  }, [matches, selectedDivisionId]);

  const hasGeneratedMatches = divMatches.length > 0;
  const hotMatchCount = useMemo(
    () => divMatches.filter((m) => ["completed", "in_progress"].includes(m.status)).length,
    [divMatches]
  );

  const suggestedGroupCount = selectedDivision
    ? suggestGroupCount(divPartners.length, selectedDivision.max_group_size)
    : 1;

  const seededPartners = [...divPartners]
    .filter((p) => p.seed != null && !p.withdrawn)
    .sort((a, b) => a.seed - b.seed);
  const canSnakeSeed = seededPartners.length >= 2 && divGroups.length >= 2;

  const handleAddDivision = (data) => {
    const id = createDivision(tournament.id, data);
    setAddDivOpen(false);
    setSelectedDivisionId(id);
    toast.success("Division created.");
  };

  const handleEditDivision = (data) => {
    updateDivision(editDiv.id, data);
    setEditDiv(null);
    toast.success("Division updated.");
  };

  const handleDeleteDivision = () => {
    const remaining = divisions.filter((d) => d.id !== deleteDiv.id);
    deleteDivision(deleteDiv.id);
    setDeleteDiv(null);
    setSelectedDivisionId(remaining[0]?.id || null);
    toast.success("Division deleted.");
  };

  const handleAddGroup = (e) => {
    e.preventDefault();
    if (!newGroupName.trim() || !selectedDivisionId) return;
    createGroup(selectedDivisionId, newGroupName.trim(), tournament.id);
    setNewGroupName("");
    setAddGroupOpen(false);
    toast.success("Group created.");
  };

  const handleAutoGroups = () => {
    if (!selectedDivisionId) return;
    autoCreateGroups(selectedDivisionId, suggestedGroupCount, tournament.id);
    toast.success(`${suggestedGroupCount} group(s) created.`);
  };

  const handleDeleteGroup = (groupId) => {
    deleteGroup(groupId);
    toast.success("Group deleted.");
  };

  const handleRenameGroup = (groupId, name) => {
    if (!name.trim()) return;
    updateGroup(groupId, { name: name.trim() });
    setEditGroupId(null);
    toast.success("Group renamed.");
  };

  const handleChangeFormat = (newFormat) => {
    if (!selectedDivisionId) return;
    updateDivision(selectedDivisionId, { format: newFormat });
  };

  const handleChangeAdvanceCount = (delta) => {
    if (!selectedDivisionId) return;
    const current = selectedDivision?.advance_count ?? 2;
    updateDivision(selectedDivisionId, { advance_count: Math.max(1, current + delta) });
  };

  const handleUnassignPartner = (partnerId) => {
    updatePartner(partnerId, { group_id: null });
  };

  const handleAssignToGroup = (partnerId, groupId) => {
    assignPartnerToGroup(partnerId, groupId);
  };

  const handleShuffle = () => {
    if (!selectedDivisionId) return;
    shuffleGroupAssignments(selectedDivisionId);
  };

  const handleSnakeSeed = () => {
    if (!canSnakeSeed) return;
    const assignments = snakeSeedPartners(seededPartners, divGroups);
    Object.entries(assignments).forEach(([partnerId, groupId]) => {
      assignPartnerToGroup(partnerId, groupId);
    });
    toast.success(`${seededPartners.length} seeded partners distributed (snake draft).`);
  };

  const handleGenerateDivisionMatches = () => {
    if (!selectedDivisionId) return;
    generateAllDivisionMatches(selectedDivisionId);
  };

  const handleGenerateGroupMatches = (groupId) => {
    generateGroupMatches(groupId);
  };

  const handleOpenClear = () => {
    if (!selectedDivisionId || divMatches.length === 0) return;
    setClearDivision({
      id: selectedDivisionId,
      name: selectedDivision?.name || "Division",
      totalCount: divMatches.length,
      hotCount: hotMatchCount,
    });
  };

  const handleConfirmClear = () => {
    if (!clearDivision) return;
    clearMatchesForDivision(clearDivision.id);
    setClearDivision(null);
    toast.success("All matches cleared.");
  };

  return (
    <div className="p-4 md:p-6 space-y-4">
      <div className="flex flex-col md:flex-row gap-4">
        {/* ── Division list panel ── */}
        <div className="md:w-64 shrink-0">
          <SurfaceCard
            title="Divisions"
            actions={
              <button
                onClick={() => setAddDivOpen(true)}
                className="flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium text-white bg-pickle-green hover:bg-pickle-green/90"
              >
                <Plus size={12} /> Add
              </button>
            }
          >
            <div className="px-2 pb-2 space-y-1">
              {divisions.length === 0 && (
                <p className="text-xs text-slate-400 px-2 py-3 text-center">No divisions yet.</p>
              )}
              {divisions.map((d) => (
                <div
                  key={d.id}
                  onClick={() => setSelectedDivisionId(d.id)}
                  className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer transition-colors ${
                    selectedDivisionId === d.id
                      ? "bg-pickle-green text-white"
                      : "hover:bg-slate-100 text-slate-700"
                  }`}
                >
                  <div className="min-w-0">
                    <div className="text-sm font-semibold truncate">{d.name}</div>
                    <div className={`text-xs flex items-center gap-1.5 mt-0.5 ${selectedDivisionId === d.id ? "text-white/70" : "text-slate-400"}`}>
                      <span>{getPartnersForDivision(d.id).length} partners</span>
                      <span className={`text-[10px] font-medium border rounded px-1 py-px ${
                        selectedDivisionId === d.id
                          ? "border-white/30 text-white/80"
                          : FORMAT_CHIP_COLORS[d.format] || "bg-slate-50 text-slate-500 border-slate-200"
                      }`}>
                        {FORMAT_LABELS[d.format] || "RR"}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-1 shrink-0 ml-2">
                    <button
                      onClick={(e) => { e.stopPropagation(); setEditDiv(d); }}
                      className={`p-1 rounded ${selectedDivisionId === d.id ? "text-white/70 hover:text-white" : "text-slate-300 hover:text-pickle-green"}`}
                    >
                      <Pencil size={11} />
                    </button>
                    <button
                      onClick={(e) => { e.stopPropagation(); setDeleteDiv(d); }}
                      className={`p-1 rounded ${selectedDivisionId === d.id ? "text-white/70 hover:text-white" : "text-slate-300 hover:text-red-500"}`}
                    >
                      <Trash2 size={11} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </SurfaceCard>
        </div>

        {/* ── Groups panel ── */}
        <div className="flex-1 min-w-0">
          {!selectedDivision ? (
            <div className="text-center py-16 text-slate-400 text-sm">
              Select a division to manage its groups.
            </div>
          ) : (
            <SurfaceCard
              title={`${selectedDivision.name} — Groups`}
              actions={
                <div className="flex items-center gap-2 flex-wrap justify-end">
                  {divGroups.length === 0 && (
                    <button
                      onClick={handleAutoGroups}
                      className="flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium text-pickle-green border border-pickle-green/30 hover:bg-pickle-green/5"
                      title={`Auto-create ${suggestedGroupCount} groups`}
                    >
                      Auto ({suggestedGroupCount})
                    </button>
                  )}
                  {canSnakeSeed && (
                    <button
                      onClick={handleSnakeSeed}
                      className="flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium text-slate-600 border border-slate-200 hover:bg-slate-100"
                      title="Distribute seeded partners using snake-draft order"
                    >
                      Snake Seed
                    </button>
                  )}
                  <button
                    onClick={handleShuffle}
                    className="flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium text-slate-600 border border-slate-200 hover:bg-slate-100 disabled:opacity-40"
                    disabled={divGroups.length === 0}
                    title="Shuffle partner assignments randomly"
                  >
                    <Shuffle size={11} /> Shuffle
                  </button>
                  <button
                    onClick={() => setAddGroupOpen(true)}
                    className="flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium text-white bg-pickle-green hover:bg-pickle-green/90"
                  >
                    <Plus size={12} /> Group
                  </button>
                </div>
              }
            >
              <div className="px-4 pb-4 space-y-3">
                {/* ── Format + Advance settings bar ── */}
                <div className="flex flex-wrap items-center gap-3 py-2.5 border-b border-slate-100">
                  <span className="text-xs font-semibold text-slate-600 shrink-0">Format:</span>
                  {[
                    { v: "round_robin", l: "Round Robin" },
                    { v: "single_elimination", l: "Single Elim" },
                  ].map((o) => (
                    <button
                      key={o.v}
                      onClick={() => handleChangeFormat(o.v)}
                      className={`px-2.5 py-1 rounded-full text-xs font-semibold border transition-colors ${
                        selectedDivision?.format === o.v
                          ? "bg-pickle-green text-white border-pickle-green"
                          : "border-slate-200 text-slate-500 hover:border-pickle-green/50 hover:text-pickle-green"
                      }`}
                    >
                      {o.l}
                    </button>
                  ))}
                  {selectedDivision?.format !== "single_elimination" && (
                    <div className="ml-auto flex items-center gap-1.5 shrink-0">
                      <span className="text-xs text-slate-500">Advance:</span>
                      <div className="flex items-center gap-1">
                        <button onClick={() => handleChangeAdvanceCount(-1)} className="w-5 h-5 flex items-center justify-center rounded border border-slate-200 text-slate-500 hover:bg-slate-100 text-xs leading-none">−</button>
                        <span className="w-6 text-center text-xs font-bold text-slate-800">{selectedDivision?.advance_count ?? 2}</span>
                        <button onClick={() => handleChangeAdvanceCount(1)} className="w-5 h-5 flex items-center justify-center rounded border border-slate-200 text-slate-500 hover:bg-slate-100 text-xs leading-none">+</button>
                      </div>
                      <span className="text-xs text-slate-400">per group</span>
                    </div>
                  )}
                </div>

                {/* ── Division-level Generate / Clear bar ── */}
                {divGroups.length > 0 && (
                  <div className="flex items-center justify-between gap-2 py-2 border-b border-slate-100">
                    <div className="flex items-center gap-2">
                      {hasGeneratedMatches ? (
                        <>
                          <span className="text-xs font-semibold text-pickle-green bg-pickle-green/10 rounded-full px-2.5 py-1">
                            ✓ {divMatches.length} matches generated
                          </span>
                          <span className="text-xs text-slate-400 italic">Clear to regenerate</span>
                        </>
                      ) : (
                        <button
                          onClick={handleGenerateDivisionMatches}
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm"
                          title={`Generate ${FORMAT_LABELS[selectedDivision?.format || "round_robin"]} matches for all groups`}
                        >
                          <Zap size={12} />
                          Generate Matches ({FORMAT_LABELS[selectedDivision?.format || "round_robin"]})
                        </button>
                      )}
                    </div>
                    {hasGeneratedMatches && (
                      <button
                        onClick={handleOpenClear}
                        className="flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-red-600 border border-red-200 hover:bg-red-50 transition-colors"
                        title="Clear all generated matches for this division"
                      >
                        <Trash2 size={11} />
                        Clear All Matches
                      </button>
                    )}
                  </div>
                )}

                {/* ── Add group inline form ── */}
                {addGroupOpen && (
                  <form onSubmit={handleAddGroup} className="flex gap-2">
                    <input
                      autoFocus
                      className="flex-1 border border-slate-200 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
                      placeholder="Group name (e.g. Group A)"
                      value={newGroupName}
                      onChange={(e) => setNewGroupName(e.target.value)}
                    />
                    <button type="submit" className="px-3 py-1.5 rounded-lg text-sm font-medium text-white bg-pickle-green">
                      Add
                    </button>
                    <button
                      type="button"
                      onClick={() => setAddGroupOpen(false)}
                      className="px-3 py-1.5 rounded-lg text-sm text-slate-600 hover:bg-slate-100"
                    >
                      Cancel
                    </button>
                  </form>
                )}

                {divGroups.length === 0 && !addGroupOpen && (
                  <div className="text-center py-8 text-slate-400 text-sm">
                    No groups yet.{" "}
                    <button onClick={() => setAddGroupOpen(true)} className="text-pickle-green underline">
                      Create one
                    </button>
                  </div>
                )}

                {divGroups.map((g) => {
                  const groupMatchCount = getMatchesForGroup(g.id).length;
                  return (
                    <GroupCards
                      key={g.id}
                      group={g}
                      partners={getPartnersForGroup(g.id).filter((p) => !p.withdrawn)}
                      matchCount={groupMatchCount}
                      onDeleteGroup={handleDeleteGroup}
                      onUnassignPartner={handleUnassignPartner}
                      onShuffleMatches={groupMatchCount > 1 ? () => shuffleGroupMatchOrder(g.id) : null}
                      isEditing={editGroupId === g.id}
                      editName={editGroupId === g.id ? editGroupName : g.name}
                      onStartEdit={() => { setEditGroupId(g.id); setEditGroupName(g.name); }}
                      onEditChange={setEditGroupName}
                      onSaveEdit={() => handleRenameGroup(g.id, editGroupName)}
                      onCancelEdit={() => setEditGroupId(null)}
                    />
                  );
                })}

                {/* ── Unassigned partners ── */}
                {unassignedPartners.length > 0 && divGroups.length > 0 && (
                  <div>
                    <p className="text-xs font-semibold text-amber-600 mb-2 flex items-center gap-1">
                      <Users size={12} /> Unassigned ({unassignedPartners.length})
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {unassignedPartners.map((p) => (
                        <div
                          key={p.id}
                          className="flex items-center gap-1 border border-amber-200 bg-amber-50 rounded-full px-2 py-0.5"
                        >
                          {p.seed != null && (
                            <span className="text-[9px] font-bold text-amber-600">#{p.seed}</span>
                          )}
                          <span className="text-xs text-amber-700">{p.team_name}</span>
                          <select
                            className="text-xs border-0 bg-transparent text-amber-600 focus:outline-none"
                            defaultValue=""
                            onChange={(e) => {
                              if (e.target.value) handleAssignToGroup(p.id, e.target.value);
                            }}
                          >
                            <option value="">Assign…</option>
                            {divGroups.map((g) => (
                              <option key={g.id} value={g.id}>{g.name}</option>
                            ))}
                          </select>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </SurfaceCard>
          )}
        </div>
      </div>

      {/* ── Modals ── */}
      {addDivOpen && (
        <DivisionFormModal onSave={handleAddDivision} onClose={() => setAddDivOpen(false)} />
      )}
      {editDiv && (
        <DivisionFormModal division={editDiv} onSave={handleEditDivision} onClose={() => setEditDiv(null)} />
      )}
      <ConfirmationModal
        isOpen={!!deleteDiv}
        title={`Delete "${deleteDiv?.name}"?`}
        message="This removes all groups in this division and unassigns all partners from it."
        confirmLabel="Delete Division"
        isDestructive
        onConfirm={handleDeleteDivision}
        onCancel={() => setDeleteDiv(null)}
      />
      {clearDivision && (
        <ClearMatchesModal
          divisionName={clearDivision.name}
          totalCount={clearDivision.totalCount}
          hotCount={clearDivision.hotCount}
          onConfirm={handleConfirmClear}
          onCancel={() => setClearDivision(null)}
        />
      )}
    </div>
  );
}
