import { loadState, saveState } from "./storage";

export const seedDemoData = () => {
    const now = Date.now();

    // Create 12 Demo Players
    const players = Array.from({ length: 12 }, (_, i) => ({
        id: `demo-player-${i + 1}`,
        name: `Player ${i + 1}`,
        waitStart: Date.now() - Math.floor(Math.random() * 3600000), // waiting up to 60 mins
        level: i % 4 === 0 ? "Advance" : i % 3 === 0 ? "High Intermediate" : i % 2 === 0 ? "Low Intermediate" : "Beginner",
        gender: i % 2 === 0 ? "M" : "F",
        status: "waiting", // Default to waiting
        paymentStatus: "paid",
        createdAt: now,
        arrivalTime: now - Math.floor(Math.random() * 60 * 60 * 1000), // Arrived 0-60 mins ago
        matches: Math.floor(Math.random() * 3), // 0-2 matches already played
        longestWaitTimeMs: 0,
    }));

    // Create 3 Courts
    const courts = [1, 2, 3].map(id => ({
        id,
        name: `Court ${id}`,
        players: [],
        teamGreen: [],
        teamBlue: [],
        timer: { startTime: null, accumulatedMs: 0, isPaused: false },
        currentMatchId: null,
        locked: false,
    }));

    // Create 4 Calendar Courts (Separate from Queue Courts)
    const calendarCourts = [1, 2, 3, 4].map(id => ({
        id,
        name: `Court ${id}`,
        players: [],
        teamGreen: [],
        teamBlue: [],
        timer: { startTime: null, accumulatedMs: 0, isPaused: false },
        currentMatchId: null,
        locked: false,
    }));

    return {
        players,
        courts,
        calendarCourts,
        matchQueue: [],
        matches: [],
        opSessions: [],
        bookings: [],
        currentOpSession: {
            id: `demo-session-${now}`,
            name: "Demo Session",
            startedAt: now,
            status: "active"
        }
    };
};

export const resetDemoData = () => {
    return seedDemoData();
};
export const seedIfEmpty = () => {
    try {
        // State is hydrated by bootstrapStorage() before this runs; loadState()
        // reads the in-memory cache (IndexedDB or localStorage fallback).
        const stored = loadState();
        if (!stored) {
            console.log("No state found. Initializing with default defaults...");

            // CLEAN STATE
            const cleanState = {
                players: [],
                matchQueue: [],
                matches: [],
                opSessions: [],
                bookings: [],
                currentOpSession: null,
                isDemoMode: false, // Default OFF

                // 4 Default Queue Courts
                courts: [1, 2, 3, 4].map(id => ({
                    id,
                    name: `Court ${id}`,
                    players: [],
                    teamGreen: [],
                    teamBlue: [],
                    timer: { startTime: null, accumulatedMs: 0, isPaused: false },
                    currentMatchId: null,
                    locked: false,
                })),

                // 4 Default Calendar Courts
                calendarCourts: [1, 2, 3, 4].map(id => ({
                    id,
                    name: `Court ${id}`,
                    players: [],
                    teamGreen: [],
                    teamBlue: [],
                    timer: { startTime: null, accumulatedMs: 0, isPaused: false },
                    currentMatchId: null,
                    locked: false,
                })),

                meta: { seededAt: Date.now(), seedLabel: "Clean Init" }
            };

            saveState(cleanState);
        }
    } catch (e) {
        console.error("Failed to seedIfEmpty:", e);
    }
};

