import { useState, useEffect, useCallback } from "react";
import { loadTournamentState } from "../storage/tournamentStorage";

const STORAGE_KEY = "picklestudioTournaments";

export default function useTournamentDisplay(tournamentId) {
  const [state, setState] = useState(() => loadTournamentState());

  useEffect(() => {
    // Cross-tab storage event (fires when another tab writes)
    const onStorage = (e) => {
      if (e.key === STORAGE_KEY && e.newValue) {
        try {
          const fresh = loadTournamentState();
          setState(fresh);
        } catch {}
      }
    };
    window.addEventListener("storage", onStorage);

    // Polling fallback every 5s (safety net)
    const interval = setInterval(() => {
      setState(loadTournamentState());
    }, 5000);

    return () => {
      window.removeEventListener("storage", onStorage);
      clearInterval(interval);
    };
  }, []);

  const tournament = tournamentId ? (state.tournaments?.[tournamentId] || null) : null;

  const getDivisionsForTournament = useCallback(
    (tid) => Object.values(state.divisions || {}).filter((d) => d.tournament_id === tid),
    [state.divisions]
  );
  const getGroupsForDivision = useCallback(
    (did) => Object.values(state.groups || {}).filter((g) => g.division_id === did),
    [state.groups]
  );
  const getMatchesForTournament = useCallback(
    (tid) => Object.values(state.matches || {}).filter((m) => m.tournament_id === tid),
    [state.matches]
  );
  const getPartnersForTournament = useCallback(
    (tid) => Object.values(state.partners || {}).filter((p) => p.tournament_id === tid),
    [state.partners]
  );
  const getPartnersForGroup = useCallback(
    (gid) => Object.values(state.partners || {}).filter((p) => p.group_id === gid),
    [state.partners]
  );

  return {
    tournament,
    tournaments: state.tournaments || {},
    divisions: state.divisions || {},
    groups: state.groups || {},
    partners: state.partners || {},
    matches: state.matches || {},
    getDivisionsForTournament,
    getGroupsForDivision,
    getMatchesForTournament,
    getPartnersForTournament,
    getPartnersForGroup,
  };
}
