const STORAGE_KEY = "picklestudioTournaments";
const STORAGE_VERSION = 5;

const getStorage = () => {
  if (typeof window !== "undefined" && window.localStorage) {
    return window.localStorage;
  }
  return null;
};

const emptyState = () => ({
  version: STORAGE_VERSION,
  savedAt: null,
  tournaments: {},
  divisions: {},
  groups: {},
  partners: {},
  matches: {},
});

/**
 * Migrate persisted data from an older schema version to the current one.
 * Each case falls through to apply all subsequent migrations in order.
 *
 * Version history:
 *   1 → 2: Added `courts` field to tournaments (default 4 courts).
 *   2 → 3: Added extended player detail fields to partners (DOB, gender, phone, rating).
 *   3 → 4: Added `format` field to divisions (default "round_robin").
 *          Also removes legacy `format` field from tournament objects if present
 *          (format moved from tournament-level to division-level).
 *   4 → 5: Added sponsors array and display_settings to tournaments.
 */
function migrate(data, fromVersion) {
  const state = { ...data };

  if (fromVersion < 2) {
    // v1 → v2: Add `courts` array to any tournament that lacks it.
    const defaultCourts = ["Court 1", "Court 2", "Court 3", "Court 4"];
    const updated = {};
    Object.entries(state.tournaments || {}).forEach(([id, t]) => {
      updated[id] = t.courts ? t : { ...t, courts: defaultCourts };
    });
    state.tournaments = updated;
  }

  if (fromVersion < 3) {
    // v2 → v3: Add extended player detail fields to partners that lack them.
    const playerDetailDefaults = {
      player_1_dob: null,
      player_2_dob: null,
      player_1_gender: null,
      player_2_gender: null,
      player_1_phone: null,
      player_2_phone: null,
      player_1_rating: null,
      player_2_rating: null,
    };
    const updated = {};
    Object.entries(state.partners || {}).forEach(([id, p]) => {
      updated[id] = { ...playerDetailDefaults, ...p };
    });
    state.partners = updated;
  }

  if (fromVersion < 4) {
    // v3 → v4: Add `format` field to divisions (default "round_robin").
    // Also strips the legacy `format` field from tournaments (format moved to division level).
    const updatedDivisions = {};
    Object.entries(state.divisions || {}).forEach(([id, d]) => {
      updatedDivisions[id] = d.format ? d : { ...d, format: "round_robin" };
    });
    state.divisions = updatedDivisions;

    const updatedTournaments = {};
    Object.entries(state.tournaments || {}).forEach(([id, t]) => {
      // eslint-disable-next-line no-unused-vars
      const { format: _removed, ...rest } = t;
      updatedTournaments[id] = rest;
    });
    state.tournaments = updatedTournaments;
  }

  if (fromVersion < 5) {
    // v4 → v5: Add sponsors array and display_settings to tournaments.
    const updatedTournaments = {};
    Object.entries(state.tournaments || {}).forEach(([id, t]) => {
      updatedTournaments[id] = {
        ...t,
        sponsors: t.sponsors || [],
        display_settings: t.display_settings || {
          slideshow_interval: 15,
          sponsor_slideshow_interval: 8,
          transition_enabled: true,
        },
      };
    });
    state.tournaments = updatedTournaments;
  }

  state.version = STORAGE_VERSION;
  return state;
}

export function loadTournamentState() {
  try {
    const storage = getStorage();
    if (!storage) return emptyState();
    const saved = storage.getItem(STORAGE_KEY);
    if (!saved) return emptyState();
    const parsed = JSON.parse(saved);
    const storedVersion = parsed.version ?? 1;

    // Run migrations when stored data is older than current schema.
    const migrated =
      storedVersion < STORAGE_VERSION
        ? migrate({ ...emptyState(), ...parsed }, storedVersion)
        : { ...emptyState(), ...parsed };

    return migrated;
  } catch (err) {
    console.error("Failed to load tournament state", err);
    return emptyState();
  }
}

export function saveTournamentState(state = {}) {
  try {
    const storage = getStorage();
    if (!storage) {
      console.warn("Local storage unavailable; skipping saveTournamentState.");
      return null;
    }
    const payload = {
      version: STORAGE_VERSION,
      savedAt: new Date().toISOString(),
      tournaments: state.tournaments || {},
      divisions: state.divisions || {},
      groups: state.groups || {},
      partners: state.partners || {},
      matches: state.matches || {},
    };
    storage.setItem(STORAGE_KEY, JSON.stringify(payload));
    return payload;
  } catch (err) {
    console.error("Failed to save tournament state", err);
    return null;
  }
}

export function clearTournamentState() {
  try {
    const storage = getStorage();
    if (!storage) return;
    storage.removeItem(STORAGE_KEY);
  } catch (err) {
    console.error("Failed to clear tournament state", err);
  }
}
