import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Plus, Trophy } from "lucide-react";
import { useTournamentState } from "./providers/TournamentStateProvider";
import TournamentCard from "./components/TournamentCard";
import TournamentModal from "./components/TournamentModal";
import ConfirmationModal from "../../common/components/ConfirmationModal";

export default function TournamentHubPage() {
  const {
    allTournaments,
    tournaments,
    createTournament,
    deleteTournament,
    getPartnersForTournament,
    getMatchesForTournament,
  } = useTournamentState();
  const navigate = useNavigate();

  const [createOpen, setCreateOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);

  const handleCreate = (data) => {
    const id = createTournament(data);
    setCreateOpen(false);
    navigate(`/tournament/${id}`);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    deleteTournament(deleteTarget.id);
    setDeleteTarget(null);
  };

  return (
    <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Trophy className="text-pickle-green" size={28} />
          <h1 className="font-display text-3xl text-pickle-green">Tournaments</h1>
        </div>
        <button
          onClick={() => setCreateOpen(true)}
          className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm transition-colors"
        >
          <Plus size={16} />
          New Tournament
        </button>
      </div>

      {/* Empty state */}
      {allTournaments.length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 gap-4 text-center">
          <Trophy size={48} className="text-slate-200" />
          <div>
            <p className="text-slate-500 font-medium">No tournaments yet</p>
            <p className="text-slate-400 text-sm mt-1">Create your first tournament to get started</p>
          </div>
          <button
            onClick={() => setCreateOpen(true)}
            className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm transition-colors"
          >
            <Plus size={16} />
            New Tournament
          </button>
        </div>
      )}

      {/* Tournament grid */}
      {allTournaments.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {allTournaments.map((t) => {
            const tournamentPartners = getPartnersForTournament(t.id);
            const tournamentMatches = getMatchesForTournament(t.id);
            const completedMatches = tournamentMatches.filter(
              (m) => m.status === "completed" || m.status === "bye"
            );
            return (
              <TournamentCard
                key={t.id}
                tournament={t}
                partnerCount={tournamentPartners.length}
                matchCount={tournamentMatches.length}
                completedCount={completedMatches.length}
                onClick={() => navigate(`/tournament/${t.id}`)}
                onDelete={() => setDeleteTarget(t)}
              />
            );
          })}
        </div>
      )}

      {/* Create modal */}
      {createOpen && (
        <TournamentModal onSave={handleCreate} onClose={() => setCreateOpen(false)} />
      )}

      {/* Delete confirmation */}
      <ConfirmationModal
        isOpen={!!deleteTarget}
        title={`Delete "${deleteTarget?.name}"?`}
        message="This will permanently delete all divisions, groups, partners, and matches for this tournament. This cannot be undone."
        confirmLabel="Delete Tournament"
        isDestructive
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
      />
    </div>
  );
}
